function tractorFuelLoadFactor(requiredHp,tractorHp){const load=clamp((Number(requiredHp)||0)/Math.max(1,Number(tractorHp)||1),0,1),pts=[[0,.18],[.25,.33],[.5,.55],[.75,.80],[1,1]];for(let i=1;i<pts.length;i++){if(load<=pts[i][0]){const [x0,y0]=pts[i-1],[x1,y1]=pts[i],t=(load-x0)/(x1-x0);return y0+(y1-y0)*t;}}return 1;}
function machineWorkFuelLph(m){return Math.max(0,Number(m?.workFuelLph??m?.fuelLph)||0)}
function machineRoadFuelLph(m){if(!m)return 0;if(Number.isFinite(Number(m.roadFuelLph)))return Math.max(0,Number(m.roadFuelLph));const work=machineWorkFuelLph(m);if(m.type==='truck')return work;const ratio=m.type==='tractor'?({domestic_used:.48,domestic_new:.44,foreign_used:.45,foreign_new:.42}[m.segment]||.38):m.type==='combine'?({domestic_used:.36,domestic_new:.34,foreign_used:.34,foreign_new:.32}[m.segment]||.30):.42;return work*ratio;}
function tractorImplementFuelLph(tractor,implement){const req=Math.max(1,Number(implement?.requiredHp)||1),hp=Math.max(1,Number(tractor?.hp)||1),base=(machineWorkFuelLph(tractor)||20)*tractorFuelLoadFactor(req,hp),reserve=Math.max(0,hp/req-1),oversize=1+Math.min(.16,reserve*.09);return base*oversize;}
