const ROTATION_TRAITS={
  winter_wheat:{family:'small_grain'},spring_wheat:{family:'small_grain'},barley:{family:'small_grain'},spring_oats:{family:'small_grain'},winter_rye:{family:'small_grain'},spring_rye:{family:'small_grain'},
  oil_flax:{family:'flax'},buckwheat:{family:'buckwheat'},
  corn:{family:'corn'},sunflower:{family:'sunflower',sclerotiniaHost:true},rapeseed:{family:'brassica',sclerotiniaHost:true},
  soybean:{family:'pulse',nitrogenFixer:true,sclerotiniaHost:true},peas:{family:'pulse',nitrogenFixer:true,sclerotiniaHost:true},
  sugar_beet:{family:'beet'},potato:{family:'potato'},perennial_grass:{family:'grass'},
  alfalfa:{family:'forage_legume',nitrogenFixer:true},clover:{family:'forage_legume',nitrogenFixer:true}
};
function rotationTrait(k){return ROTATION_TRAITS[k]||{family:CROPS[k]?.group||'other'};}
function nitrogenFixingCrop(k){return !!rotationTrait(k).nitrogenFixer;}
function sclerotiniaHost(k){return !!rotationTrait(k).sclerotiniaHost;}
function rotationPredecessorFactor(prevKey,cropKey){if(!prevKey||!CROPS[prevKey]||!CROPS[cropKey])return 1.02;if(prevKey===cropKey)return .78;const a=rotationTrait(prevKey),b=rotationTrait(cropKey);if(a.family==='small_grain'&&b.family==='small_grain')return .90;if(a.family==='corn'&&b.family==='small_grain')return .92;if(sclerotiniaHost(prevKey)&&sclerotiniaHost(cropKey))return .91;if(a.family==='pulse'&&b.family==='pulse')return .94;return 1;}

function cropNames(keys){return (keys||[]).map(k=>CROPS[k]?.label||k).join(' → ')}
function rotationGuideHtml(k){const g=ROTATION_GUIDE[k];if(!g)return'';return `<div class="rotation-hint"><div class="small"><b>Лучшие предшественники:</b> ${cropNames(g.predecessors)}</div><div class="small"><b>Хороший следующий выбор:</b> ${cropNames(g.next)}</div><div class="muted tiny" style="margin-top:5px">Пример севооборота: ${cropNames(g.example)}. Это подсказка, а не жёсткое правило: учитывайте состояние поля, сроки и экономику.</div></div>`;}

