function harvestMoisture(field,crop,at=state.gameTime){if(field?.grainWindrow&&field.grainWindrow.crop===crop)return grainWindrowMoistureNow(field.grainWindrow,at);const spec=CROP_MOISTURE[crop];if(!spec||spec.safe==null)return null;let recent=0,cloud=0;for(let i=0;i<3;i++){const w=weatherFor(dayStart(at)-i*DAY);recent+=w.precip*(i===0?.65:i===1?.25:.10);cloud+=w.cloud/3;}const c=CROPS[crop],base=crop==='corn'?4:c.group==='oilseed'?1.1:c.group==='legume'?1.5:1.8;const fieldWet=Math.max(0,(Number(field?.moisture)||55)-55)*.045;let v=spec.safe+base+recent*.42+Math.max(0,cloud-45)*.025+fieldWet;if(recent<.5&&cloud<45)v-=1.2;const h=field&&field.crop?harvestWindowInfo(field):null;if(h&&at>h.optimalEnd)v-=Math.min(1.8,daysBetween(h.optimalEnd,at)*.05);return Math.round(clamp(v,spec.safe-.8,spec.max)*10)/10}
const QUALITY_POINT_RULES={near:{min:0,low:.96,high:1.02},mid:{min:45,low:.97,high:1.05},far:{min:60,low:.985,high:1.065},root_near:{min:0,low:.95,high:1.02},root_mid:{min:45,low:.97,high:1.06},root_far:{min:62,low:.985,high:1.075},forage_near:{min:0,low:.97,high:1.03},forage_mid:{min:40,low:.98,high:1.06},forage_far:{min:55,low:.99,high:1.075}};
function qualityProfile(crop,score){score=clamp(Number(score)||70,0,100);if(crop==='hay'||crop==='meadow_hay')return{metric:'Кормовая ценность',value:score,unit:'/100',label:score>=80?'высокая':score>=60?'стандарт':'пониженная'};if(crop==='straw')return{metric:'Сохранность',value:score,unit:'/100',label:score>=75?'чистая сухая':score>=55?'стандарт':'пониженная'};if(['winter_wheat','spring_wheat','winter_rye','spring_rye'].includes(crop)){const protein=9.0+score*.05,grade=score>=78?'продовольственное':score>=62?'стандарт':'фураж';return{metric:'Белок',value:protein,unit:'%',label:grade};}if(crop==='spring_oats'){const nature=430+score*1.25;return{metric:'Натура',value:nature,unit:' г/л',label:score>=75?'высокая':score>=55?'стандарт':'пониженная'};}if(crop==='oil_flax'){const oil=35+score*.11;return{metric:'Масличность',value:oil,unit:'%',label:score>=76?'высокая':score>=56?'стандарт':'пониженная'};}if(crop==='buckwheat'){const purity=91+score*.07;return{metric:'Чистота',value:purity,unit:'%',label:score>=75?'крупяное качество':score>=55?'стандарт':'пониженное'};}if(crop==='sunflower'){const oil=38+score*.15;return{metric:'Масличность',value:oil,unit:'%',label:score>=78?'высокая масличность':score>=58?'стандарт':'пониженная масличность'};}if(crop==='rapeseed'){const oil=36+score*.12;return{metric:'Масличность',value:oil,unit:'%',label:score>=76?'высокая':score>=56?'стандарт':'пониженная'};}if(crop==='soybean'){const protein=30+score*.10;return{metric:'Белок',value:protein,unit:'%',label:score>=75?'высокобелковая':score>=55?'стандарт':'пониженный белок'};}if(crop==='peas'){const purity=90+score*.09,damage=Math.max(.5,10-score*.09);return{metric:'Чистота',value:purity,unit:'%',secondary:`Повреждение ${num(damage,1)}%`,label:score>=75?'продовольственное':score>=55?'стандарт':'кормовое'};}if(crop==='sugar_beet'){const sugar=13+score*.07;return{metric:'Сахаристость',value:sugar,unit:'%',label:score>=75?'высокая':score>=55?'стандарт':'пониженная'};}if(crop==='potato'){const marketable=72+score*.24;return{metric:'Товарность',value:marketable,unit:'%',label:score>=78?'премиальный':score>=58?'стандарт':'переработка'};}const nature=(crop==='corn'?620:600)+score*(crop==='corn'?1.5:1.6);return{metric:'Натура',value:nature,unit:' г/л',label:score>=75?'высокое качество':score>=55?'стандарт':'пониженное качество'};}
function makeQuality(crop,score,source='harvest'){score=Math.round(clamp(Number(score)||70,0,100)*10)/10;return{score,source,...qualityProfile(crop,score)};}
function harvestQuality(field,crop,report,moisture,at=state.gameTime){const fs=report?.factors||[],keys=new Set(['weather','nutrition','ph','seedbed','compaction','weeds','protection','harvest']),sel=fs.filter(x=>keys.has(x.key)),mean=sel.length?sel.reduce((a,x)=>a+x.value,0)/sel.length:.9;let score=52+mean*38;const safe=cropSafeMoisture(crop);if(safe!=null&&Number.isFinite(Number(moisture)))score-=Math.max(0,Number(moisture)-safe)*1.2;const h=field?harvestWindowInfo(field):null;if(h&&at>h.optimalEnd)score-=Math.min(18,daysBetween(h.optimalEnd,at)*.45);if(field?.cropProtection){score-=Math.min(12,(Number(field.cropProtection.diseaseDamage)||0)*40);score-=Math.min(8,(Number(field.cropProtection.pestDamage)||0)*35);}return makeQuality(crop,score,'harvest');}
function lotQuality(l){if(!l.quality||!Number.isFinite(Number(l.quality.score)))l.quality=makeQuality(l.crop,70,'legacy');return l.quality;}
function qualityClass(score){score=Number(score)||0;return score>=80?'good':score>=60?'info':score>=45?'warn':'bad'}
function qualityWeighted(crop){const lots=(state.warehouse?.lots||[]).filter(l=>l.crop===crop&&(Number(l.tons)||0)>0);const assigned=lots.reduce((a,l)=>a+(Number(l.tons)||0),0),stock=Math.max(0,Number(state.warehouse?.stocks?.[crop])||0),unassigned=Math.max(0,stock-assigned);let total=unassigned*70,tons=unassigned;for(const l of lots){const t=Math.max(0,Number(l.tons)||0);total+=t*lotQuality(l).score;tons+=t;}return tons>0?total/tons:70;}

// 0.11.9.47 — feed-value foundation for future cattle rations. Values are on dry-matter basis.
const FEED_PROFILES={
 hay:{label:'Сено',dm:.86,me:8.6,cp:.12,qualityEnergySpan:1.15,qualityProteinSpan:.045},
 meadow_hay:{label:'Луговое сено',dm:.84,me:8.0,cp:.095,qualityEnergySpan:1.0,qualityProteinSpan:.035},
 straw:{label:'Солома',dm:.89,me:6.8,cp:.042,qualityEnergySpan:.45,qualityProteinSpan:.012},
 silage:{label:'Кукурузный силос',dm:.325,me:10.8,cp:.069,qualityEnergySpan:.9,qualityProteinSpan:.014}
};
function feedValue(crop,tons,quality=70,moisture=null){const key=crop==='corn_silage'?'silage':crop,p=FEED_PROFILES[key];if(!p)return null;const q=clamp(Number(quality)||70,0,100),dm=Number.isFinite(Number(moisture))?clamp(1-Number(moisture)/100,.08,.95):p.dm,shift=(q-70)/30,me=clamp(p.me+shift*p.qualityEnergySpan,p.me*.72,p.me*1.18),cp=clamp(p.cp+shift*p.qualityProteinSpan,.025,.22),asFed=Math.max(0,Number(tons)||0),dmT=asFed*dm;return{key,label:p.label,tons:asFed,dmPct:dm*100,dmT,me,cpPct:cp*100,proteinT:dmT*cp,energyGJ:dmT*me,quality:q};}
function feedValueForLot(l){if(!l||!FEED_PROFILES[l.crop])return null;return feedValue(l.crop,l.tons,lotQuality(l).score,l.moisture);}
function feedValueForSilage(b){if(!b||!b.fermented||Number(b.tons)<=0)return null;const q=clamp(Number(b.quality)||60,0,100);return feedValue('silage',b.tons,q,67.5);}
function feedBalanceSnapshot(){const items=[];for(const l of state.warehouse?.lots||[]){const x=feedValueForLot(l);if(x)items.push({...x,source:l.id||l.sectionId||'lot'});}for(const b of ensureSilageBunkers()){const x=feedValueForSilage(b);if(x)items.push({...x,source:b.id});}const total=items.reduce((a,x)=>({tons:a.tons+x.tons,dmT:a.dmT+x.dmT,proteinT:a.proteinT+x.proteinT,energyGJ:a.energyGJ+x.energyGJ}),{tons:0,dmT:0,proteinT:0,energyGJ:0}),byType={};for(const x of items){const a=byType[x.key]||(byType[x.key]={key:x.key,label:x.label,tons:0,dmT:0,proteinT:0,energyGJ:0,qualityWeighted:0});a.tons+=x.tons;a.dmT+=x.dmT;a.proteinT+=x.proteinT;a.energyGJ+=x.energyGJ;a.qualityWeighted+=x.quality*x.tons;}for(const a of Object.values(byType))a.quality=a.tons?a.qualityWeighted/a.tons:0;return{items,total,byType:Object.values(byType)};}
function feedBalanceHtml(){const f=feedBalanceSnapshot();return `<div class="card section-card"><div class="section-title"><h2>Кормовой баланс</h2><span class="pill">foundation .46</span></div><div class="note info">Пока это учёт запасов, а не рацион: животные корм не списывают. Питательность считается по сухому веществу, обменной энергии и сырому протеину; качество заготовки меняет энергию и протеин.</div><div class="grid kpis"><div class="card kpi"><div class="label">КОРМОВАЯ МАССА</div><div class="v">${num(f.total.tons,1)} т</div></div><div class="card kpi"><div class="label">СУХОЕ ВЕЩЕСТВО</div><div class="v">${num(f.total.dmT,1)} т СВ</div></div><div class="card kpi"><div class="label">ОБМЕННАЯ ЭНЕРГИЯ</div><div class="v">${num(f.total.energyGJ,0)} ГДж</div></div><div class="card kpi"><div class="label">СЫРОЙ ПРОТЕИН</div><div class="v">${num(f.total.proteinT,2)} т</div></div></div>${f.byType.length?`<div class="table-wrap"><table><thead><tr><th>КОРМ</th><th>МАССА</th><th>СВ</th><th>СР. КАЧЕСТВО</th><th>ЭНЕРГИЯ</th><th>ПРОТЕИН</th></tr></thead><tbody>${f.byType.map(x=>`<tr><td><b>${x.label}</b></td><td>${num(x.tons,1)} т</td><td>${num(x.dmT,1)} т</td><td>${num(x.quality,0)}/100</td><td>${num(x.energyGJ,0)} ГДж</td><td>${num(x.proteinT,2)} т</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Сена, соломы и готового силоса пока нет.</div>'}</div>`;}
function qualityBuyerMultiplier(score,point){const r=QUALITY_POINT_RULES[point?.id]||QUALITY_POINT_RULES.mid,sc=clamp(Number(score)||70,0,100),t=sc/100;return r.low+(r.high-r.low)*t;}
function buyerAcceptsQuality(score,point){const r=QUALITY_POINT_RULES[point?.id]||QUALITY_POINT_RULES.mid;return (Number(score)||0)>=r.min;}
function lotMoistureStatus(l){const safe=cropSafeMoisture(l.crop),m=Number(l.moisture);if(baleProducts.has(l.crop)&&Number.isFinite(m)){const ideal=(l.crop==='hay'||l.crop==='meadow_hay')?17:18,excess=Math.max(0,m-ideal);return{safe:null,moisture:m,excess,label:m<=ideal?'Сухие тюки':m<=22?'Повышенная':'Опасная',cls:m<=ideal?'good':m<=22?'warn':'bad'};}if(safe==null||!Number.isFinite(m))return{safe,moisture:null,excess:0,label:'—',cls:'info'};const excess=Math.max(0,m-safe);return{safe,moisture:m,excess,label:excess<=.2?'Безопасная':excess<=2?'Повышенная':'Высокая',cls:excess<=.2?'good':excess<=2?'warn':'bad'}}
function dryingQuote(l){const st=lotMoistureStatus(l);if(st.safe==null||st.moisture==null||st.excess<=.2)return{needed:false,cost:0,hours:0,target:st.safe,points:0,dryTons:Number(l.tons)||0,ratePerTonPoint:dryingRatePerTonPoint(l?.crop)};const tons=Math.max(0,Number(l.tons)||0),points=tons*st.excess,ratePerTonPoint=dryingRatePerTonPoint(l?.crop),cost=Math.round(points*ratePerTonPoint),hours=Math.max(.5,points/DRYING_CAPACITY_TON_POINTS_H),dryTons=tons*(100-st.moisture)/(100-st.safe);return{needed:true,cost,hours,target:st.safe,points,dryTons,ratePerTonPoint}}
function ownDryingQuote(l){const q=dryingQuote(l),sp=infraSpec('dryer');if(!q.needed||!sp||!(sp.tph>0))return{...q,available:false,fuelLiters:0,fuelCost:0};const tons=Math.max(0,Number(l.tons)||0),difficulty=Math.max(.5,q.points/Math.max(.001,tons*4)),hours=Math.max(.25,tons/sp.tph*difficulty),fuelLiters=q.points*(sp.dieselPerTonPoint||0),fuelCost=Math.round(fuelLiters*fuelAvgCost());return{...q,available:true,hours,fuelLiters,fuelCost}}
function cropStorageDensity(crop){return Math.max(.08,Number(CROP_BULK_DENSITY[crop])||.72)}
function harvestDockagePct(field,quality){const weeds=Number(field?.soil?.weeds)||15,res=Number(field?.soil?.residue)||20,q=Number(quality?.score)||70;return Math.round(clamp(1.2+weeds*.035+res*.012+(70-q)*.025,.8,8)*10)/10}
function harvestDamagePct(crop,quality,moisture){const q=Number(quality?.score)||70,safe=cropSafeMoisture(crop),wet=safe==null?0:Math.max(0,Number(moisture)-safe);return Math.round(clamp(.8+(70-q)*.035+wet*.06,.4,7)*10)/10}
function wetBufferUsedT(){return (state.warehouse?.wetLots||[]).reduce((a,l)=>a+Math.max(0,Number(l.tons)||0),0)}
function wetBufferFreeT(){return Math.max(0,(Number(infraSpec('grain')?.wetBufferT)||0)-wetBufferUsedT())}
function wetLotRisk(l,days=30){const st=lotMoistureStatus(l),ex=Math.max(0,st.excess||0),a=clamp(Number(infraSpec('grain')?.aeration)||0,0,.95),daily=(.012+ex*.018+ex*ex*.0025)*(1-a*.72),lossPct=clamp(daily*days,0,35),qualityLoss=clamp((.04+ex*.13+ex*ex*.018)*(1-a*.65)*days,0,45);return{lossPct,qualityLoss,critical:ex>=5,label:ex<=.2?'безопасно':ex<=2?'повышенный риск':ex<=5?'высокий риск':'критический риск'}}
function cleaningQuote(l){const dock=Math.max(0,Number(l?.dockagePct)||0),tons=Math.max(0,Number(l?.tons)||0),removedPct=Math.max(0,dock-.8)*.90,outT=tons*(1-removedPct/100),cost=Math.round(tons*CLEANING_CONTRACT_RATE_PER_TON),hours=Math.max(.25,tons/28);return{needed:dock>1.1,dock,targetDockage:.8,removedPct,outT,cost,hours}}
function ownCleaningQuote(l){const q=cleaningQuote(l),sp=infraSpec('cleaner'),tons=Math.max(0,Number(l?.tons)||0),energyPerTon=Math.max(0,Number(sp?.energyPerTon)||0),consumablesPerTon=Math.max(0,Number(sp?.consumablesPerTon)||0),helperLaborPerTon=Math.max(0,Number(sp?.helperLaborPerTon)||0),costPerTon=energyPerTon+consumablesPerTon+helperLaborPerTon,cost=Math.round(tons*costPerTon);return{...q,available:!!(sp?.tph>0),hours:sp?.tph>0?Math.max(.15,tons/sp.tph):q.hours,cost,costPerTon,energyPerTon,consumablesPerTon,helperLaborPerTon}}
function findPostHarvestLot(id){return (state.warehouse?.lots||[]).find(x=>x.id===id)||(state.warehouse?.wetLots||[]).find(x=>x.id===id)||null}
function removePostHarvestLot(id){let lot=null;for(const k of ['lots','wetLots']){const arr=state.warehouse?.[k]||[],i=arr.findIndex(x=>x.id===id);if(i>=0){lot=arr[i];arr.splice(i,1);if(k==='lots')state.warehouse.stocks[lot.crop]=Math.max(0,(state.warehouse.stocks[lot.crop]||0)-lot.tons);break;}}return lot}
function routeProcessedLot(lot){const st=lotMoistureStatus(lot);if(!rootCrops.has(lot.crop)&&!baleProducts.has(lot.crop)&&st.excess>.2){if(wetBufferFreeT()+1e-9<Number(lot.tons||0))return false;state.warehouse.wetLots.push(lot);return true}return storeWarehouseLot(lot)}
function startCleaning(lotId,own=false){const lot=findPostHarvestLot(lotId);if(!lot){toast('Партия не найдена');return}const q=own?ownCleaningQuote(lot):cleaningQuote(lot);if(!q.needed){toast('Очистка этой партии не требуется');return}if(own&&!q.available){toast('Сначала постройте собственный зерноочиститель');return}if(state.money<q.cost){toast(`Недостаточно средств: нужно ${rub(q.cost)}`);return}const econ=postHarvestEconomicEffect(lot,'clean',own);if(!confirm(`Очистить ${num(lot.tons,2)} т «${CROPS[lot.crop]?.label||lot.crop}»? Примесь ${num(q.dock,1)}→${num(q.targetDockage,1)}%, товарная масса после очистки ≈ ${num(q.outT,2)} т. ${own?`Своя очистка: ${rub(q.cost)} (${rub(q.costPerTon)}/т), время ${durationText(q.hours)}. Труд подсобного рабочего уже включён в себестоимость и не требует назначения сотрудника.`:`Подряд: ${rub(q.cost)}, ${durationText(q.hours)}.`}${econ?`\nОжидаемый чистый эффект при лучшем доступном покупателе сейчас: ${econ.effect>=0?'+':''}${rub(econ.effect)} (без транспортных расходов).`:''}`))return;const src=removePostHarvestLot(lotId);if(!src)return;if(q.cost>0){state.money-=q.cost;finance('expense',q.cost,'grain_cleaning',src.fieldId,`${own?'Собственная':'Подрядная'} очистка · ${num(src.tons,2)} т${own?' · энергия, расходники и подсобный труд':''}`,src.crop)}const arr=own?(state.warehouse.ownCleaningJobs=state.warehouse.ownCleaningJobs||[]):(state.warehouse.cleaningJobs=state.warehouse.cleaningJobs||[]),last=arr.length?arr[arr.length-1]:null,startAt=own?Math.max(state.gameTime,Number(last?.readyAt)||0):state.gameTime,readyAt=startAt+q.hours*3600000;arr.push({id:'clean-'+uid(),lot:{...src},crop:src.crop,startedAt:startAt,readyAt,outT:q.outT,targetDockage:q.targetDockage,cost:q.cost,own});save();render();toast(own&&startAt>state.gameTime?'Партия в очереди очистителя':'Очистка началась')}
function processCleaning(){for(const key of ['cleaningJobs','ownCleaningJobs']){const keep=[];for(const j of state.warehouse?.[key]||[]){if(j.readyAt>state.gameTime){keep.push(j);continue}const q=lotQuality(j.lot),lot={...j.lot,tons:j.outT,dockagePct:j.targetDockage,cleanedAt:j.readyAt,quality:makeQuality(j.crop,clamp(q.score+Math.min(5,(Number(j.lot.dockagePct)||0)*.55),0,100),'cleaned')};if(!routeProcessedLot(lot)){j.readyAt=state.gameTime+3600000;j.storageWaiting=true;keep.push(j);continue}log(`Очистка завершена: ${CROPS[j.crop]?.label||j.crop}, ${num(lot.tons,2)} т, примесь ${num(lot.dockagePct,1)}%.`)}state.warehouse[key]=keep}}
function storageBreakEven(crop,days=90,lots=null){const src=(lots||state.warehouse?.lots||[]).filter(l=>l.crop===crop),tons=src.reduce((a,l)=>a+(Number(l.tons)||0),0);if(!tons)return null;const now=cropMarketPrice(crop),months=days/30,fee=tons*grainStorageRate()*months,baseLoss=grainStorageLossPct()/100*months,a=clamp(Number(infraSpec('grain')?.aeration)||0,0,.95),wetExtra=src.reduce((a0,l)=>a0+(Number(l.tons)||0)*Math.min(.20,Math.pow(Math.max(0,lotMoistureStatus(l).excess),1.45)*.004*(1-a*.7)),0)/tons,loss=clamp(baseLoss+wetExtra,0,.35),after=tons*(1-loss),needed=(tons*now+fee)/Math.max(.001,after);return{days,tons,now,fee,lossPct:loss*100,after,needed}}

function processDrying(){const jobs=state.warehouse?.dryingJobs||[],keep=[];for(const j of jobs){if(j.readyAt>state.gameTime){keep.push(j);continue}const lot={...j.lot,tons:j.dryTons,moisture:j.targetMoisture,driedAt:j.readyAt,dryingCost:j.cost,quality:j.lot.quality||makeQuality(j.crop,70,'legacy')};if(!storeWarehouseLot(lot)){j.readyAt=state.gameTime+3600000;j.storageWaiting=true;keep.push(j);continue}log(`Сушка завершена: ${CROPS[lot.crop]?.label||lot.crop}, ${num(lot.tons,2)} т, влажность ${num(lot.moisture,1)}%.`)}state.warehouse.dryingJobs=keep;processOwnDrying()}
function processOwnDrying(){const jobs=state.warehouse?.ownDryingJobs||[],keep=[];for(const j of jobs){if(j.readyAt>state.gameTime){keep.push(j);continue}const lot={...j.lot,tons:j.dryTons,moisture:j.targetMoisture,driedAt:j.readyAt,dryingCost:j.fuelCost||0,quality:j.lot.quality||makeQuality(j.crop,70,'legacy')};if(!storeWarehouseLot(lot)){j.readyAt=state.gameTime+3600000;j.storageWaiting=true;keep.push(j);continue}log(`Собственная сушка завершена: ${CROPS[lot.crop]?.label||lot.crop}, ${num(lot.tons,2)} т, влажность ${num(lot.moisture,1)}%.`)}state.warehouse.ownDryingJobs=keep}
function startDrying(lotId){const lot=findPostHarvestLot(lotId);if(!lot){toast('Партия не найдена');return}const q=dryingQuote(lot);if(!q.needed){toast('Сушка этой партии не требуется');return}if(state.money<q.cost){toast(`Недостаточно средств на сушку: нужно ${rub(q.cost)}`);return}const water=Math.max(0,lot.tons-q.dryTons),econ=postHarvestEconomicEffect(lot,'dry',false);if(!confirm(`Отправить ${num(lot.tons,2)} т на подрядную сушку до ${num(q.target,1)}%?\nПосле сушки ≈ ${num(q.dryTons,2)} т · удалится ≈ ${num(water,2)} т воды.\nСтоимость ${rub(q.cost)}, время ${durationText(q.hours)}.${econ?`\nОжидаемый чистый эффект при лучшем доступном покупателе сейчас: ${econ.effect>=0?'+':''}${rub(econ.effect)} (без транспортных расходов).`:''}`))return;const src=removePostHarvestLot(lotId);if(!src)return;state.money-=q.cost;finance('expense',q.cost,'grain_drying',src.fieldId,`Подрядная сушка · ${num(src.tons,2)} т · ${num(src.moisture,1)}→${num(q.target,1)}%`,src.crop);state.warehouse.dryingJobs=state.warehouse.dryingJobs||[];state.warehouse.dryingJobs.push({id:'dry-'+uid(),lot:{...src},crop:src.crop,fieldId:src.fieldId,startedAt:state.gameTime,readyAt:state.gameTime+q.hours*3600000,targetMoisture:q.target,dryTons:q.dryTons,cost:q.cost});save();render();toast('Партия отправлена на сушку');}
