const ROOT_SALE_POINT_TEMPLATES=[
 {id:'root_near',name:'Районная овощебаза',distance:[18,35],priceMult:.97,desc:'Близкий рынок картофеля и свёклы.'},
 {id:'root_mid',name:'Картофельный комбинат / сахарный завод',distance:[35,65],priceMult:1.00,desc:'Основной переработчик корнеплодов.'},
 {id:'root_far',name:'Региональный перерабатывающий холдинг',distance:[65,110],priceMult:1.025,desc:'Дальняя точка с умеренной премией и дорогой доставкой.'}
];

const ROOT_BUYER_CAPACITY_BASE={
 potato:{root_near:800,root_mid:3000,root_far:5200},
 sugar_beet:{root_near:1200,root_mid:7000,root_far:11800}
};
function rootBuyerCapacity(cropKey,point,at=state.gameTime){
 if(!rootCrops.has(cropKey))return Infinity;const base=ROOT_BUYER_CAPACITY_BASE[cropKey]?.[point?.id];if(!base)return Infinity;
 const y=new Date(at).getFullYear(),seed=((state.landSeed||1)^hashString(`rootcap:${y}:${cropKey}:${point?.id||''}`))>>>0,r=rngFactory(seed),factor=.88+r()*.24;
 return Math.round(base*factor);
}
function rootBuyerLedger(){state.market=state.market&&typeof state.market==='object'?state.market:{};state.market.rootBuyerVolumes=state.market.rootBuyerVolumes&&typeof state.market.rootBuyerVolumes==='object'?state.market.rootBuyerVolumes:{};return state.market.rootBuyerVolumes;}
function rootBuyerCommittedTons(cropKey,point,at=state.gameTime){
 if(!rootCrops.has(cropKey))return 0;const y=new Date(at).getFullYear(),key=`${y}:${cropKey}:${point?.id||''}`,ledger=rootBuyerLedger(),settled=Math.max(0,Number(ledger[key])||0),transit=(state.warehouse?.salesTransit||[]).filter(j=>j.crop===cropKey&&j.pointId===point?.id&&Number(j.marketYear||new Date(j.operationStartedAt||j.startedAt||at).getFullYear())===y).reduce((a,j)=>a+Math.max(0,Number(j.tons)||0),0);return settled+transit;
}
function rootVolumeFactorAtRatio(r){r=Math.max(0,Number(r)||0);if(r<=1)return 1;if(r<=1.5)return 1-(r-1)*.20;if(r<=2.5)return .90-(r-1.5)*.18;if(r<=4)return .72-(r-2.5)*(.17/1.5);return .55;}
