 if(!rootCrops.has(cropKey))return{capacity:Infinity,committed:0,requested:Math.max(0,Number(tons)||0),factor:1,remaining:Infinity,utilization:0};const cap=rootBuyerCapacity(cropKey,point,at),used=rootBuyerCommittedTons(cropKey,point,at),qty=Math.max(0,Number(tons)||0),factor=rootVolumeAverageFactor(used,qty||1,cap);return{capacity:cap,committed:used,requested:qty,factor,remaining:Math.max(0,cap-used),utilization:cap>0?used/cap:0};
