 return [...SALE_POINT_TEMPLATES,...ROOT_SALE_POINT_TEMPLATES,...FORAGE_SALE_POINT_TEMPLATES].map(x=>({...x,distanceKm:randInt(r,x.distance[0],x.distance[1])}));
