function lotsWeightedQuality(lots){const tons=lots.reduce((a,l)=>a+(Number(l.tons)||0),0);return tons?lots.reduce((a,l)=>a+(Number(l.tons)||0)*lotQuality(l).score,0)/tons:70}
function grainBlendSaleAnalysis(lots){const tons=(lots||[]).reduce((a,l)=>a+Math.max(0,Number(l.tons)||0),0),quality=lotsWeightedQuality(lots||[]),dockage=tons?(lots||[]).reduce((a,l)=>a+Math.max(0,Number(l.tons)||0)*Math.max(0,Number(l.dockagePct)||0),0)/tons:0,damage=tons?(lots||[]).reduce((a,l)=>a+Math.max(0,Number(l.tons)||0)*Math.max(0,Number(l.grainDamagePct)||0),0)/tons:0,dockPenaltyPct=clamp(Math.max(0,dockage-1)*1.2,0,10),damagePenaltyPct=clamp(Math.max(0,damage-1)*1.8,0,12),commercialScore=clamp(quality-Math.max(0,dockage-1)*1.5-Math.max(0,damage-1)*2.0,0,100),priceFactor=clamp(1-(dockPenaltyPct+damagePenaltyPct)/100,.78,1);return{tons,quality,dockage,damage,dockPenaltyPct,damagePenaltyPct,commercialScore,priceFactor}}
