  state.money+=j.revenue;
  if(rootCrops.has(j.crop)&&j.pointId&&!j.deliveryContractId)recordRootBuyerSale(j.crop,j.pointId,j.tons,Date.UTC(Number(j.marketYear)||new Date(j.readyAt||state.gameTime).getFullYear(),0,1));
