const fieldCode=f=>f?.code||((isMeadow(f)?'H-':'F-')+String(f?.id||0).padStart(4,'0'));
const LAND_CLUSTERS=[{id:'N',label:'Север',short:'С'},{id:'NE',label:'Северо-Восток',short:'СВ'},{id:'E',label:'Восток',short:'В'},{id:'SE',label:'Юго-Восток',short:'ЮВ'},{id:'S',label:'Юг',short:'Ю'},{id:'SW',label:'Юго-Запад',short:'ЮЗ'},{id:'W',label:'Запад',short:'З'},{id:'NW',label:'Северо-Запад',short:'СЗ'}];
const LAND_CLUSTER_IDS=new Set(LAND_CLUSTERS.map(x=>x.id));
function landClusterById(id){return LAND_CLUSTERS.find(x=>x.id===id)||LAND_CLUSTERS[0]}
function assignLandCluster(f,seed=state?.landSeed||1){if(!f)return f;if(!LAND_CLUSTER_IDS.has(f.clusterId)){const x=((Math.imul((Number(f.id)||1),2654435761)^(Number(seed)||1)^0x4C4E44)>>>0);f.clusterId=LAND_CLUSTERS[x%LAND_CLUSTERS.length].id;f.clusterPosition=((x>>>8)%1000)/999;}else if(!Number.isFinite(Number(f.clusterPosition)))f.clusterPosition=.5;return f}
function landClusterLabel(f){assignLandCluster(f);const c=landClusterById(f.clusterId);return `${c.short} · ${c.label}`}
const LAND_CLUSTER_RING=['N','NE','E','SE','S','SW','W','NW'];
function clusterIndex(id){return LAND_CLUSTER_RING.indexOf(id)}
function clusterSteps(a,b){const ia=clusterIndex(a),ib=clusterIndex(b);if(ia<0||ib<0)return 4;const d=Math.abs(ia-ib);return Math.min(d,8-d)}
function clustersAdjacent(a,b){return a===b||clusterSteps(a,b)===1}
function sameClusterDistanceKm(a,b){assignLandCluster(a);assignLandCluster(b);if(!a||!b)return 0;if(a.id===b.id)return 0;if(a.clusterId!==b.clusterId)return Math.max(.5,(Number(a.distanceKm)||0)+(Number(b.distanceKm)||0));const pos=Math.abs((Number(a.clusterPosition)||0)-(Number(b.clusterPosition)||0)),radial=Math.abs((Number(a.distanceKm)||0)-(Number(b.distanceKm)||0));return clamp(1.2+pos*6.5+radial*.12,.8,9)}
function adjacentClusterDistanceKm(a,b){assignLandCluster(a);assignLandCluster(b);if(!a||!b)return 0;if(a.clusterId===b.clusterId)return sameClusterDistanceKm(a,b);if(!clustersAdjacent(a.clusterId,b.clusterId))return Math.max(.5,(Number(a.distanceKm)||0)+(Number(b.distanceKm)||0));const radial=Math.abs((Number(a.distanceKm)||0)-(Number(b.distanceKm)||0)),pos=Math.abs((Number(a.clusterPosition)||.5)-(Number(b.clusterPosition)||.5));return clamp(4.5+radial*.18+pos*7,3,18)}
function assetRouteToFieldKm(asset,target){assignLandCluster(target);if(!asset||asset.locationType!=='field'||!Number.isFinite(Number(asset.locationFieldId)))return Math.max(.5,Number(target?.distanceKm)||0);const src=landById(asset.locationFieldId);return src?(clustersAdjacent(src.clusterId,target.clusterId)?adjacentClusterDistanceKm(src,target):Math.max(.5,(Number(src.distanceKm)||0)+(Number(target.distanceKm)||0))):Math.max(.5,Number(target?.distanceKm)||0)}
function setAssetFieldLocation(asset,field){if(!asset||!field)return;assignLandCluster(field);asset.locationType='field';asset.locationFieldId=field.id;asset.locationClusterId=field.clusterId;asset.locationUpdatedAt=state.gameTime}
function assetLocationLabel(asset){if(!asset||asset.locationType!=='field'||!Number.isFinite(Number(asset.locationFieldId)))return'На базе';const f=landById(asset.locationFieldId);if(!f)return'На базе';assignLandCluster(f);return `${fieldCode(f)} · ${landClusterLabel(f)}`}

