function baleFormatCapacityForModel(m,format){if(!m)return 0;if(m.baleCapacity)return Math.max(0,Number(m.baleCapacity[format])||0);const mass=Math.max(.01,Number(BALE_FORMATS[format]?.massT)||.35),payload=Math.max(0,Number(m.capacityT)||0);if(!payload)return 0;const stackFactor=m.type==='truck'?0.82:m.type==='trailer'?0.88:.84;return Math.max(1,Math.floor(payload*stackFactor/mass));}
