function macroBaseRate(y=currentYear()){const cycle=[.115,.107,.098,.104,.121,.132,.124,.111,.101,.096,.102,.114];return cycle[Math.abs(y-2026)%cycle.length];}
function bankOffer(bankId,productId){const b=BANKS[bankId],p=LOAN_PRODUCTS[productId];if(!b||!p)return null;const scorePenalty=(100-(state.financing?.creditScore??100))*.001;return{...p,bankId,bank:b.label,bankDesc:b.desc,minDscr:b.minDscr,min:Math.round(p.min*b.limitMult/50000)*50000,max:Math.round(p.max*b.limitMult/100000)*100000,annualRate:macroBaseRate()+p.margin+b.spread+scorePenalty,id:`${bankId}:${productId}`};}
