function outsideWorkDefault(){return{offers:[],active:[],history:[],lastRefreshDay:null,totalIncome:0,completed:0};}
function normalizeOutsideWork(x){x=x&&typeof x==='object'?x:{};return{offers:Array.isArray(x.offers)?x.offers.filter(Boolean):[],active:Array.isArray(x.active)?x.active.filter(Boolean):[],history:Array.isArray(x.history)?x.history.filter(Boolean).slice(0,200):[],lastRefreshDay:Number.isFinite(Number(x.lastRefreshDay))?Number(x.lastRefreshDay):null,totalIncome:Math.max(0,Number(x.totalIncome)||0),completed:Math.max(0,Number(x.completed)||0)};}
function outsideWorkDayKey(t=state.gameTime){return Math.floor(dayStart(t)/DAY);}
function outsideWorkTemplatesForMonth(m){const out=[];for(const [role,arr] of Object.entries(OUTSIDE_WORK_TEMPLATES))for(const x of arr)if(x.season.includes(m))out.push({...x,role});return out;}
function refreshOutsideWork(force=false){state.outsideWork=normalizeOutsideWork(state.outsideWork);const key=outsideWorkDayKey(),d=new Date(state.gameTime);if(!force&&state.outsideWork.lastRefreshDay===key&&state.outsideWork.offers.length)return;const r=rngFactory(((state.landSeed||1)^hashString(`outside:${key}`)^0x0A6411)>>>0),templates=outsideWorkTemplatesForMonth(d.getMonth()),offers=[];const target=Math.min(12,Math.max(5,templates.length+2));for(let i=0;i<target&&templates.length;i++){const t=pick(r,templates),req=randInt(r,t.skill[0],t.skill[1]),hours=randInt(r,t.hours[0],t.hours[1]);offers.push({id:`JOB-${key}-${i+1}`,templateId:t.id,label:t.label,role:t.role,requiredSkill:req,hours,availableUntil:dayStart(state.gameTime)+2*DAY,customer:pick(r,['ООО «Колос»','КФХ «Рассвет»','Агрофирма «Поле»','СПК «Нива»','КФХ «Берёзка»'])});}if(!offers.some(o=>o.requiredSkill<=45)){offers.push({id:`JOB-${key}-START`,templateId:'yard_machine',label:'Механизатор · хозяйственные работы',role:'operator',requiredSkill:35,hours:6,availableUntil:dayStart(state.gameTime)+2*DAY,customer:'КФХ «Рассвет»'});}state.outsideWork.offers=offers;state.outsideWork.lastRefreshDay=key;}
function outsideWorkerEligible(w,o){if(!w||!o||!employeeFree(w))return false;if(w.id!=='OWNER'&&w.contract!=='permanent')return false;if(w.id!=='OWNER'&&w.role!==o.role)return false;return (Number(w.skill)||0)>=Number(o.requiredSkill||0);}
function outsideWorkRate(w,o){const role=o?.role||'operator';return gigHourlyRate(role,w?.skill||50);}
function startOutsideWork(offerId,workerId){refreshOutsideWork();const o=state.outsideWork.offers.find(x=>x.id===offerId),w=workerById(workerId);if(!o||!w)return toast('Предложение или работник уже недоступны');if(!outsideWorkerEligible(w,o))return toast('Работник занят, не подходит по профессии или квалификации');const rate=outsideWorkRate(w,o),hours=Math.max(1,Number(o.hours)||8),end=state.gameTime+hours*3600000,reward=Math.round(rate*hours);if(!confirm(`${o.label}\n${o.customer}\n\n${w.name} · навык ${w.skill}/100\nСмена: ${hours} ч\nСтавка: ${rub(rate)}/ч\nДоход хозяйства: ${rub(reward)}\n\nНа время работы человек недоступен для вашего хозяйства.`))return;w.busyUntil=end;w.fatigue=clamp((w.fatigue||0)+shiftFatigueGain(w,Math.min(14,hours),hours),0,100);const job={...o,workerId:w.id,workerName:w.name,workerSkillStart:w.skill,startedAt:state.gameTime,end,rate,reward,status:'working'};state.outsideWork.active.push(job);state.outsideWork.offers=state.outsideWork.offers.filter(x=>x.id!==offerId);log(`${w.name}: принят заказ «${o.label}» на ${hours} ч · ожидаемый доход ${rub(reward)}.`);save();render();}
function finishOutsideWork(j){const w=workerById(j.workerId);if(w){staffAccrueHoursAcrossRange(w,j.hours,j.startedAt,j.end,'outside_work');addSkillHours(w,j.hours,'outside_work');const restH=staffRestHoursAfterShift(Math.min(14,j.hours),w);w.restUntil=Math.max(Number(w.restUntil)||0,j.end+restH*3600000);if((w.busyUntil||0)<=j.end)w.busyUntil=0;}state.money+=j.reward;finance('income',j.reward,'outside_work_income',null,`Работа по найму · ${j.workerName} · ${j.label}`);j.finishedAt=j.end;j.status='completed';j.skillAfter=w?.skill??j.workerSkillStart;state.outsideWork.totalIncome+=j.reward;state.outsideWork.completed++;state.outsideWork.history.unshift(j);state.outsideWork.history=state.outsideWork.history.slice(0,200);log(`${j.workerName}: работа по найму завершена · +${rub(j.reward)} · ${j.hours} ч опыта.`);}
function processOutsideWork(){state.outsideWork=normalizeOutsideWork(state.outsideWork);refreshOutsideWork();const done=state.outsideWork.active.filter(j=>j.status==='working'&&j.end<=state.gameTime);for(const j of done)finishOutsideWork(j);state.outsideWork.active=state.outsideWork.active.filter(j=>j.status==='working');state.outsideWork.offers=state.outsideWork.offers.filter(o=>!o.availableUntil||o.availableUntil>state.gameTime);}
function renderOutsideWork(){refreshOutsideWork();const ow=state.outsideWork,workers=[state.staff.owner,...state.staff.employees.filter(e=>e.contract==='permanent')];const active=ow.active||[];const cards=(ow.offers||[]).map(o=>{const elig=workers.filter(w=>outsideWorkerEligible(w,o));return `<div class="card info-card contract-card"><div class="section-title"><div><span class="status info">${STAFF_ROLE_LABEL[o.role]||o.role}</span><h3>${o.label}</h3></div><b>${o.hours} ч</b></div><div class="small">${o.customer} · требуется навык ≥ <b>${o.requiredSkill}</b></div><div class="muted tiny">Оплата зависит от квалификации выбранного работника и совпадает с рыночной ставкой разового специалиста его уровня.</div><div class="row-actions" style="margin-top:10px"><select class="select compact" data-outside-worker="${o.id}"><option value="">— выбрать работника —</option>${elig.map(w=>`<option value="${w.id}">${w.name} · ${w.skill}/100 · ${rub(outsideWorkRate(w,o))}/ч · ${rub(outsideWorkRate(w,o)*o.hours)}</option>`).join('')}</select><button class="btn" data-outside-start="${o.id}" ${elig.length?'':'disabled'}>Выйти на работу</button></div>${!elig.length?'<div class="block-reason">Нет свободного владельца или штатного сотрудника нужной профессии/квалификации.</div>':''}</div>`}).join('');return `${pageHead('Работа по найму','Предоставляйте свободного владельца или штатных сотрудников другим хозяйствам без своей техники. Доход идёт хозяйству, а работник получает часы опыта.')}<div class="grid kpis"><div class="card kpi"><div class="label">ДОСТУПНО</div><div class="v">${ow.offers.length}</div></div><div class="card kpi"><div class="label">В РАБОТЕ</div><div class="v">${active.length}</div></div><div class="card kpi"><div class="label">ЗАРАБОТАНО</div><div class="v positive">${rub(ow.totalIncome)}</div></div><div class="card kpi"><div class="label">ВЫПОЛНЕНО</div><div class="v">${ow.completed}</div></div></div><div class="note">Владелец не получает зарплату, поэтому вся оплата заказа остаётся хозяйству. Штатному сотруднику эти часы одновременно входят в его месячную премию и развитие навыка — фактическая маржа хозяйства ниже полной ставки заказчика.</div>${active.length?`<div class="card section-card"><div class="section-title"><h2>Сейчас на работе</h2></div><div class="contract-grid">${active.map(j=>`<div class="card info-card contract-card active"><div class="section-title"><div><span class="status warn">В работе</span><h3>${j.workerName}</h3></div><b>${rub(j.reward)}</b></div><div class="small">${j.label} · ${j.hours} ч · ${rub(j.rate)}/ч</div><div class="muted tiny">Завершение ${dateFmt(j.end)}</div><div class="progress"><span style="width:${clamp((state.gameTime-j.startedAt)/Math.max(1,j.end-j.startedAt)*100,0,100)}%"></span></div></div>`).join('')}</div></div>`:''}<div class="card section-card"><div class="section-title"><div><h2>Доска работ</h2><div class="muted tiny">Предложения обновляются ежедневно и меняются по сезону.</div></div><button class="btn secondary compact" data-outside-refresh>Обновить</button></div><div class="contract-grid">${cards||'<div class="empty">Сейчас подходящей работы нет.</div>'}</div></div>${ow.history.length?`<div class="card section-card"><div class="section-title"><h2>История</h2></div><div class="table-wrap"><table><thead><tr><th>РАБОТНИК</th><th>РАБОТА</th><th>ЧАСЫ</th><th>ДОХОД</th><th>НАВЫК</th></tr></thead><tbody>${ow.history.slice(0,30).map(j=>`<tr><td>${j.workerName}</td><td>${j.label}</td><td>${j.hours}</td><td>${rub(j.reward)}</td><td>${j.workerSkillStart} → ${j.skillAfter}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;}
function financingDefault(){return{contracts:[],creditScore:100,nextSerial:1,line:null};}
function addMonthsTs(ms,n){const d=new Date(ms),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);const mx=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,mx));return d.getTime();}
function normalizeFinancing(x){x=x&&typeof x==='object'?x:{};const cs=(Array.isArray(x.contracts)?x.contracts:[]).filter(Boolean).map(c=>{const balance=Math.max(0,+c.balance||0);return{...c,balance,annualRate:Math.max(0,+c.annualRate||0),termMonths:Math.max(1,+c.termMonths||1),monthlyPayment:Math.max(0,+c.monthlyPayment||0),nextPaymentAt:+c.nextPaymentAt||state?.gameTime||Date.now(),paymentsMade:Math.max(0,+c.paymentsMade||0),schedule:c.schedule||(c.type==='lease'?'lease_balloon':'annuity'),graceMonths:Math.max(0,+c.graceMonths||0),residualValue:Math.max(0,+c.residualValue||0),status:c.status||'active',arrears:{principal:Math.min(balance,Math.max(0,+c.arrears?.principal||0)),interest:Math.max(0,+c.arrears?.interest||0),penalty:Math.max(0,+c.arrears?.penalty||0)}}});let l=x.line&&typeof x.line==='object'?{...x.line}:null;if(l){l.limit=Math.max(0,+l.limit||0);l.balance=Math.max(0,+l.balance||0);l.annualRate=Math.max(0,+l.annualRate||.165);l.nextPaymentAt=+l.nextPaymentAt||state?.gameTime||Date.now();l.endAt=+l.endAt||addMonthsTs(state?.gameTime||Date.now(),12);l.arrears=Math.max(0,+l.arrears||0);l.status=l.status||'active';}return{contracts:cs,creditScore:clamp(+x.creditScore||100,40,100),nextSerial:Math.max(1,+x.nextSerial||1),line:l};}
function annuityPayment(p,a,n){p=Math.max(0,+p||0);n=Math.max(1,+n||1);const r=(+a||0)/12;return r<=0?p/n:p*r/(1-Math.pow(1+r,-n));}
function balloonPayment(p,a,n,residual){p=Math.max(0,+p||0);n=Math.max(1,+n||1);residual=clamp(+residual||0,0,p);const r=(+a||0)/12;if(r<=0)return Math.max(0,(p-residual)/n);return Math.max(0,(p-residual/Math.pow(1+r,n))*r/(1-Math.pow(1+r,-n)));}
function financingArrears(){const f=state.financing||financingDefault();return f.contracts.filter(c=>['active','buyout_due'].includes(c.status)).reduce((s,c)=>s+(+c.arrears?.principal||0)+(+c.arrears?.interest||0)+(+c.arrears?.penalty||0),0)+(+f.line?.arrears||0);}
function financingBlockReason(){const f=state.financing||financingDefault(),arr=financingArrears();if(state?.financialCrisis?.bankruptAt)return'Хозяйство признано банкротом: новое финансирование недоступно.';if(arr>.5)return `Есть просроченные обязательства: ${rub(arr)}. Сначала погасите просрочку.`;if((f.creditScore??100)<55)return `Кредитный рейтинг ${Math.round(f.creditScore)}/100 слишком низкий для нового финансирования.`;return'';}
function activeDebt(){const f=state.financing||financingDefault();const contracts=f.contracts.filter(c=>['active','buyout_due'].includes(c.status)).reduce((s,c)=>s+(+c.balance||0)+(+c.arrears?.interest||0)+(+c.arrears?.penalty||0),0);return contracts+(+f.line?.balance||0)+(+f.line?.arrears||0);}
function contractCurrentInstallment(c){if(!c||c.status!=='active')return 0;const interest=Math.round((+c.balance||0)*(+c.annualRate||0)/12);if(c.schedule==='seasonal')return interest;if(c.schedule==='grace_annuity'&&(+c.paymentsMade||0)<(+c.graceMonths||0))return interest;return Math.max(interest,Math.round(+c.monthlyPayment||0));}
function monthlyDebtService(){const f=state.financing||financingDefault();return f.contracts.filter(c=>c.status==='active').reduce((s,c)=>s+contractCurrentInstallment(c),0)+(f.line?.balance?f.line.balance*f.line.annualRate/12:0);}
function financingCollateralValue(){const land=(state.fields||[]).filter(f=>f.owned&&f.tenure!=='leased').reduce((sum,f)=>sum+Math.max(0,fieldSaleValue(f))*.55,0),equipment=(state.equipment?.fleet||[]).reduce((sum,a)=>sum+Math.max(0,assetSaleValue(a))*.45,0),stock=Object.entries(state.warehouse?.stocks||{}).reduce((sum,[k,t])=>sum+Math.max(0,Number(t)||0)*Math.max(0,Number(CROPS[k]?.price)||0)*.25,0),since=state.gameTime-365*DAY,operating=(state.finance||[]).filter(x=>x.time>=since&&x.type==='income'&&['crop_sale','contract_income','outside_work_income'].includes(x.category)).reduce((sum,x)=>sum+Math.max(0,Number(x.amount)||0),0)*.20,score=clamp((state.financing?.creditScore??100)/100,.55,1);return Math.round((3000000+land+equipment+stock+operating)*score/50000)*50000;}
function financingAvailableCapacity(extraSecured=0){return Math.max(0,financingCollateralValue()+Math.max(0,Number(extraSecured)||0)-activeDebt());}
function financingCapacityBlock(requested,extraSecured=0){requested=Math.max(0,Number(requested)||0);const av=financingAvailableCapacity(extraSecured);return requested>av+.5?`Недостаточно залогового лимита: доступно ${rub(av)}, запрошено ${rub(requested)}.`:'';}
function financingOperatingCapacity(extraSecured=0){const since=state.gameTime-365*DAY,rows=(state.finance||[]).filter(x=>x.time>=since&&!x.nonCash),income=rows.filter(x=>x.type==='income'&&!['financing_inflow'].includes(x.category)).reduce((s,x)=>s+(+x.amount||0),0),expense=rows.filter(x=>x.type==='expense'&&!['financing_principal','financing_interest','equipment','land'].includes(x.category)).reduce((s,x)=>s+(+x.amount||0),0),recent=Math.max(0,income-expense),ha=allLandUnits().filter(f=>f.owned).reduce((s,f)=>s+(+f.ha||0),0),expected=(state.fields||[]).filter(f=>f.owned&&f.crop&&CROPS[f.crop]).reduce((s,f)=>s+(+f.ha||0)*(+CROPS[f.crop].baseYield||0)*Math.max(0,cropMarketPrice(f.crop,state.gameTime))*.30,0),base=1500000+ha*18000+Math.max(0,+state.money||0)*.12+(financingCollateralValue()+Math.max(0,+extraSecured||0))*.04;return Math.max(750000,base+recent*.65+expected);}
function contractAnnualDebtService(c){if(!c||c.status!=='active')return 0;const bal=Math.max(0,+c.balance||0),rate=Math.max(0,+c.annualRate||0),remaining=Math.max(1,(+c.termMonths||1)-(+c.paymentsMade||0));if(c.schedule==='seasonal')return bal*(1+rate);if(c.schedule==='grace_annuity'){const g=Math.max(0,(+c.graceMonths||0)-(+c.paymentsMade||0)),months=Math.min(12,remaining),interest=bal*rate/12*Math.min(g,months),amort=Math.max(0,months-g)*Math.max(0,+c.monthlyPayment||0);return interest+amort;}return Math.min(12,remaining)*Math.max(0,+c.monthlyPayment||contractCurrentInstallment(c));}
