function newLoanAnnualDebtService(pr,amount){amount=Math.max(0,+amount||0);if(pr.schedule==='seasonal')return amount*(1+pr.annualRate);if(pr.schedule==='grace_annuity'){const post=Math.round(annuityPayment(amount,pr.annualRate,Math.max(1,pr.termMonths-(pr.graceMonths||0)))),g=Math.min(12,pr.graceMonths||0);return amount*pr.annualRate/12*g+post*Math.max(0,12-g);}return Math.round(annuityPayment(amount,pr.annualRate,pr.termMonths))*Math.min(12,pr.termMonths);}
