function financingBankCurrentLimit(bankId){const offers=Object.keys(LOAN_PRODUCTS).map(pid=>bankOffer(bankId,pid)).filter(Boolean);return offers.reduce((m,o)=>Math.max(m,financingCurrentLoanLimit(o)),0);}
