 const l=state.financing?.line;if(l&&l.status==='active'){let t=Number(l.nextPaymentAt)||end+1,guard=0,first=true;while(t<=end&&guard++<24){const interest=Math.round((Number(l.balance)||0)*(Number(l.annualRate)||0)/12),mature=t>=Number(l.endAt||Infinity);add(t,'expense',interest+(first?Number(l.arrears)||0:0)+(mature?Number(l.balance)||0:0),mature?`${l.id} · закрытие кредитной линии`:`${l.id} · проценты`,'debt');first=false;t=addMonthsTs(t,1);}}
