 const payroll=(state.staff?.employees||[]).filter(e=>e.contract==='permanent').reduce((a,e)=>{const t=staffPayTerms(e);return a+t.base+t.bonus*100;},0),infra=infrastructureMonthlyCost(),grainFee=grainStoredT()*Math.max(0,Number(infraSpec('grain').storagePerT)||0),vegFee=vegetableStoredT()*Math.max(0,Number(infraSpec('vegetable').storagePerT)||0);for(const t of monthStartsBetween(start,end)){if(payroll)add(t,'expense',payroll,'Зарплата постоянного персонала','payroll');if(infra)add(t,'expense',infra,'Содержание инфраструктуры','infrastructure');if(grainFee+vegFee)add(t,'expense',Math.round(grainFee+vegFee),'Хранение текущих запасов','storage');}
