function seasonExpenseForecastHtml(){const s=seasonExpenseForecast();return `<div class="card section-card"><div class="section-title"><h2>Ожидаемые расходы сезона · ${s.year}</h2><span class="pill">до 31 декабря</span></div><div class="grid kpis"><div class="card kpi"><div class="label">УЖЕ ПОНЕСЕНО</div><div class="v">${rub(s.spent)}</div></div><div class="card kpi"><div class="label">ЕЩЁ ОЖИДАЕТСЯ</div><div class="v negative">${rub(s.future)}</div></div><div class="card kpi"><div class="label">ОЦЕНКА СЕЗОНА</div><div class="v">${rub(s.total)}</div></div></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>СТАТЬЯ</th><th class="right">УЖЕ</th><th class="right">ОЖИДАЕТСЯ</th><th class="right">ИТОГО</th></tr></thead><tbody>${s.items.map(x=>`<tr><td><b>${x.label}</b></td><td class="right">${rub(x.spent)}</td><td class="right ${x.future>0?'negative':''}">${rub(x.future)}</td><td class="right"><b>${rub(x.total)}</b></td></tr>`).join('')}</tbody></table></div><div class="note info" style="margin-top:10px">Семена, питание и СЗР считаются по текущим полям и агрономическим рекомендациям; топливо — ориентир оставшихся сезонных работ. Зарплаты, аренда, долг и прочие обязательства берутся из уже известных календарных платежей. Это прогноз ликвидности, а не ручной бюджет.</div></div>`;}
function cashflowStressSummary(fc=cashflowForecast(90)){const cut=Number(fc.minAt)||fc.end,untilMin=(fc.events||[]).filter(e=>e.at<=cut),expenses=untilMin.filter(e=>e.type==='expense'),incomes=untilMin.filter(e=>e.type==='income'),byCat={};for(const e of expenses)byCat[e.category]=(byCat[e.category]||0)+e.amount;const catLabels={debt:'долги и лизинг',rent:'аренда земли',payroll:'постоянный персонал',infrastructure:'инфраструктура',storage:'хранение',sale:'логистика продаж',contract:'контракты',other:'прочие обязательства'};const drivers=Object.entries(byCat).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([category,amount])=>({category,amount,label:catLabels[category]||category}));const gap=Math.max(0,-Number(fc.minBalance||0)),creditReserve=financingAvailableCapacity(),uncoveredGap=Math.max(0,gap-creditReserve),fleetValue=(state.equipment?.fleet||[]).reduce((sum,a)=>sum+Math.max(0,assetSaleValue(a)),0),stockValue=Object.entries(state.warehouse?.stocks||{}).reduce((sum,[k,t])=>sum+Math.max(0,Number(t)||0)*Math.max(0,cropMarketPrice(k,state.gameTime)),0);return{gap,uncoveredGap,creditReserve,drivers,knownIncomeBeforeMin:incomes.reduce((a,e)=>a+e.amount,0),knownExpenseBeforeMin:expenses.reduce((a,e)=>a+e.amount,0),fleetValue,stockValue,contingentIncome:Number(fc.contingentIncome)||0,minAt:cut};}
function financialHealthSnapshot(){const fc=cashflowForecast(90),arr=financingArrears(),credit=financingAvailableCapacity(),rescue=Number(state.money||0)+credit,cr=state.financialCrisis||financialCrisisDefault(),crisisTrigger=Number(state.money)<0||arr>.5||fc.minBalance+credit<-.5;const crisisDays=cr.startedAt?Math.max(0,(state.gameTime-cr.startedAt)/DAY):0,insolventDays=cr.insolventAt?Math.max(0,(state.gameTime-cr.insolventAt)/DAY):0;let status=cr.bankruptAt?'bankrupt':cr.insolventAt?'insolvent':crisisTrigger?'crisis':fc.minBalance<0?'watch':'stable';return{status,forecast:fc,arrears:arr,creditReserve:credit,rescueLiquidity:rescue,crisisTrigger,crisisDays,insolventDays,stress:cashflowStressSummary(fc)};}
function processFinancialCrisis(){state.financialCrisis=normalizeFinancialCrisis(state.financialCrisis);const cr=state.financialCrisis;if(cr.bankruptAt){cr.status='bankrupt';return;}let h=financialHealthSnapshot();if(h.crisisTrigger){if(!cr.startedAt)cr.startedAt=state.gameTime;}else{cr.startedAt=null;cr.insolventAt=null;cr.status=h.status;cr.lastStatus=cr.status;return;}h=financialHealthSnapshot();const hardGap=Math.max(0,-h.forecast.minBalance),cannotCover=h.creditReserve+Math.max(0,Number(state.money)||0)+.5<h.arrears+hardGap;if(h.crisisDays>=60&&cannotCover){if(!cr.insolventAt){cr.insolventAt=state.gameTime;log('Финансовый кризис перешёл в неплатёжеспособность: обязательства не покрываются денежными средствами и доступным кредитным резервом.');}}else if(!cannotCover)cr.insolventAt=null;h=financialHealthSnapshot();if(cr.insolventAt&&h.insolventDays>=120&&cannotCover){cr.bankruptAt=state.gameTime;cr.status='bankrupt';speed=0;log('Хозяйство признано банкротом после длительной неплатёжеспособности.');toast('Банкротство: хозяйство длительно не может покрыть обязательства.');}else cr.status=cr.insolventAt?'insolvent':'crisis';if(cr.status!==cr.lastStatus){cr.lastStatus=cr.status;}}
function repayContractArrears(id){const c=state.financing?.contracts?.find(x=>x.id===id&&['active','buyout_due'].includes(x.status));if(!c)return;const a=c.arrears||{},sum=Math.round((a.principal||0)+(a.interest||0)+(a.penalty||0));if(sum<=0)return toast('Просрочки по договору нет');if(state.money<sum)return toast(`Для погашения просрочки нужно ${rub(sum)}`);if(!confirm(`Погасить просрочку ${c.id}: ${rub(sum)}?`))return;state.money-=sum;const principal=Math.min(c.balance,Number(a.principal)||0),other=(Number(a.interest)||0)+(Number(a.penalty)||0);c.balance=Math.max(0,c.balance-principal);if(principal)finance('expense',principal,'financing_principal',null,`Погашение просроченного основного долга ${c.id}`);if(other)finance('expense',other,'financing_interest',null,`Погашение процентов/пеней ${c.id}`);c.arrears={principal:0,interest:0,penalty:0};state.financing.creditScore=clamp(state.financing.creditScore+1,40,100);processFinancialCrisis();save();render();}
function loanPaymentSetup(pr,amount){if(pr.schedule==='seasonal')return{monthlyPayment:Math.round(amount*pr.annualRate/12),graceMonths:0};if(pr.schedule==='grace_annuity'){const g=pr.graceMonths||0;return{monthlyPayment:Math.round(annuityPayment(amount,pr.annualRate,Math.max(1,pr.termMonths-g))),graceMonths:g};}return{monthlyPayment:Math.round(annuityPayment(amount,pr.annualRate,pr.termMonths)),graceMonths:0};}
