const SHIFT_LABEL={8:'Обычная · 8 ч',10:'Усиленная · 10 ч',12:'Авральная · 12 ч',14:'Сезонная · 14 ч',16:'Владелец · 16 ч',18:'Владелец · 18 ч'};
