function fuelLogisticsPickerHtml(field,q,logistics=null){if(!q||!(Number(q.liters)>0))return'';const selected=operationPicker?.fuelSupplyMode||'base_return',exclude=poweredFuelAssets(q,logistics).map(a=>a.id),opts=fuelSupplyOptions(exclude),plan=buildFuelLogisticsPlan(field,q,logistics,selected,(Number(q.liters)||0)+(Number(logistics?.transportFuelLiters)||0));const cards=opts.map(x=>{const ok=x.id==='base_return'||x.plan.ok,p=x.id===selected?plan:null,poolCount=x.plan?.poolUnits?.length||0;return `<button class="btn contractor-tier ${selected===x.id?'selected':''}" data-fuel-supply-mode="${x.id}" ${ok?'':'disabled'}><div class="contractor-tier-head"><div><b>${x.label}</b><span>${x.desc}</span></div></div><div class="unit-meta">${x.id==='base_return'?'Без дополнительной техники':ok?`${x.plan.label||'Доступно'}${poolCount>1?` · в пуле ${poolCount}`:''}`:(x.plan.reason||'Недоступно')}</div>${p?.ok?`<div class="muted tiny">Баки/заявки: ${p.refills} · ${selected==='base_return'?`возвратов машин: ${p.supportReturns} · дополнительный простой ≈ ${durationText(p.addedHours)}`:'заявки попадут в общий диспетчер ГСМ хозяйства'}</div>`:''}</button>`}).join('');return `<div class="picker-section"><div class="picker-section-head"><div><b>Снабжение ГСМ</b><span>Мобильные заправщики не закрепляются за одним полем: заявки всех одновременных операций попадают в общий пул, где диспетчер учитывает сроки, расстояния, остаток топлива и возможность заранее заехать на базу.</span></div></div><div class="contractor-tier-grid">${cards}</div>${plan?.ok?`<div class="note info"><b>${plan.label}</b> · рабочим машинам понадобится до ${num(plan.baseDrawTotalL,0)} л из базовой ёмкости${selected==='base_return'?` · дополнительный простой ≈ ${durationText(plan.addedHours)}`:' · мобильные партии будут списываться с базы фактически по рейсам общего диспетчера'}.</div>`:''}</div>`}
function processTaskFuelEvents(){for(const t of state.tasks||[]){const fl=t.fuelLogistics;if(!fl?.events)continue;for(const ev of fl.events){if(ev.processed||!(Number(ev.absoluteAt)>0)||ev.absoluteAt>state.gameTime)continue;const q=Math.max(0,Number(ev.baseDrawL)||0);if(q>0&&!transferFuelFromBase(q,`операция ${OPS[t.op]?.label||t.op} · партия ГСМ`)){state.criticalAlert={type:'fuel_shortage',time:state.gameTime,taskId:t.id,fieldId:t.fieldId,title:'На базе закончился дизель',message:`Для запланированной партии ГСМ нужно ${num(q,0)} л, в ёмкости ${num(fuelStock(),0)} л. Пополните запас.`};setGameSpeed(0);return true;}ev.processed=true;}}return false}
function settleFuelSupportOperatingCost(ev){const h=Math.max(0,Number(ev.supportHours)||0),fuel=Math.max(0,Number(ev.supportFuelL)||0),vehicleId=ev.vehicleAssetId||null;if(fuel>0){if(!consumeFuel(fuel,ev.fieldId,`Дизель мобильного снабжения ГСМ · ${ev.unitKey}`))return false;}const driverRate=700,labor=Math.round(h*driverRate);if(labor>0){if(state.money<labor)return false;state.money-=labor;finance('expense',labor,staffFinanceCategory(),ev.fieldId,`Водитель мобильного снабжения ГСМ · ${durationText(h)} · ${rub(driverRate)}/ч`);}if(vehicleId&&h>.001)applyMachineUsage({machineAssetIds:[vehicleId],machineHours:h,assetActiveHours:{[vehicleId]:h},op:'fuel_support',end:ev.at,fieldId:ev.fieldId,fuelLiters:fuel});return true}
function processFuelDispatchEvents(){const fd=fuelDispatchState();let changed=false;for(const ev of fd.events||[]){if(ev.processed||Number(ev.at)>state.gameTime)continue;if(ev.kind==='pool_reload'){const q=Math.max(0,Number(ev.loadL)||0);if(q>0&&!transferFuelFromBase(q,`общий диспетчер ГСМ · ${ev.unitKey}`)){state.criticalAlert={type:'fuel_shortage',time:state.gameTime,title:'На базе закончился дизель',message:`Для мобильного заправщика требуется ${num(q,0)} л, в ёмкости ${num(fuelStock(),0)} л.`};setGameSpeed(0);return true;}const u=fd.units[ev.unitKey]||(fd.units[ev.unitKey]={cargoL:0,locationFieldId:null});u.cargoL=Math.max(0,Number(u.cargoL)||0)+q;u.locationFieldId=null;ev.processed=true;changed=true;}
 else if(ev.kind==='pool_service'){if(!settleFuelSupportOperatingCost(ev)){state.criticalAlert={type:'fuel_shortage',time:state.gameTime,title:'Мобильное снабжение ГСМ остановлено',message:'Не хватает дизеля или денег на эксплуатацию заправщика/водителя.'};setGameSpeed(0);return true;}const u=fd.units[ev.unitKey]||(fd.units[ev.unitKey]={cargoL:0,locationFieldId:null});u.cargoL=Math.max(0,(Number(u.cargoL)||0)-Math.max(0,Number(ev.amountL)||0));u.locationFieldId=ev.fieldId??null;const t=(state.tasks||[]).find(x=>x.id===ev.taskId),d=t?.fuelLogistics?.demands?.find(x=>x.id===ev.demandId);if(d)d.processed=true;ev.processed=true;changed=true;log(`ГСМ: ${ev.unitKey} обслужил ${fieldCode(landById(ev.fieldId))} · ${num(ev.amountL,0)} л.`);}}
 if(changed)rebuildFuelDispatchPool(state.gameTime);return false}
function settleTaskFuelLogistics(t){const fl=t?.fuelLogistics;if(!fl||fl.settled)return;for(const [id,v] of Object.entries(fl.machineEndFuel||{})){const a=state.equipment?.fleet?.find(x=>x.id===id);if(a)a.fuelLevelL=clamp(Number(v)||0,0,assetFuelTankL(a));}if(Number(fl.supplierReturnL)>0&&!['ibc','cans','tanker'].includes(fl.mode))returnFuelToBase(fl.supplierReturnL,`остаток мобильного заправщика · ${OPS[t.op]?.label||t.op}`);const cost=Math.max(0,Number(fl.mainConsumedL??fl.consumedL)||0)*Math.max(0,Number(fl.unitCost)||fuelAvgCost());if(cost>0)finance('expense',cost,'fuel',t.fieldId,`Дизель · ${OPS[t.op]?.label||t.op} · фактически сожжено ${num(fl.mainConsumedL??fl.consumedL,0)} л`,t.cropKey,true);fl.settled=true;rebuildFuelDispatchPool(state.gameTime)}

function materialStock(id){return Math.max(0,Number(state.materials?.stocks?.[id])||0)}
function materialAvgCost(id){const v=Number(state.materials?.avgCost?.[id]);return Number.isFinite(v)&&v>0?v:materialMarketPrice(id)}
function addMaterial(id,qty){state.materials=state.materials||{stocks:{},avgCost:{}};state.materials.stocks=state.materials.stocks||{};state.materials.avgCost=state.materials.avgCost||{};state.materials.stocks[id]=Math.max(0,materialStock(id)+qty)}
function consumeMaterial(id,qty,fieldId,category,note,crop){const m=MATERIALS[id];if(!m||materialStock(id)+1e-9<qty)return false;const unitCost=materialAvgCost(id);addMaterial(id,-qty);finance('expense',qty*unitCost,category,fieldId,note,crop,true);return true}

function materialReservations(){state.materials=state.materials||{stocks:{},avgCost:{}};state.materials.reservations=Array.isArray(state.materials.reservations)?state.materials.reservations:[];return state.materials.reservations}
function materialReserved(id){return materialReservations().filter(r=>r.materialId===id).reduce((a,r)=>a+Math.max(0,Number(r.remaining)||0),0)}
function materialAvailableStock(id){return Math.max(0,materialStock(id)-materialReserved(id))}
function farmSeedReserved(crop){return materialReservations().filter(r=>r.materialId===`farmseed:${crop}`).reduce((a,r)=>a+Math.max(0,Number(r.remaining)||0),0)}
function farmSeedAvailable(crop){return Math.max(0,farmSeedStock(crop)-farmSeedReserved(crop))}
function reserveTaskMaterial(taskId,materialId,qty,meta={}){qty=Math.max(0,Number(qty)||0);if(qty<=1e-9)return true;const available=materialId.startsWith('farmseed:')?farmSeedAvailable(materialId.slice(9)):materialAvailableStock(materialId);if(available+1e-9<qty)return false;materialReservations().push({id:uid(),taskId,materialId,qty,remaining:qty,createdAt:state.gameTime,...meta});return true}
function releaseTaskMaterialReservations(taskId){state.materials.reservations=materialReservations().filter(r=>r.taskId!==taskId)}
function consumeTaskReservedMaterial(taskId,materialId,qty,fieldId,category,note,crop){qty=Math.max(0,Number(qty)||0);if(qty<=1e-9)return true;const r=materialReservations().find(x=>x.taskId===taskId&&x.materialId===materialId&&Number(x.remaining)>1e-9);if(!r||Number(r.remaining)+1e-9<qty)return false;if(materialId.startsWith('farmseed:')){const ck=materialId.slice(9);if(farmSeedStock(ck)+1e-9<qty)return false;addFarmSeed(ck,-qty);finance('expense',0,'seed',fieldId,note||`Фермерские семена · ${CROPS[ck]?.label||ck}`,ck,true);}else{if(!consumeMaterial(materialId,qty,fieldId,category,note,crop))return false;}r.remaining=Math.max(0,Number(r.remaining)-qty);if(r.remaining<=1e-8)state.materials.reservations=materialReservations().filter(x=>x.id!==r.id);return true}
function buyMaterial(id,qty,supplierId=materialSupplierDraft[id]||'regional'){const m=MATERIALS[id];qty=Number(qty);if(!m||!Number.isFinite(qty)||qty<=0){toast('Укажите корректное количество');return}const sp=supplier(supplierId),kind=materialStorageKind(id),need=materialOrderStorageAmount(id,qty),free=materialStorageFree(kind);if(need>free+.0001){toast(`Недостаточно места в объекте «${infraSpec(kind).label}» с учётом заказов в пути: свободно ${num(free,kind==='chemicalStore'?0:1)} ${kind==='chemicalStore'?'л экв.':'т'}`);return}const q=materialPurchaseQuote(id,qty,{supplierId:sp.id}),cost=q.cost;if(state.money<cost){toast('Недостаточно средств');return}state.money-=cost;state.materials.orders=Array.isArray(state.materials.orders)?state.materials.orders:[];state.materials.orders.push({id:uid(),materialId:id,qty,cost,unit:q.unit,storageKind:kind,storageAmount:need,supplierId:sp.id,supplierLabel:sp.label,orderedAt:state.gameTime,readyAt:q.readyAt,status:'transit'});const disc=q.discount?` · оптовая скидка ${Math.round(q.discount*100)}% · экономия ${rub(q.savings)}`:'';finance('expense',cost,'inventory_purchase',null,`Заказ: ${m.label} · ${sp.label} · ${num(qty,2)} ${m.unit} · ${rub(q.unit)}/${m.unit}${disc}`);log(`Заказано: ${m.label} · ${num(qty,2)} ${m.unit} · доставка ${sp.days} дн.`);save();render();toast(`Заказ оформлен · прибытие через ${sp.days} дн.`)}
function buyMissingMaterial(id,required,label='материал'){
 const have=materialAvailableStock(id),missing=Math.max(0,required-have);if(missing<=1e-9)return true;
 const m=MATERIALS[id];if(!m)return false;const kind=materialStorageKind(id),need=materialOrderStorageAmount(id,missing),free=materialStorageFree(kind);if(need>free+.0001){toast(`Недостаточно места в «${infraSpec(kind).label}»: свободно ${num(free,kind==='chemicalStore'?0:1)} ${kind==='chemicalStore'?'л экв.':'т'}`);return false}
 const q=materialPurchaseQuote(id,missing,{urgent:true,supplierId:'fast'}),cost=q.cost;
 if(!confirm(`Недостаточно: ${label}.\nНужно: ${num(required,2)} ${m.unit}\nНа складе: ${num(have,2)} ${m.unit}\nЭкстренный самовывоз: ${num(missing,2)} ${m.unit}\nСтоимость: ${rub(cost)}\n\nПлановый заказ у поставщика занимает 3–14 дней и дешевле. Купить экстренно сейчас?`))return false;
 if(state.money<cost){toast('Недостаточно средств для закупки материала');return false}
 const oldQty=materialStock(id),oldAvg=materialAvgCost(id);state.money-=cost;addMaterial(id,missing);state.materials.avgCost[id]=(oldQty*oldAvg+cost)/(oldQty+missing);
 finance('expense',cost,'inventory_purchase',null,`Экстренный местный самовывоз: ${m.label} · ${num(missing,2)} ${m.unit}`);log(`Экстренно куплено: ${m.label} · ${num(missing,2)} ${m.unit} за ${rub(cost)}.`);save();return true;
}
function seedNeed(field,cropKey){const x=SEEDS[cropKey];return x?x.rate*field.ha:0}
const FARM_SEED_CROPS=new Set(['winter_wheat','spring_wheat','barley','spring_oats','winter_rye','spring_rye','oil_flax','buckwheat','rapeseed','soybean','peas']);
function farmSeedPenalty(crop){return crop==='rapeseed'?.08:(crop==='peas'||crop==='soybean')?.05:.06}
function farmSeedStock(crop){return Math.max(0,Number(state.materials?.farmSeeds?.[crop])||0)}
function addFarmSeed(crop,kg){state.materials=state.materials||{stocks:{},avgCost:{},farmSeeds:{}};state.materials.farmSeeds=state.materials.farmSeeds||{};state.materials.farmSeeds[crop]=Math.max(0,farmSeedStock(crop)+(Number(kg)||0))}
function seedTreatmentQuote(crop,outputKg){const sp=infraSpec('seedTreater'),kg=Math.max(0,Number(outputKg)||0),yieldFactor=.98,inputT=kg/1000/yieldFactor,processCost=Math.round(kg*(sp.costPerKg||0)),grainValue=Math.round(inputT*cropMarketPrice(crop)),replacement=Math.round(kg*materialMarketPrice('seed_'+crop)),saving=replacement-processCost-grainValue;return{crop,outputKg:kg,inputT,yieldFactor,processCost,grainValue,replacement,saving,hours:sp.tph>0?inputT/sp.tph:0}}
