function seedTreaterQueueEnd(){return (state.warehouse?.seedTreatmentJobs||[]).reduce((mx,j)=>Math.max(mx,Number(j.readyAt)||0),state.gameTime)}
function processSeedTreatment(){const jobs=state.warehouse?.seedTreatmentJobs||[];for(const j of jobs){if(j.readyAt>state.gameTime)continue;const freeT=materialStorageFree('seedStore');if(j.outputKg/1000>freeT+.0001){j.storageWaiting=true;j.readyAt=state.gameTime+3600000;continue;}addFarmSeed(j.crop,j.outputKg);j.done=true;log(`Протравитель: готово ${num(j.outputKg,0)} кг фермерских семян «${CROPS[j.crop].label}».`);}state.warehouse.seedTreatmentJobs=jobs.filter(j=>!j.done);}
function treatFarmSeed(crop,outputKg){if(!FARM_SEED_CROPS.has(crop)){toast('Эту культуру нельзя размножать через хозяйственный протравитель');return false}const sp=infraSpec('seedTreater');if(!(sp.tph>0)){toast('Сначала постройте протравитель семян');return false}const q=seedTreatmentQuote(crop,outputKg);if(q.outputKg<=0){toast('Укажите количество семян');return false}const reservedKg=(state.warehouse?.seedTreatmentJobs||[]).reduce((sum,j)=>sum+(Number(j.outputKg)||0),0),freeT=materialStorageFree('seedStore')-reservedKg/1000;if(q.outputKg/1000>freeT+.0001){toast(`Недостаточно свободного/незарезервированного места на семенном складе: доступно ${num(Math.max(0,freeT),1)} т`);return false}if((Number(state.warehouse.stocks[crop])||0)+1e-9<q.inputT){toast(`Недостаточно товарного зерна: нужно ${num(q.inputT,2)} т`);return false}if(state.money<q.processCost){toast('Недостаточно средств на протравливание');return false}const startAt=seedTreaterQueueEnd(),readyAt=startAt+q.hours*3600000,waitH=Math.max(0,(startAt-state.gameTime)/3600000);if(!confirm(`Поставить в очередь ${num(q.outputKg,0)} кг фермерских семян «${CROPS[crop].label}»?\n\nСо склада уйдёт: ${num(q.inputT,2)} т зерна\nОбработка: ${rub(q.processCost)}\nВремя обработки: ${durationText(q.hours)}${waitH>0?` · ожидание очереди ${durationText(waitH)}`:''}\nГотовность: ${dateFmt(readyAt)}`))return false;if(!withdrawWarehouseCrop(crop,q.inputT))return false;state.money-=q.processCost;state.warehouse.seedTreatmentJobs=state.warehouse.seedTreatmentJobs||[];state.warehouse.seedTreatmentJobs.push({id:'seedtr-'+uid(),crop,outputKg:q.outputKg,inputT:q.inputT,startedAt:startAt,orderedAt:state.gameTime,readyAt,processCost:q.processCost,storageWaiting:false});finance('expense',q.processCost,'seed_processing',null,`Протравливание собственного зерна · ${CROPS[crop].label} · ${num(q.outputKg,0)} кг`);log(`Протравитель: партия ${num(q.outputKg,0)} кг «${CROPS[crop].label}» поставлена в очередь, готовность ${dateFmt(readyAt)}.`);save();render();toast(`Партия поставлена в очередь · ${durationText(q.hours)}`);return true}

