const MARKET_ROTATION_CROPS=['winter_wheat','spring_wheat','barley','spring_oats','winter_rye','spring_rye','oil_flax','buckwheat','corn','sunflower','rapeseed','soybean','peas','sugar_beet','potato'];
function marketLandPriceMultiplier(status,r,soil=null){if(status==='abandoned')return .52+r()*.16;if(status==='fallow')return .78+r()*.12;const quality=soil?((soil.ph>=5.8&&soil.ph<=7.2?.025:0)+(soil.weeds<20?.02:0)+(soil.compaction<40?.02:0)):0;return .98+r()*.14+quality;}
