function marketNextCrop(prev,r){const guided=ROTATION_GUIDE[prev]?.next?.filter(k=>MARKET_ROTATION_CROPS.includes(k))||[];const pool=guided.length?guided:MARKET_ROTATION_CROPS.filter(k=>k!==prev);return pick(r,pool);}
