function processMarketLandYear(year){for(const f of state.fields||[]){if(f.owned||f.landProfile?.status==='abandoned')continue;const lp=f.landProfile||(f.landProfile={status:'working',previousCrop:f.lastCrop||null,yearsIdle:0}),r=rngFactory(((state.landSeed||1)^Math.imul(f.id,2654435761)^Math.imul(year,2246822519))>>>0);if(lp.status==='fallow'){const returnToCrop=lp.yearsIdle>=2||r()<.76;if(returnToCrop){const next=marketNextCrop(lp.previousCrop,r);lp.status='working';lp.previousCrop=next;lp.yearsIdle=0;f.lastCrop=next;f.soil.weeds=clamp(randInt(r,8,28),0,100);f.soil.compaction=clamp(randInt(r,20,50),0,100);f.soil.residue=clamp(['corn','sunflower'].includes(next)?randInt(r,50,78):randInt(r,22,52),0,100);lp.historyText=`Сезон ${year}: владелец вернул поле из пара и вырастил «${CROPS[next].label}». Поле снова в рабочем севообороте.`;}else{lp.yearsIdle=Math.min(3,(lp.yearsIdle||1)+1);f.soil.N=clamp(f.soil.N+5,0,120);f.soil.P=clamp(f.soil.P+1,0,120);f.soil.K=clamp(f.soil.K+1,0,120);f.soil.weeds=clamp(f.soil.weeds-5,4,100);f.soil.compaction=clamp(f.soil.compaction-2,10,100);lp.historyText=`Сезон ${year}: владелец оставил поле под чистым паром второй сезон. Предшественник — ${lp.previousCrop&&CROPS[lp.previousCrop]?CROPS[lp.previousCrop].label:'неизвестен'}.`;}}else{const prev=lp.previousCrop;const restChance=['sunflower','corn','sugar_beet','potato'].includes(prev)?.16:.10;if(r()<restChance){lp.status='fallow';lp.yearsIdle=1;lp.historyText=`Сезон ${year}: после «${prev&&CROPS[prev]?CROPS[prev].label:'предыдущей культуры'}» владелец перевёл поле в чистый пар.`;f.soil.weeds=clamp(f.soil.weeds-8,5,100);f.soil.compaction=clamp(f.soil.compaction-2,12,100);}else{const next=marketNextCrop(prev,r);lp.previousCrop=next;lp.yearsIdle=0;f.lastCrop=next;f.soil.N=clamp(f.soil.N-randInt(r,2,8)+(CROPS[next]?.group==='legume'?8:0),28,100);f.soil.P=clamp(f.soil.P-randInt(r,1,5),28,100);f.soil.K=clamp(f.soil.K-randInt(r,1,6),30,105);f.soil.weeds=clamp(randInt(r,8,32),0,100);f.soil.compaction=clamp(f.soil.compaction+randInt(r,-3,5),18,65);f.soil.residue=clamp(['corn','sunflower'].includes(next)?randInt(r,52,82):randInt(r,20,56),0,100);lp.historyText=`Сезон ${year}: выращена культура «${CROPS[next].label}» после «${prev&&CROPS[prev]?CROPS[prev].label:'неизвестного предшественника'}». Земля регулярно обрабатывается владельцем.`;}}lp.marketYear=year;refreshMarketFieldPrice(f,r);}}
function processMarketLandDynamics(){const current=new Date(state.gameTime).getFullYear();let last=Number(state.landMarketYear)||2026;while(last<current){last++;processMarketLandYear(last);}state.landMarketYear=current;refreshLandListings(state.gameTime);refreshMeadowListings(state.gameTime);}
function assignLandDistanceBands(list,r,targetHa){
 const total=Math.max(1,Number(targetHa)||list.reduce((a,x)=>a+(Number(x.ha)||0),0)),targets=[total*.50,total*.30,total*.20],bands=[[2,10],[11,30],[31,60]],used=[0,0,0],order=[...list];
 for(let i=order.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[order[i],order[j]]=[order[j],order[i]];}
 for(const f of order){const ha=Math.max(0,Number(f.ha)||0);let best=0,bestScore=-Infinity;for(let b=0;b<3;b++){const deficit=targets[b]-used[b],score=deficit/Math.max(1,targets[b]);if(score>bestScore){bestScore=score;best=b;}}const [lo,hi]=bands[best];f.distanceKm=+(lo+r()*(hi-lo)).toFixed(1);used[best]+=ha;}
 return{nearHa:used[0],midHa:used[1],farHa:used[2],totalHa:used.reduce((a,b)=>a+b,0)};
}
function landDistanceBandStats(list){const out={nearHa:0,midHa:0,farHa:0,totalHa:0};for(const f of list||[]){const ha=Math.max(0,Number(f.ha)||0),d=Number(f.distanceKm)||0;out.totalHa+=ha;if(d<=10)out.nearHa+=ha;else if(d<=30)out.midHa+=ha;else out.farHa+=ha;}return out;}
function generateLandMarket(seed,targetHa=CONFIG.landFundHa){const r=rngFactory(seed),count=920,counts={small:184,medium:552,large:184},ranges={small:[5,10],medium:[11,50],large:[51,300]},cats=[];for(const [cat,n] of Object.entries(counts))for(let i=0;i<n;i++)cats.push(cat);for(let i=cats.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[cats[i],cats[j]]=[cats[j],cats[i]];}const sizes=cats.map(cat=>randInt(r,ranges[cat][0],ranges[cat][1]));let total=sizes.reduce((a,b)=>a+b,0),delta=targetHa-total,guard=0;while(delta!==0&&guard++<200000){const i=Math.floor(r()*sizes.length),cat=cats[i],[lo,hi]=ranges[cat];if(delta>0&&sizes[i]<hi){sizes[i]++;delta--;}else if(delta<0&&sizes[i]>lo){sizes[i]--;delta++;}}if(delta!==0)throw new Error('Не удалось сформировать земельный фонд заданной площади');const out=sizes.map((ha,i)=>makeMarketField(ha,i,r));assignLandDistanceBands(out,r,targetHa);return out;}
function landMarketModeLabel(mode){return mode==='lease_only'?'Только аренда':mode==='buy_only'?'Только покупка':'Покупка или аренда'}
