function implementRequirementSpec(im){if(!im||im.type!=='implement'||im.selfPropelled)return{hydraulicLpm:0,pto:null,hitchClass:0,minMassT:0};const hp=Math.max(0,Number(im.requiredHp)||0),cat=im.category||'',wide=Math.max(0,Number(im.width)||0);const powered=['mower','baler','tedder','rake','sprayer'].includes(cat),pto=powered?(hp>=180?'1000':'540'):null;let hyd=0;if(['sow_grain','sow_row','sow_potato','sprayer','fertilizer','harvest_potato','harvest_beet'].includes(cat))hyd=30+hp*.16;else if(wide>=8||hp>=350)hyd=25+hp*.12;else if(hp>=180)hyd=25+hp*.07;hyd=Math.round(clamp(hyd,0,150));const heavy=['deepRip','plow','disk','stubble','cultivate','harrow','ridge'].includes(cat),minMass=heavy?hp*.024:hp*.012;const hitchClass=im.hitchClass||((wide<=4&&hp<180)?3:(wide<=6&&hp<300)?4:0);return{hydraulicLpm:hyd,pto,hitchClass,minMassT:+Math.max(0,minMass).toFixed(1)}}
function fieldTractionFactor(f){if(!f)return 1;const moisture=clamp(Number(f.moisture)||55,20,90);let x=moisture<=52?1.04:moisture<=62?1:moisture<=70?1-(moisture-62)*.018:1-(8*.018)-(moisture-70)*.027;x*=f.soil?.type==='Супесь'?1.05:f.soil?.type==='Суглинок'?.96:1;return clamp(x,.55,1.08)}
function implementDraftFactor(im){const c=im?.category||'';if(['deepRip','plow'].includes(c))return 1;if(['disk','stubble'].includes(c))return .82;if(['cultivate'].includes(c))return .72;if(['harrow','ridge'].includes(c))return .60;if(['sow_grain','sow_row','sow_potato'].includes(c))return .56;if(['mower','baler'].includes(c))return .50;return .46}
function tractorImplementCompatibility(ta,im,f=null){const tc=tractorCapabilitySpec(ta),req=implementRequirementSpec(im);if(!tc)return{ok:false,label:'нужен трактор'};if(tc.hp<(Number(im?.requiredHp)||0))return{ok:false,label:`мощность ${tc.hp}/${im.requiredHp} л.с.`};if(req.hydraulicLpm&&tc.hydraulicLpm<req.hydraulicLpm)return{ok:false,label:`гидравлика ${tc.hydraulicLpm}/${req.hydraulicLpm} л/мин`};if(req.pto&&!tc.pto.includes(req.pto))return{ok:false,label:`требуется ВОМ ${req.pto}`};if(req.hitchClass&&tc.hitchClass<req.hitchClass)return{ok:false,label:`навеска кат. ${tc.hitchClass}/${req.hitchClass}`};const mob=mobilitySpec(ta),wet=fieldTractionFactor(f),b=tc.ballast,available=tc.massT*(Number(mob.traction)||1)*b.traction*wet,required=Math.max(1,(Number(im?.requiredHp)||1)*.036*implementDraftFactor(im)),ratio=available/required;if(req.minMassT&&tc.massT<req.minMassT*.72)return{ok:false,label:`недостаточная сцепная масса ${num(tc.massT,1)}/${num(req.minMassT,1)} т`};if(f&&ratio<.66)return{ok:false,label:`недостаточная тяга на текущей почве (${Math.round(ratio*100)}%)`};return{ok:true,label:'совместимо',tractionRatio:ratio,availableTraction:available,requiredDraft:required,tractor:tc,requirements:req}}
function unitTractionDynamics(ta,im,f){const c=tractorImplementCompatibility(ta,im,f);if(!c.ok)return{...c,slipPct:100,rateFactor:0,fuelFactor:2,soilPressureFactor:1};const mob=mobilitySpec(ta),ratio=c.tractionRatio,wet=fieldTractionFactor(f),nominal=assetDriveType(ta)==='tracked'?5:assetDriveType(ta)==='halftrack'?6:8,excess=Math.max(0,1-ratio),slip=clamp(nominal+excess*31+Math.max(0,1-wet)*12,nominal,30),rate=clamp(1-Math.max(0,slip-5)*.007,.68,1),fuel=clamp((Number(mob.fieldFuel)||1)*(1+Math.max(0,slip-5)*.009)*c.tractor.ballast.fuel,.92,1.38),pressure=(Number(mob.soilPressure)||1)*c.tractor.ballast.soilPressure;return{...c,slipPct:slip,rateFactor:rate,fuelFactor:fuel,soilPressureFactor:pressure}}
function ballastControlsHtml(a){const m=equipmentModel(a?.modelId);if(m?.type!=='tractor')return'';const tc=tractorCapabilitySpec(a);return `<div class="note info"><b>Балластировка и тяга.</b> Текущая расчётная масса ${num(tc.massT,1)} т · гидравлика ≈ ${tc.hydraulicLpm} л/мин · навеска кат. ${tc.hitchClass}. Тяжёлый балласт улучшает сцепление, но увеличивает давление на почву и расход.</div><label class="small">Балласт <select class="select compact" data-ballast="${a.id}">${Object.values(BALLAST_PROFILES).map(x=>`<option value="${x.id}" ${x.id===a.ballastLevel?'selected':''}>${x.label}</option>`).join('')}</select></label>`}
function implementConditionFactors(a){const m=equipmentModel(a?.modelId);if(!m||m.type!=='implement'||m.selfPropelled)return{rate:1,fuel:1,quality:1,score:100};const c=k=>Number.isFinite(Number(a.systems?.[k]))?clamp(Number(a.systems[k]),0,100):100,d=k=>Math.max(0,78-c(k))/68;const wd=d('working'),md=d('metering'),dd=d('drive'),fd=d('frame'),hd=d('hydraulics'),rd=d('running');const rate=clamp(1-.22*wd-.12*dd-.10*fd-.06*hd-.05*rd,.68,1),fuel=clamp(1+.10*wd+.08*dd+.04*rd,1,1.18),quality=clamp(1-.13*wd-.09*md-.03*fd-.02*hd,.80,1),score=clamp(Math.round((rate*.42+quality*.58)*100),0,100);return{rate,fuel,quality,score};}
function nextTrackInventoryId(){const inv=state.equipment.trackInventory=Array.isArray(state.equipment.trackInventory)?state.equipment.trackInventory:[];let n=0;for(const x of inv){const z=String(x.id||'').match(/^TRK-(\d+)$/);if(z)n=Math.max(n,+z[1]);}return'TRK-'+String(n+1).padStart(4,'0')}
function trackSaleValue(x){const m=equipmentModel(x.modelId),v=trackSpecById(m,x.trackId);if(!v)return 0;const raw=Math.max(20000,Math.round(v.price*(.20+.007*clamp(Number(x.condition)||50,1,100))*clamp(1-(Number(x.hours)||0)/16000,.52,1)*.82/10000)*10000);return Number.isFinite(Number(x.acquiredPrice))?Math.min(raw,Math.max(10000,Math.floor(Number(x.acquiredPrice)*.92/10000)*10000)):raw}
function trackSwapQuote(a,targetId){const m=equipmentModel(a?.modelId),to=trackSpecById(m,targetId),from=assetTrackSpec(a);if(!m||!to)return null;const item=(state.equipment.trackInventory||[]).filter(x=>x.modelId===m.id&&x.trackId===to.id).sort((x,y)=>y.condition-x.condition||x.hours-y.hours)[0]||null;if(to.id===from?.id&&!item&&!a?.criticalDeadSystems?.tracks)return null;const parts=item?0:to.price,labor=Math.max(40000,Math.round(to.installHours*3800/10000)*10000);return{from,to,item,partsCost:parts,laborCost:labor,cost:parts+labor,hours:to.installHours}}
function startTrackSwap(assetId,targetId){const a=state.equipment.fleet.find(x=>x.id===assetId),q=a&&trackSwapQuote(a,targetId);if(!q)return toast('Эта ходовая недоступна');if(a.repairReason||(a.busyUntil||0)>state.gameTime)return toast('Техника занята или находится в сервисе');if(state.money<q.cost)return toast(`Нужно ${rub(q.cost)}`);if(!confirm(`${a.farmId} · смена ходовой\n${q.from?.name||driveTypeLabel(baseDriveType(equipmentModel(a.modelId)))} → ${q.to.name}\nКомплект: ${rub(q.partsCost)}\nРабота: ${rub(q.laborCost)}\nПростой: ≈ ${durationText(q.hours)}\n\nНачать?`))return;state.money-=q.cost;finance('expense',q.cost,'equipment_service',null,`Ходовая ${a.farmId}: ${q.to.name}`);a.repairReason=`Смена ходовой: ${q.to.name}`;a.repairSystem='tracks';a.serviceJob={type:'track_swap',targetTrackId:q.to.id,targetInventoryId:q.item?.id||null,newTrackPurchased:!q.item,cost:q.cost,partsCost:q.partsCost,laborCost:q.laborCost};a.repairUntil=state.gameTime+q.hours*3600000;a.busyUntil=a.repairUntil;save();render()}
