const NEW_WEAR_PROTECTION_HOURS=5000;
const NEW_IMPLEMENT_WEAR_PROTECTION_HOURS=2500;
const NEW_NODE_WEAR_PROTECTION_HOURS=3000;
const NEW_RUNNING_GEAR_WEAR_PROTECTION_HOURS=1500;
function hasCapitalRepair(a){return Array.isArray(a?.serviceHistory)&&a.serviceHistory.some(h=>h?.mode==='capital');}
function assetWearProtectionLimit(a){const m=equipmentModel(a?.modelId);return m&&!isPoweredSelfPropelled(m)?NEW_IMPLEMENT_WEAR_PROTECTION_HOURS:NEW_WEAR_PROTECTION_HOURS;}
