function protectedWearHours(a,workHours,startHours=null){workHours=Math.max(0,Number(workHours)||0);const h0=startHours===null?Math.max(0,Number(a?.hours)||0):Math.max(0,Number(startHours)||0),lim=assetWearProtectionLimit(a);if(!a||a.source!=='new'||hasCapitalRepair(a)||h0>=lim)return 0;return Math.max(0,Math.min(workHours,lim-h0));}
