const SERVICE_SIMPLE_SYSTEMS=new Set(['running','tires','tracks','working','frame']);
const SERVICE_COMPLEX_SYSTEMS=new Set(['engine','transmission','hydraulics','metering','drive']);
function workshopSlots(){return Math.max(0,Number(infraSpec('workshop')?.cap)||0)}
function workshopBusySlots(){return (state.equipment?.fleet||[]).filter(a=>a.repairReason&&a.repairUntil>state.gameTime&&a.serviceJob?.location==='workshop').length}
function serviceFleetSpec(){return infraSpec('serviceFleet')}
function serviceFleetBusyTeams(){return (state.equipment?.fleet||[]).filter(a=>a.repairReason&&a.repairUntil>state.gameTime&&a.serviceJob?.location==='field'&&a.serviceJob?.provider==='own').length}
function modelServiceTechnology(m){const y=Number(m?.years?.[0])||1980;if(m?.segment==='domestic_used')return'legacy';if(m?.segment==='foreign_new'||(m?.segment==='domestic_new'&&y>=2012))return'modern';if(m?.segment==='foreign_used'&&y>=2008)return'modern';return'mechanical'}
