function brandServiceLabel(m){const b=String(m?.brand||'').trim();return b?`Представитель ${b}`:'Представитель бренда'}
function ownWorkshopCanHandle(a,target='all',mode='partial'){const cls=repairSkillClass(a,target,mode),lvl=infraLevel('workshop');if(cls==='brand')return false;if(cls==='simple')return lvl>=1;if(cls==='heavy_mechanical')return lvl>=2;if(cls==='specialist')return lvl>=3;return false}
function fieldRepairEligible(a,target='all',mode='partial'){if(mode==='capital')return false;const m=equipmentModel(a?.modelId),cls=repairSkillClass(a,target,mode),keys=target==='all'?repairableKeys(a,'all'):[target];if(!a?.breakdownFieldId||infraLevel('serviceFleet')<1)return false;if(cls==='brand')return false;if(mode==='replace'&&keys.some(k=>['engine','transmission','frame','drive'].includes(k)))return false;if(keys.some(k=>['frame','engine','transmission'].includes(k))){return mode==='partial'&&modelServiceTechnology(m)==='legacy'&&infraLevel('serviceFleet')>=2&&keys.every(k=>k!=='frame');}return keys.every(k=>SERVICE_SIMPLE_SYSTEMS.has(k)||k==='hydraulics'||k==='metering'||k==='drive')}
function assetServiceMassT(a){const m=equipmentModel(a?.modelId);if(!m)return 5;if(m.type==='tractor')return tractorBaseWeightT(a);if(m.type==='combine')return clamp(8+(Number(assetEngineSpec(a)?.hp||m.hp)||200)/35,10,28);if(m.type==='truck')return clamp(7+(Number(m.capacityT)||8)*.45,8,22);if(m.selfPropelled)return clamp(5+(Number(m.hp)||150)/45,6,22);if(m.type==='implement')return clamp(1.5+(Number(m.requiredHp)||80)/55,2,18);return 5}
