function towQuote(a){const d=repairFieldDistanceKm(a),mass=assetServiceMassT(a),heavy=Math.max(0,mass-8),cost=d>0?Math.round((30000+d*2400+heavy*6500)/5000)*5000:0,hours=d>0?clamp(1.2+d/32+heavy*.035,1.5,10):0;return{distanceKm:d,massT:mass,cost,hours,label:d>0?`Эвакуация ${num(d,1)} км · ${num(mass,1)} т`:'Техника на базе'}}
function brandServiceArrivalHours(m,distanceKm=0,contract=false){distanceKm=Math.max(0,Number(distanceKm)||0);const seg=String(m?.segment||''),foreign=seg.startsWith('foreign'),base=seg==='foreign_new'?18:seg==='foreign_used'?22:12,roadKph=foreign?65:70,raw=base+distanceKm/roadKph;return contract?raw*.50:raw}
function servicePartsLogistics(a,target='all',mode='partial',plan=null){const m=equipmentModel(a?.modelId),sp=serviceProfile(m),breakdown=String(a?.repairReason||'').startsWith('Неисправность');if(!m||!breakdown||mode!=='partial')return{waitH:0,days:0,source:'scheduled',label:'Запчасти подготовлены заранее'};let stocked=false;if(target&&target!=='all'&&typeof criticalWarehouseItem==='function')stocked=!!criticalWarehouseItem(a,target);if(stocked)return{waitH:0,days:0,source:'warehouse',label:'Запчасть на складе хозяйства'};let days=Math.max(0,Number(sp.partsDays)||0),source,label;if(m.segment==='foreign_used'||m.segment==='foreign_new'){source='import_order';label='Импортная запчасть под заказ';}else if(days<=1){source='local_stock';label='Местный склад/разборка';}else{source='regional_order';label='Региональный склад запчастей';}if(plan?.contractActive&&source==='import_order'){days=Math.max(1,days*.75);label+=' · сервисный договор';}const waitH=days*24;return{waitH,days,source,label};}
