function systemValues(a){return Object.values(a.systems||{}).filter(Number.isFinite)}
function assetMaxCondition(a){const ov=Math.max(0,Number(a?.nodeCapitalOverhauls?.frame)||0);return clamp(resourceCapForHours(Math.max(0,Number(a?.hours)||0))-ov*1.25,45,100)}
