function capAssetSystems(a){const chassisCap=assetMaxCondition(a);for(const k of Object.keys(a.systems||{}))if(Number.isFinite(a.systems[k]))a.systems[k]=clamp(a.systems[k],1,systemMaxCondition(a,k));return chassisCap}
