function sellEquipment(assetId){const i=state.equipment.fleet.findIndex(a=>a.id===assetId);if(i<0)return;const a=state.equipment.fleet[i],m=equipmentModel(a.modelId),chk=canSellAsset(a);if(!chk.ok){toast(chk.label);return}const value=assetSaleValue(a);if(!confirm(`Продать ${a.farmId} · ${m.name} за ${rub(value)}?${m.type==='tractor'&&assetEngineSpec(a)?`\nВ цену входит установленный двигатель: ${assetEngineSpec(a).name}.\nСнятые двигатели на складе останутся вашей собственностью.`:''}`))return;state.equipment.fleet.splice(i,1);state.money+=value;finance('income',value,'equipment_sale',null,`Продажа техники ${a.farmId}: ${m.name}`);log(`Продана техника ${a.farmId}: ${m.name} за ${rub(value)}.`);if(selectedEquipmentId===assetId){selectedEquipmentId=null;page='equipment';}save();render();toast(`Техника продана · +${rub(value)}`)}
function assetFree(a){if(a?.engineMissing)return false;return (a.busyUntil||0)<=state.gameTime&&(a.repairUntil||0)<=state.gameTime&&!a.repairReason&&recalcAssetCondition(a)>10}
function implementCategoryFor(op,cropKey){if(op==='sow'){if(cropKey==='potato')return'sow_potato';return rowCrops.has(cropKey)?'sow_row':'sow_grain';}if(op==='harvest'&&cropKey==='potato')return'harvest_potato';if(op==='harvest'&&cropKey==='sugar_beet')return'harvest_beet';return OP_EQUIP[op]||null}
function operationImplementWidth(im,op){if(op==='lime'&&Number(im?.limeWidth)>0)return Number(im.limeWidth);return Number(im?.width)||0;}
function operationImplementSpeed(im,op){if(op==='lime'&&Number(im?.limeSpeed)>0)return Number(im.limeSpeed);return Number(im?.speed)||0;}
function operationImplementRate(im,op,effDefault=.78){return Math.max(.01,operationImplementWidth(im,op)*operationImplementSpeed(im,op)*(Number(im?.eff)||effDefault)/10);}
function fertilizerImplementSupportsOperation(im,op){if(im?.category!=='fertilizer')return true;if(op==='lime')return !!(im.limeCapable===true||im.fertilizerKinds?.includes('lime'));return im.fertilizerKinds===undefined||!!im.fertilizerKinds?.includes('granular');}
function implementSupports(im,op,cropKey){if(!im||im.type!=='implement')return false;if(op==='grainWindrow')return !!(im.grainWindrow||im.category==='grain_windrower'||(im.supportedCategories||[]).includes('grain_windrower'));if(op==='sow'&&cropKey==='soybean')return ['sow_grain','sow_row'].includes(im.category)&&fertilizerImplementSupportsOperation(im,op);const cat=implementCategoryFor(op,cropKey);return !!cat&&modelSupportsCategory(im,cat)&&fertilizerImplementSupportsOperation(im,op);}
function seedingModeLabel(x){return {conventional:'классическая',minTill:'минимальная',noTill:'прямой посев'}[x]||x;}
function seederFieldCompatibility(im,f,cropKey){if(!im||!f||!['sow_grain','sow_row','sow_potato'].includes(im.category))return{ok:true,label:'Совместимо'};if(im.category==='sow_potato')return{ok:true,label:'Совместимо'};const tech=f.technology||'conventional',modes=Array.isArray(im.seedingModes)?im.seedingModes:['conventional'];if(!modes.includes(tech))return{ok:false,label:`Сеялка не рассчитана на технологию «${TECH[tech]?.label||seedingModeLabel(tech)}»`};const seedbed=Number(f.soil?.seedbed)||0,c=CROPS[cropKey]||CROPS.spring_wheat;if(tech==='conventional'&&seedbed<Math.max(50,(Number(c?.seedbed)||60)-10)&&!im.seedbedPrep)return{ok:false,label:'Нужна сеялка-комбинация с предпосевной подготовкой или лучшее посевное ложе'};if(tech==='minTill'&&seedbed<42&&!im.directDrill&&!im.seedbedPrep)return{ok:false,label:'При слабой подготовке нужна комбинированная/прямого посева сеялка'};if(tech==='noTill'&&!im.directDrill)return{ok:false,label:'Для No-Till требуется сеялка прямого посева'};return{ok:true,label:'Совместимо'};}
function headerCategoryFor(cropKey){if(cropKey==='corn')return'corn';if(cropKey==='sunflower')return'sunflower';return grainCrops.has(cropKey)?'grain':null}
function headerPurposeLabel(m){if(!m||m.type!=='header')return'';return m.category==='corn'?'Кукурузная жатка':m.category==='sunflower'?'Жатка для подсолнечника':m.category==='pickup_grain'?'Платформа-подборщик зерновых валков':m.category==='grain_windrow'?'Валковая зерновая жатка':'Зерновая жатка';}
function headerPurposeCrops(m){if(!m||m.type!=='header')return'';return m.category==='corn'?'Кукуруза на зерно':m.category==='sunflower'?'Подсолнечник':m.category==='grain_windrow'?'Зерновые, зернобобовые и рапс для раздельной уборки':'Пшеница, ячмень, рапс, горох, соя';}
function headerCompatible(combineModel,headerModel){if(!combineModel||!headerModel||combineModel.type!=='combine'||headerModel.type!=='header')return false;const hc=Array.isArray(headerModel.compatibleCombineIds)?headerModel.compatibleCombineIds:null,ch=Array.isArray(combineModel.compatibleHeaderIds)?combineModel.compatibleHeaderIds:null;if(hc&&ch)return hc.includes(combineModel.id)&&ch.includes(headerModel.id);return false;}
function headerCompatibleForCrop(combineModel,headerModel,cropKey){return headerCategoryFor(cropKey)===headerModel?.category&&headerCompatible(combineModel,headerModel);}
function headerWorkRate(h){const explicit=Number(h?.fieldCapacityHaH);if(Number.isFinite(explicit)&&explicit>0)return explicit;return Math.max(.1,(Number(h?.width)||0)*(Number(h?.speed)||0)*(Number(h?.eff)||.72)/10);}
