function serviceEventCount(a,k){return (a.serviceHistory||[]).filter(h=>(h.mode==='partial'||h.mode==='capital')&&(h.target==='all'||h.target===k)).length}
function systemLifetimeHours(a,k){if(k==='engine'&&isPoweredSelfPropelled(equipmentModel(a.modelId)))return Math.max(0,Number(a.engineHours)||0);if(['transmission','running','hydraulics'].includes(k)&&isPoweredSelfPropelled(equipmentModel(a.modelId)))return Math.max(0,Number(a.componentHours?.[k])||0);if(k==='tires')return Math.max(0,Number(a.tireHours)||0);if(k==='tracks')return Math.max(0,Number(a.trackHours)||0);return Math.max(0,Number(a.nodeHours?.[k]??a.hours)||0)}
function systemCapitalOverhauls(a,k){if(k==='engine'&&isPoweredSelfPropelled(equipmentModel(a.modelId)))return Math.max(0,Number(a.engineCapitalOverhauls)||0);if(['transmission','running','hydraulics'].includes(k)&&isPoweredSelfPropelled(equipmentModel(a.modelId)))return Math.max(0,Number(a.componentCapitalOverhauls?.[k])||0);return Math.max(0,Number(a.nodeCapitalOverhauls?.[k])||0)}
const PREVENTIVE_BASE_INTERVALS={engine:400,transmission:600,running:500,hydraulics:450,tires:300,tracks:350,working:180,metering:220,drive:260,frame:650};
function preventiveInterval(a,k){const m=equipmentModel(a?.modelId),tech=modelServiceTechnology(m),base=PREVENTIVE_BASE_INTERVALS[k]||400,mult=tech==='legacy'?.82:tech==='modern'?1.18:1;return Math.max(100,Math.round(base*mult/25)*25)}
