function preventiveLastHours(a,k){const h=Number(a?.preventiveLastHours?.[k]);return Number.isFinite(h)?Math.max(0,h):0}
function preventiveDueInfo(a,k){const interval=preventiveInterval(a,k),cur=preventiveCurrentHours(a,k),last=preventiveLastHours(a,k),used=Math.max(0,cur-last),left=interval-used;return{interval,cur,last,used,left,due:left<=0,soon:left>0&&left<=Math.min(120,interval*.25)}}
function preventiveRiskFactor(a,k){const d=preventiveDueInfo(a,k);if(d.due)return 1;if(d.used<=d.interval*.35)return .82;if(d.used<=d.interval*.70)return .88;return .94}
function diagnosticFresh(a){return !!a?.preseasonDiagnostic&&Number(a.preseasonDiagnostic.validUntilHours||0)>Number(a.hours||0)}
function diagnosticForecast(a,horizon=250){const rows=assetCriticalRiskSummary(a).map(x=>({key:x.key,pct:x.pct,operationPct:(1-Math.pow(1-x.pct/100,horizon/100))*100,due:preventiveDueInfo(a,x.key)}));return{hours:horizon,rows,high:rows.filter(x=>x.operationPct>=1||x.due.due),max:rows[0]||null}}
function diagnosticQuote(a){const m=equipmentModel(a?.modelId),keys=Object.keys(a?.systems||{}).filter(k=>Number.isFinite(a.systems[k]));if(isPoweredSelfPropelled(m)&&(a.tireId||a.trackId))keys.push(assetDriveType(a)==='wheeled'?'tires':'tracks');const base=m?.type==='combine'?42000:isPoweredSelfPropelled(m)?26000:15000,cost=Math.round((base+keys.length*3500)/5000)*5000,hours=clamp(1.5+keys.length*.55,2,7);return{cost,hours,keys}}
function serviceContractKey(m){return String(m?.brand||'').trim()||'GENERIC'}
function serviceContractActive(m){const c=state?.infrastructure?.serviceContracts?.[serviceContractKey(m)];return !!c&&Number(c.expiresAt)>state.gameTime}
function brandContractQuote(brand){const assets=(state.equipment?.fleet||[]).filter(a=>serviceContractKey(equipmentModel(a.modelId))===brand&&modelServiceTechnology(equipmentModel(a.modelId))==='modern'),value=assets.reduce((sum,a)=>sum+(Number(a.purchasePrice)||Number(equipmentModel(a.modelId)?.price)||0),0),foreign=assets.some(a=>String(equipmentModel(a.modelId)?.segment||'').startsWith('foreign')),base=foreign?220000:140000,cost=Math.max(base,Math.round((base+value*.0028+assets.length*20000)/10000)*10000);return{brand,count:assets.length,value,cost,days:365,arrivalMult:.50,laborMult:.82,calloutMult:.40}}
function buyServiceContract(brand){const q=brandContractQuote(brand);if(!q.count)return toast('В парке нет современной техники этого бренда');if(state.money<q.cost)return toast(`Нужно ${rub(q.cost)}`);if(!confirm(`Сервисный договор ${brand}\nСрок: 1 год\nТехника в парке: ${q.count}\nСтоимость: ${rub(q.cost)}\n\nДоговор даёт приоритетный выезд: время приезда сокращается примерно на 50%, работа дешевле на 18%, а выездная часть счёта — примерно на 60%. Оформить?`))return;state.money-=q.cost;state.infrastructure.serviceContracts=state.infrastructure.serviceContracts||{};state.infrastructure.serviceContracts[brand]={brand,startedAt:state.gameTime,expiresAt:state.gameTime+365*DAY,cost:q.cost};finance('expense',q.cost,'equipment_service',null,`Сервисный договор ${brand} · 1 год`);save();render();toast(`Сервисный договор ${brand} активирован`)}
function preventiveServiceQuote(a,keys=null){const m=equipmentModel(a?.modelId),all=(keys||Object.keys(a?.systems||{}).filter(k=>Number.isFinite(a.systems[k]))).filter(k=>Number.isFinite(a.systems?.[k])&&!a.criticalDeadSystems?.[k]),due=all.filter(k=>{const d=preventiveDueInfo(a,k);return d.due||d.soon||criticalFailureRisk100h(a,k)>=.35||Number(a.systems[k])<75});const chosen=due.length?due:all.filter(k=>preventiveDueInfo(a,k).left<=180);const ks=chosen.length?chosen:all.slice(0,Math.min(2,all.length)),parts=ks.reduce((sum,k)=>sum+Math.max(2500,Math.round((equipmentModel(a.modelId)?.price||500000)*({engine:.0012,transmission:.001,hydraulics:.0007,running:.0007,working:.0008,metering:.0008,drive:.0008,frame:.0004}[k]||.0005)/1000)*1000),0),hours=Math.max(1,ks.length*1.25),cost=Math.round((parts+hours*2800)/1000)*1000;return{keys:ks,cost,hours}}
function startPreseasonDiagnostic(assetId){const a=state.equipment.fleet.find(x=>x.id===assetId);if(!a)return;if(a.repairReason||(a.busyUntil||0)>state.gameTime)return toast('Техника занята');const q=diagnosticQuote(a),plan=serviceExecutionPlan(a,'all','partial',{preferField:false}),m=equipmentModel(a.modelId),contract=plan.provider==='brand'&&serviceContractActive(m);let cost=Math.round(q.cost*(contract?.86:1)/1000)*1000,hours=q.hours*(contract?.85:1)+plan.arrivalH*(contract?.55:1);if(state.money<cost)return toast(`Нужно ${rub(cost)}`);state.money-=cost;finance('expense',cost,'equipment_service',null,`Предсезонная диагностика ${a.farmId}`);a.repairReason='Предсезонная диагностика';a.repairSystem=null;a.serviceJob={type:'preseason_diagnostic',cost,keys:q.keys,provider:plan.provider,providerLabel:plan.label,location:plan.location,startedAt:state.gameTime};a.repairUntil=state.gameTime+hours*3600000;a.busyUntil=a.repairUntil;save();render()}
function prepareForSeasonQuote(a){const d=diagnosticQuote(a),p=preventiveServiceQuote(a),m=equipmentModel(a.modelId),plan=serviceExecutionPlan(a,p.keys[0]||'all','partial',{preferField:false}),contract=plan.provider==='brand'&&serviceContractActive(m),cost=Math.round((d.cost+p.cost)*(contract?.86:1)/1000)*1000,hours=(d.hours+p.hours)*plan.hourMult+plan.arrivalH*(contract?.55:1);return{...p,diagnosticCost:d.cost,cost,hours,plan}}
function startPrepareForSeason(assetId){const a=state.equipment.fleet.find(x=>x.id===assetId);if(!a)return;if(a.repairReason||(a.busyUntil||0)>state.gameTime)return toast('Техника занята');const q=prepareForSeasonQuote(a);if(state.money<q.cost)return toast(`Нужно ${rub(q.cost)}`);const list=q.keys.map(assetSystemLabel).join(', ')||'основные системы';if(!confirm(`${a.farmId} · подготовка к сезону\nДиагностика + профилактика: ${list}\nСтоимость: ${rub(q.cost)}\nПростой: ≈ ${durationText(q.hours)}\n\nПровести?`))return;state.money-=q.cost;finance('expense',q.cost,'equipment_service',null,`Подготовка к сезону ${a.farmId}`);a.repairReason='Подготовка к сезону';a.serviceJob={type:'season_prepare',cost:q.cost,keys:q.keys,provider:q.plan.provider,providerLabel:q.plan.label,location:q.plan.location,startedAt:state.gameTime};a.repairUntil=state.gameTime+q.hours*3600000;a.busyUntil=a.repairUntil;save();render()}
function spareRiskAnalytics(){const fleet=state.equipment?.fleet||[],groups=new Map();for(const a of fleet){const m=equipmentModel(a.modelId);for(const x of assetCriticalRiskSummary(a)){if(x.pct<.18)continue;const key=`${m.id}:${x.key}`,rec=groups.get(key)||{modelId:m.id,modelName:m.name,key:x.key,count:0,risk500:0,maxRisk:0,inventory:0};rec.count++;rec.risk500+=1-Math.pow(1-x.pct/100,5);rec.maxRisk=Math.max(rec.maxRisk,x.pct);groups.set(key,rec);}}for(const r of groups.values()){if(r.key==='engine')r.inventory=(state.equipment.engineInventory||[]).filter(x=>engineSpecById(equipmentModel(r.modelId),x.engineId)).length;else if(r.key==='tires')r.inventory=(state.equipment.tireInventory||[]).filter(x=>x.modelId===r.modelId).length;else if(r.key==='tracks')r.inventory=(state.equipment.trackInventory||[]).filter(x=>x.modelId===r.modelId).length;else r.inventory=(state.equipment.componentInventory||[]).filter(x=>x.system===r.key).length;}return[...groups.values()].sort((a,b)=>b.risk500-a.risk500||b.maxRisk-a.maxRisk).slice(0,12)}
function renderSpareRiskGroups(spares){if(!spares?.length)return '<div class="empty">Сейчас нет узлов с заметным суммарным риском.</div>';const by=new Map();for(const r of spares){const g=by.get(r.modelId)||{modelId:r.modelId,modelName:r.modelName,count:0,maxRisk:0,rows:[]};g.count=Math.max(g.count,r.count);g.maxRisk=Math.max(g.maxRisk,r.risk500);g.rows.push(r);by.set(r.modelId,g);}return `<div class="spare-risk-groups">${[...by.values()].sort((a,b)=>b.maxRisk-a.maxRisk).map(g=>`<details class="operation-field spare-risk-group"><summary><b>${g.modelName}</b> · ${g.count} машин · максимальный риск ${num(g.maxRisk*100,1)}% <span class="muted tiny">· ${g.rows.length} узл.</span></summary><div class="table-wrap"><table><thead><tr><th>УЗЕЛ</th><th>МАШИН</th><th>РИСК 500 Ч</th><th>НА СКЛАДЕ</th><th>РЕКОМЕНДАЦИЯ</th></tr></thead><tbody>${g.rows.map(r=>`<tr><td>${assetSystemLabel(r.key)}</td><td>${r.count}</td><td>${num(r.risk500*100,1)}%</td><td>${r.inventory}</td><td>${r.inventory>0?'<span class="status good">запас есть</span>':r.risk500>=.025?'<span class="status warn">рассмотреть запас</span>':'наблюдать'}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}</div>`;}

