const DELIVERY_CONTRACT_CUSTOMERS=['Региональная мельница','Мукомольный комбинат','Маслозавод','Крахмальный завод','Комбикормовый завод','Семенной центр','Перерабатывающий комбинат','Областной элеватор'];
const FORAGE_DELIVERY_CUSTOMERS=['Молочный комплекс','Животноводческий комплекс','Конный завод','Откормочная площадка','Региональный кормовой холдинг','Фермерский кооператив'];
function deliveryContractsDefault(){return{offers:[],active:[],history:[],nextSerial:1,lastRefreshKey:null,totalIncome:0,completed:0,failed:0,totalPenalties:0};}
function normalizeDeliveryContracts(x){x=x&&typeof x==='object'?x:{};return{offers:Array.isArray(x.offers)?x.offers.filter(o=>o&&CROPS[o.crop]):[],active:Array.isArray(x.active)?x.active.filter(o=>o&&CROPS[o.crop]):[],history:Array.isArray(x.history)?x.history.slice(-200):[],nextSerial:Math.max(1,Number(x.nextSerial)||1),lastRefreshKey:x.lastRefreshKey??null,totalIncome:Math.max(0,Number(x.totalIncome)||0),completed:Math.max(0,Number(x.completed)||0),failed:Math.max(0,Number(x.failed)||0),totalPenalties:Math.max(0,Number(x.totalPenalties)||0)};}
function deliveryPeakReferencePrice(crop,quality){const now=state.gameTime,points=ensureSalePoints().filter(pt=>baleProducts.has(crop)?String(pt.id).startsWith('forage_'):rootCrops.has(crop)?String(pt.id).startsWith('root_'):!String(pt.id).startsWith('root_')&&!String(pt.id).startsWith('forage_')),vals=[];for(let m=0;m<12;m++){const d=new Date(now),ms=new Date(d.getFullYear(),d.getMonth()+m,15,12).getTime();let best=0;for(const pt of points)best=Math.max(best,Math.round(cropMarketPrice(crop,ms)*(pt.priceMult||1)*qualityBuyerMultiplier(quality,pt)));vals.push(best);}vals.sort((a,b)=>a-b);const mid=vals.length?vals[Math.floor(vals.length*.55)]:CROPS[crop]?.price||1;return Math.max(mid,CROPS[crop]?.price*.88||1);}
function deliveryOfferGenerate(idx,now=state.gameTime){
 const seed=(state.landSeed^hashString(`delivery:${currentYear()}:${idx}:${state.deliveryContracts.nextSerial}`))>>>0,r=rngFactory(seed),forageSlot=idx%4===1;
 const cropKeys=forageSlot?[...baleProducts]:Object.keys(CROPS).filter(k=>CROPS[k].fieldCrop!==false&&!baleProducts.has(k)&&(Number(CROPS[k].price)||0)>0);
 const crop=cropKeys[(idx+Math.floor(r()*cropKeys.length))%cropKeys.length],forage=baleProducts.has(crop),safe=cropSafeMoisture(crop),root=rootCrops.has(crop);
 let quality,maxMoist,tons,customer;
 if(forage){
  if(crop==='hay'){quality=Math.round(76+r()*12);maxMoist=Math.round((17+r()*3)*10)/10;tons=Math.round((25+r()*150)*10)/10;}
  else if(crop==='meadow_hay'){quality=Math.round(66+r()*17);maxMoist=Math.round((18+r()*4)*10)/10;tons=Math.round((30+r()*180)*10)/10;}
  else{quality=Math.round(62+r()*20);maxMoist=Math.round((18+r()*4)*10)/10;tons=Math.round((35+r()*220)*10)/10;}
  customer=FORAGE_DELIVERY_CUSTOMERS[Math.floor(r()*FORAGE_DELIVERY_CUSTOMERS.length)];
 }else{
  quality=Math.round(68+r()*20);maxMoist=safe==null?null:Math.round((safe+r()*1.4)*10)/10;tons=Math.round((root?(180+r()*900):(40+r()*260))*10)/10;customer=DELIVERY_CONTRACT_CUSTOMERS[Math.floor(r()*DELIVERY_CONTRACT_CUSTOMERS.length)];
 }
 const premium=1.03+r()*.08,unitPrice=Math.round(deliveryPeakReferencePrice(crop,quality)*premium/10)*10,gross=Math.round(tons*unitPrice),penalty=Math.round(gross*(.10+r()*.05)),id='S-'+String(state.deliveryContracts.nextSerial++).padStart(6,'0');
 return{id,crop,customer,tons,minQuality:quality,maxMoisture:maxMoist,unitPrice,gross,penalty,createdAt:now,availableUntil:now+(20+Math.floor(r()*25))*DAY,contractMonths:12+Math.floor(r()*13),status:'offer'};
}
function refreshDeliveryContracts(force=false){state.deliveryContracts=normalizeDeliveryContracts(state.deliveryContracts);const key=currentYear()*12+new Date(state.gameTime).getMonth();state.deliveryContracts.offers=state.deliveryContracts.offers.filter(o=>o.availableUntil>state.gameTime);if(!force&&state.deliveryContracts.lastRefreshKey===key&&state.deliveryContracts.offers.length>=10)return;state.deliveryContracts.lastRefreshKey=key;let guard=0;while(state.deliveryContracts.offers.length<12&&guard++<40)state.deliveryContracts.offers.push(deliveryOfferGenerate(guard));}
function acceptDeliveryContract(id){refreshDeliveryContracts();const i=state.deliveryContracts.offers.findIndex(x=>x.id===id);if(i<0)return toast('Предложение уже недоступно');const c=state.deliveryContracts.offers.splice(i,1)[0];c.status='active';c.acceptedAt=state.gameTime;c.deadline=addMonthsTs(state.gameTime,Math.max(12,Number(c.contractMonths)||18));state.deliveryContracts.active.push(c);save();render();toast(`Контракт ${c.id} принят · срок ${Math.max(12,Number(c.contractMonths)||18)} мес.`);}
function qualifyingDeliveryLots(c){let reserved=reservedWarehouseTons(c.crop);const out=[];for(const l of (state.warehouse.lots||[]).filter(l=>l.crop===c.crop&&(Number(l.tons)||0)>.001)){const qty=Math.max(0,Number(l.tons)||0),blocked=Math.min(qty,reserved);reserved-=blocked;const free=qty-blocked;if(free>.001&&lotQuality(l).score+1e-6>=c.minQuality&&(c.maxMoisture==null||Number(l.moisture)<=c.maxMoisture+1e-6))out.push({...l,tons:free,_sourceLot:l});}return out;}
function deliveryQualifyingTons(c){return qualifyingDeliveryLots(c).reduce((a,l)=>a+(Number(l.tons)||0),0);}
function fulfillDeliveryContract(id){const c=state.deliveryContracts.active.find(x=>x.id===id);if(!c)return;if(state.gameTime>c.deadline)return toast('Срок контракта уже истёк');const lots=qualifyingDeliveryLots(c),available=lots.reduce((a,l)=>a+(Number(l.tons)||0),0);if(available+1e-6<c.tons)return toast(`Недостаточно подходящей продукции: ${num(available,1)} из ${num(c.tons,1)} т`);const distance=30,durationH=Math.max(4,c.tons/35+distance*2/55),readyAt=state.gameTime+durationH*3600000,transportCost=Math.round(c.tons*(240+distance*11));if(readyAt>c.deadline)return toast('Доставка уже не успеет прибыть до срока контракта');if(state.money<transportCost){toast(`Недостаточно средств на доставку: ${rub(transportCost)}`);return}let left=c.tons,selected=[],qualityMass=0;for(const l of lots){if(left<=.001)break;const take=Math.min(left,Number(l.tons)||0);selected.push({id:l.id,tons:take,fieldId:l.fieldId,quality:lotQuality(l).score,moisture:l.moisture});qualityMass+=take*lotQuality(l).score;const src=l._sourceLot||l;src.tons-=take;left-=take;state.warehouse.stocks[c.crop]=Math.max(0,(state.warehouse.stocks[c.crop]||0)-take);}state.warehouse.lots=state.warehouse.lots.filter(l=>(Number(l.tons)||0)>.001);state.money-=transportCost;finance('expense',transportCost,'operation',null,`Доставка по контракту ${c.id} · ${c.customer}`,c.crop);state.warehouse.salesTransit.push({id:uid(),crop:c.crop,tons:c.tons,price:c.unitPrice,revenue:c.gross,qualityScore:qualityMass/c.tons,pointId:'delivery_contract',pointName:c.customer,distanceKm:distance,startedAt:state.gameTime,readyAt,lots:selected,assetIds:[],label:'Контрактная логистика',fuelLiters:0,workerIds:[],cost:transportCost,deliveryContractId:c.id});c.status='shipping';c.shippingStartedAt=state.gameTime;c.shippingReadyAt=readyAt;log(`Контракт ${c.id}: ${num(c.tons,1)} т отправлено заказчику ${c.customer}.`);save();render();}
function failDeliveryContract(c,reason){if(!c||['completed','failed'].includes(c.status))return;c.status='failed';c.failedReason=reason;c.finishedAt=state.gameTime;const fine=Math.max(0,Number(c.penalty)||0);if(fine>0){state.money-=fine;finance('expense',fine,'contract_penalty',null,`Штраф по контракту поставки ${c.id}: ${reason}`,c.crop);processFinancialCrisis();}state.deliveryContracts.failed++;state.deliveryContracts.totalPenalties+=fine;state.deliveryContracts.history.unshift({...c,paidPenalty:fine});}
function processDeliveryContracts(){state.deliveryContracts=normalizeDeliveryContracts(state.deliveryContracts);refreshDeliveryContracts();for(const c of state.deliveryContracts.active){if(c.status==='active'&&state.gameTime>c.deadline)failDeliveryContract(c,'Истёк двухлетний срок поставки');}state.deliveryContracts.active=state.deliveryContracts.active.filter(c=>!['completed','failed'].includes(c.status));}
function renderDeliveryContracts(){refreshDeliveryContracts();const dc=state.deliveryContracts;return `${pageHead('Контракты на поставку','Долгосрочные обязательства по культуре, качеству и влажности с премией за дисциплину производства')}<div class="grid kpis"><div class="card kpi"><div class="label">ДОСТУПНО</div><div class="v">${dc.offers.length}</div></div><div class="card kpi"><div class="label">ПРИНЯТО</div><div class="v">${dc.active.length}</div></div><div class="card kpi"><div class="label">ВЫПОЛНЕНО</div><div class="v">${dc.completed}</div></div><div class="card kpi"><div class="label">ШТРАФЫ</div><div class="v negative">${rub(dc.totalPenalties)}</div></div></div><div class="note">Цена фиксируется при принятии: ориентир — ожидаемый рынок ближайшего года плюс премия примерно 3–11% за обязательство и качество. Срок исполнения предложения — 12–24 месяца. Требования генерируются только в достижимом диапазоне текущей модели качества и сушки. На доске регулярно есть 2–4 кормовых договора: качественное сено, луговое сено и солома.</div>${dc.active.length?`<div class="card section-card"><div class="section-title"><h2>Принятые поставки</h2><span class="pill">${dc.active.length}</span></div><div class="contract-grid">${dc.active.map(c=>{const have=deliveryQualifyingTons(c),ok=have+1e-6>=c.tons;return `<div class="card info-card contract-card active"><div class="section-title"><div><span class="status ${c.status==='shipping'?'warn':'info'}">${c.status==='shipping'?'В пути':'Принят'}</span><h3>${c.id} · ${CROPS[c.crop]?.label||c.crop}</h3></div><b>${rub(c.gross)}</b></div><div class="small">${c.customer} · ${num(c.tons,1)} т · качество ≥ <b>${c.minQuality}/100</b>${c.maxMoisture!=null?` · влажность ≤ <b>${num(c.maxMoisture,1)}%</b>`:''}</div><div class="muted small">Цена ${rub(c.unitPrice)}/т · выполнить до ${dateFmt(c.deadline)} · штраф ${rub(c.penalty)}</div>${c.status==='shipping'?`<div class="progress"><span style="width:${clamp((state.gameTime-c.shippingStartedAt)/Math.max(1,c.shippingReadyAt-c.shippingStartedAt)*100,0,100)}%"></span></div><div class="muted tiny">Доставка заказчику · прибытие ${dateFmt(c.shippingReadyAt)}</div>`:`<div class="row-actions"><span class="pill">подходит ${num(have,1)} т</span><button class="btn" data-delivery-fulfill="${c.id}" ${ok?'':'disabled'}>Отгрузить по контракту</button></div>${!ok?`<div class="block-reason">Нужно накопить ещё ${num(Math.max(0,c.tons-have),1)} т продукции, соответствующей качеству и влажности.</div>`:''}`}</div>`}).join('')}</div></div>`:''}<div class="card section-card"><div class="section-title"><h2>Предложения</h2><button class="btn secondary compact" data-delivery-refresh>Обновить</button></div><div class="contract-grid">${dc.offers.map(c=>`<div class="card info-card contract-card"><div class="section-title"><div><span class="status info">Поставка</span><h3>${CROPS[c.crop]?.label||c.crop}</h3></div><b>${rub(c.unitPrice)}/т</b></div><div class="small">${c.customer} · ${num(c.tons,1)} т</div><div class="small">Качество ≥ <b>${c.minQuality}/100</b>${c.maxMoisture!=null?` · влажность ≤ <b>${num(c.maxMoisture,1)}%</b>`:''}</div><div class="muted tiny">Гарантированная сумма ${rub(c.gross)} · штраф при неисполнении ${rub(c.penalty)} · объявление до ${shortDate(c.availableUntil)}</div><button class="btn" style="margin-top:10px" data-delivery-accept="${c.id}">Принять контракт</button></div>`).join('')}</div></div>${dc.history.length?`<div class="card section-card"><div class="section-title"><h2>История</h2></div><div class="table-wrap"><table><thead><tr><th>КОНТРАКТ</th><th>КУЛЬТУРА</th><th>РЕЗУЛЬТАТ</th><th>СУММА / ШТРАФ</th></tr></thead><tbody>${dc.history.slice(0,30).map(c=>`<tr><td>${c.id}</td><td>${CROPS[c.crop]?.label||c.crop}</td><td><span class="status ${c.status==='completed'?'good':'bad'}">${c.status==='completed'?'Выполнен':'Не выполнен'}</span>${c.failedReason?`<div class="muted tiny">${c.failedReason}</div>`:''}</td><td>${c.status==='completed'?rub(c.gross):`−${rub(c.paidPenalty||0)}`}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;}

const CONTRACT_AREA_BANDS={small:{label:'Малые',min:5,max:25,target:4},medium:{label:'Средние',min:30,max:100,target:3},large:{label:'Большие',min:120,max:300,target:3}};
function contractsDefault(){return{offers:[],active:[],history:[],lastRefreshDay:0,nextSerial:1,totalIncome:0,totalPenalties:0,completed:0,failed:0};}
function normalizeContracts(x){x=x&&typeof x==='object'?x:{};return{offers:Array.isArray(x.offers)?x.offers.filter(c=>c&&c.id&&OPS[c.op]):[],active:Array.isArray(x.active)?x.active.filter(c=>c&&c.id&&OPS[c.op]):[],history:Array.isArray(x.history)?x.history.slice(-200):[],lastRefreshDay:Number(x.lastRefreshDay)||0,nextSerial:Math.max(1,Number(x.nextSerial)||1),totalIncome:Math.max(0,Number(x.totalIncome)||0),totalPenalties:Math.max(0,Number(x.totalPenalties)||0),completed:Math.max(0,Number(x.completed)||0),failed:Math.max(0,Number(x.failed)||0)};}
function fieldContractPenalty(c,kind='missed'){const reward=Math.max(0,Number(c?.reward)||0),rate=kind==='abandon'?.06:kind==='late'?(Number(c?.weatherPauseDays)>0?.03:.08):.10;return Math.min(250000,Math.round(reward*rate));}
function chargeFieldContractPenalty(c,kind,reason){const fine=fieldContractPenalty(c,kind);if(fine<=0)return 0;state.money-=fine;finance('expense',fine,'contract_penalty',null,`Штраф по агроконтракту ${c.id}: ${reason}`,c.cropKey);state.contracts.totalPenalties=(Number(state.contracts.totalPenalties)||0)+fine;c.paidPenalty=fine;processFinancialCrisis();return fine;}
function contractPseudoField(c){return{id:-1,ha:Number(c.ha)||10,crop:c.cropKey||null,distanceKm:Number(c.distanceKm)||8,moisture:55,soil:{}};}
function contractSeasonCandidates(at=state.gameTime){const d=new Date(at),m=d.getMonth()+1,t=dayStart(at),y=d.getFullYear(),out=[];
 const add=(op,cropKey=null)=>out.push({op,cropKey});
 if(m>=3&&m<=6&&snowCoverCm(at)<3)['disk','plow','deepRip','cultivate','harrow'].forEach(op=>add(op));
 if(m>=7&&m<=11)['stubble','disk','plow','deepRip','cultivate','harrow'].forEach(op=>add(op));
 if(m>=4&&m<=5)add('ridge','potato');
 for(const [k,c] of Object.entries(CROPS)){if(c.fieldCrop===false)continue;const sw=seasonalWindow(c.sow,y);if(t>=sw.start&&t<=sw.end)add('sow',k);const hw=seasonalWindow(c.harvest,y);if(t>=hw.start&&t<=hw.end)add('harvest',k);const vegStart=sw.start+Math.max(15,Math.round(c.maturityDays*.12))*DAY,vegEnd=hw.start;if(t>=vegStart&&t<=vegEnd){add('herbicide',k);add('fungicide',k);add('insecticide',k);}}
 if(m>=4&&m<=10){['nitrate','urea','ammophos','npk','potash','lime'].forEach(op=>add(op));}
 if(m>=6&&m<=9){['mow','ted','rake','bale','baleHaul'].forEach(op=>add(op,'perennial_grass'));}
 return out.filter(x=>contractorCatalogUnits(x.op,x.cropKey).length>0);
}
function contractTierForBand(band,r){if(band==='small')return r<.65?'economy':'standard';if(band==='medium')return r<.72?'standard':'premium';return r<.35?'standard':'premium';}
function contractTierAvailableForCatalog(op,cropKey,tierId){const c={op,cropKey,tierId};return contractorCatalogUnits(op,cropKey).some(u=>contractUnitTierInfo(c,u).ok);}
function contractAttainableTier(op,cropKey,desired='premium'){const order=['economy','standard','premium'],want=contractTierRank(desired);for(let i=want;i>=0;i--)if(contractTierAvailableForCatalog(op,cropKey,order[i]))return order[i];return'economy';}
function contractReward(ha,op,cropKey,tierId){const f={ha,crop:cropKey,distanceKm:8},q=contractorTierQuote(f,op,tierId,cropKey);return q?.fullFieldCost||Math.round((OPS[op]?.cost||1500)*ha*contractorScaleFactor(ha)*(CONTRACTOR_TIERS[tierId]?.priceFactor||1));}
function contractReferenceWorkHours(c){const pkg=contractorTierPackage(c.op,c.cropKey,c.tierId),rate=Math.max(.1,Number(pkg?.rate)||0);return Math.max(.25,(Number(c.ha)||0)/rate);}
function contractDeadlineHours(c){return contractReferenceWorkHours(c)+12;}
function generateContractOffer(bandKey,idx,now=state.gameTime){const band=CONTRACT_AREA_BANDS[bandKey],cands=contractSeasonCandidates(now);if(!band||!cands.length)return null;const seed=(state.landSeed^hashString(`contract:${bandKey}:${Math.floor(now/DAY)}:${idx}:${state.contracts.nextSerial}`))>>>0,r=rngFactory(seed),cand=cands[Math.floor(r()*cands.length)%cands.length],ha=Math.round((band.min+r()*(band.max-band.min))*10)/10,desiredTierId=contractTierForBand(bandKey,r()),tierId=contractAttainableTier(cand.op,cand.cropKey,desiredTierId),distanceKm=Math.round((2+r()*33)*10)/10,id='C-'+String(state.contracts.nextSerial++).padStart(6,'0'),reward=contractReward(ha,cand.op,cand.cropKey,tierId),acceptDays=2+Math.floor(r()*3);return{id,band:bandKey,op:cand.op,cropKey:cand.cropKey,ha,distanceKm,tierId,reward,createdAt:now,availableUntil:now+acceptDays*DAY,status:'offer'};}
function refreshContracts(force=false){state.contracts=normalizeContracts(state.contracts);const c=state.contracts,day=dayStart(state.gameTime),refreshKey=Math.floor(day/(3*DAY));c.offers=c.offers.filter(x=>x.availableUntil>state.gameTime);if(!force&&c.lastRefreshDay===refreshKey)return;c.lastRefreshDay=refreshKey;const cands=contractSeasonCandidates(state.gameTime);if(!cands.length)return;for(const [bandKey,band] of Object.entries(CONTRACT_AREA_BANDS)){let n=c.offers.filter(x=>x.band===bandKey).length,guard=0;while(n<band.target&&guard++<20){const o=generateContractOffer(bandKey,guard,state.gameTime);if(!o)break;c.offers.push(o);n++;}}}
function contractTierRank(id){return id==='premium'?2:id==='standard'?1:0;}
function contractUnitTierInfo(c,u){
 const rank=contractTierRank(c?.tierId),models=(u?.models?.length?u.models:(u?.assets||[]).map(a=>equipmentModel(a.modelId))).filter(Boolean),segCap=models.some(m=>m.segment==='domestic_used')?1:2;
 const std=contractorTierPackage(c.op,c.cropKey,'standard'),prem=contractorTierPackage(c.op,c.cropKey,'premium'),rate=Math.max(0,Number(u?.rate)||0),stdRate=Math.max(.01,Number(std?.rate)||rate),premRate=Math.max(.01,Number(prem?.rate)||stdRate);
 let perf=0;if(rate>=stdRate*.65)perf=1;if(rate>=premRate*.75)perf=2;const maxRank=Math.min(segCap,perf),labels=['Эконом','Стандарт','Премиум'];
 return{ok:maxRank>=rank,maxRank,label:labels[maxRank],required:labels[rank],rate,stdRate,premRate,legacyCap:segCap<2};
}
function contractFreeUnits(c){return ownedUnitOptions(contractPseudoField(c),c.op,c.cropKey).filter(u=>contractUnitTierInfo(c,u).ok);}
function acceptContract(id){refreshContracts();const i=state.contracts.offers.findIndex(x=>x.id===id);if(i<0){toast('Объявление уже недоступно');return}const c=state.contracts.offers[i];if(c.availableUntil<=state.gameTime){state.contracts.offers.splice(i,1);toast('Срок объявления истёк');return}const workH=contractReferenceWorkHours(c),deadlineH=contractDeadlineHours(c);c.status='accepted';c.acceptedAt=state.gameTime;c.deadlineWorkHours=workH;c.deadlineReserveHours=12;c.deadline=state.gameTime+deadlineH*3600000;c.startedAt=null;c.end=null;c.failedReason=null;state.contracts.offers.splice(i,1);state.contracts.active.push(c);save();render();toast(`Контракт ${c.id} принят · расчёт ${durationText(workH)} + резерв 12 ч`);}
function abandonContract(id){const i=state.contracts.active.findIndex(x=>x.id===id);if(i<0)return;const c=state.contracts.active[i];if(c.startedAt){toast('Уже начатую работу нельзя отменить');return}const fine=chargeFieldContractPenalty(c,'abandon','Отказ исполнителя');c.status='failed';c.failedReason=`Отказ исполнителя · штраф ${rub(fine)}`;c.finishedAt=state.gameTime;state.contracts.active.splice(i,1);state.contracts.history.unshift(c);state.contracts.failed++;save();render();}
let contractPicker=null;
function openContractPicker(id){const c=state.contracts.active.find(x=>x.id===id);if(!c||c.startedAt)return;contractPicker={contractId:id,ownTeams:[],workerMap:{},shiftWorkerMap:{},shiftHours:8,shiftCount:1,supplyMode:'base_return'};page='contracts';renderPreservingViewport();}
function resolveContractUnits(c){const all=contractFreeUnits(c),out=[];for(const t of contractPicker?.ownTeams||[]){const u=all.find(x=>x.assets[0]?.id===t.primaryId&&((x.assets[1]?.id||'')===(t.secondaryId||'')));if(u)out.push(u);}return selectedUnitsValid(out)?out:[];}
function nextContractTeamConfig(c,ignore=-1){const all=contractFreeUnits(c),used=new Set();for(const [i,t] of (contractPicker?.ownTeams||[]).entries()){if(i===ignore)continue;if(t.primaryId)used.add(t.primaryId);if(t.secondaryId)used.add(t.secondaryId);}for(const u of all){if(u.assets.some(a=>used.has(a.id)))continue;return{primaryId:u.assets[0]?.id||'',secondaryId:u.assets[1]?.id||''};}return null;}
function contractAssetEconomicRate(a){const m=equipmentModel(a?.modelId);if(!m)return 0;const current=Math.max(50000,Number(assetSaleValue(a))||Number(m.price)||0),sp=serviceProfile(m),wear=equipmentWearFactor(m)*(simplePassiveLoaderTool(m)?.30:1),powered=m.type==='tractor'||m.type==='combine'||m.type==='truck'||m.selfPropelled,lifeH=simplePassiveLoaderTool(m)?22000:powered?7000:m.type==='header'?10000:14000,serviceH=powered?14000:22000,riskMult=Math.max(.85,1/Math.max(.55,Number(sp.reliability)||1))*(1+Math.max(0,(Number(sp.partsDays)||2)-2)*.04);return current/lifeH*wear+(Number(m.price)||current)/serviceH*Math.max(.55,Number(sp.repairMult)||1)*riskMult;}
