function processContractWeatherEvents(at){let stop=false;for(const c of state.contracts?.active||[]){if(c.status!=='working'||c.end<=at||c.startedAt>=at)continue;const x=contractWeatherStateAt(c,at+1000);if(x&&!c.weatherPausedAt){updateContractWorkProgress(c,at);c.weatherPausedAt=at;c.weatherPauseReason=x.reason;c.weatherResumeAt=x.resume;c.weatherPauseDays=(Number(c.weatherPauseDays)||0)+1;if(!c.shiftPausedAt&&!c.breakdownPausedAt){state.criticalAlert={type:'weather_stop',time:at,contractId:c.id,fieldId:null,title:'Погодная остановка контракта',message:`Контракт ${c.id} · ${OPS[c.op]?.label||c.op}: ${x.reason}. Ожидаемое возобновление: ${dateFmt(x.resume)}.`};setGameSpeed(0);stop=true;}}else if(!x&&c.weatherPausedAt&&at+1000>=Number(c.weatherResumeAt||0)){const pauseStart=Number(c.weatherPausedAt)||at;creditContractOperationalRest(c,pauseStart,at);c.weatherPausedAt=null;c.weatherPauseReason=null;c.weatherResumeAt=null;c.workProgressAt=at;}}return stop;}
