function fieldSupplyPlanMeta(plan){if(!plan?.ok)return plan?.reason||'Недоступно';const names=(plan.assets||[]).map(a=>`${a.farmId} ${equipmentModel(a.modelId)?.name||''}`).join(' + ');if(plan.mode==='bigbag_loader')return `${names}<div class="muted tiny">Транспорт: ${plan.transport?.label||'—'} · партия ${num((plan.capacity||0)/1000,1)} т (${Math.floor((plan.capacity||0)/1000)} биг-бэг.) · ковшовая фасовка ≈ ${num(plan.packMinPerBag||0,1)} мин/биг-бэг</div>`;if(plan.mode==='seed_loader'||plan.mode==='fert_tender')return `${names}<div class="muted tiny">Мобильная партия ${num((plan.capacity||0)/1000,1)} т · перегрузка ≈ ${num(plan.transferPerMin||0,0)} кг/мин</div>`;if(plan.mode==='solution_tanker')return `${names}<div class="muted tiny">Мобильный объём ${num((plan.capacity||0)/1000,1)} м³ · заправка ≈ ${num(plan.transferPerMin||0,0)} л/мин</div>`;return names}
