function selfPropelledLoaderSetup(a){const m=a&&equipmentModel(a.modelId);if(!a||m?.category!=='loader_selfpropelled')return null;const fleet=state.equipment?.fleet||[],tool=a.loaderToolId?fleet.find(x=>x.id===a.loaderToolId):null,tm=tool&&equipmentModel(tool.modelId);return{machine:a,tractor:a,loader:a,loaderModel:m,tool,toolModel:tm&&loaderToolCompatible(m,tm)?tm:null,selfPropelled:true};}
