function processSilageDeliveries(){const tr=state.warehouse?.silageTransit||[],keep=[];let blocked=false;for(const l of tr){if(l.readyAt>state.gameTime){keep.push(l);continue}const b=silageBunkerById(l.bunkerId);if(!b){l.readyAt=state.gameTime+3600000;keep.push(l);continue}if(!l.unloadQueued){if(silageBunkerFreeLooseT(b)+1e-6<l.tons){l.storageWaiting=true;l.readyAt=state.gameTime;keep.push(l);state.criticalAlert={type:'silage_bunker_full',time:state.gameTime,taskId:l.taskId,fieldId:l.fieldId,title:'Силосная траншея заполнена рыхлой массой',message:`${b.id}: свободного объёма недостаточно для ${num(l.tons,1)} т. Уплотните массу или выберите другую траншею.`};setGameSpeed(0);blocked=true;continue}const sp=infraSpec('silage'),startAt=Math.max(state.gameTime,Number(b.unloadAvailableAt)||state.gameTime),hours=Math.max(.02,l.tons/Math.max(10,Number(sp.unloadTph)||80));l.unloadQueued=true;l.unloadStartedAt=startAt;l.readyAt=startAt+hours*3600000;l.unloadWaitH=Math.max(0,(startAt-state.gameTime)/3600000);b.unloadAvailableAt=l.readyAt;l.storageWaiting=false;if(l.readyAt>state.gameTime){keep.push(l);continue}}if(l.readyAt>state.gameTime){keep.push(l);continue}if(!addSilageLoad(b,l.tons)){l.storageWaiting=true;l.unloadQueued=false;l.readyAt=state.gameTime;keep.push(l);blocked=true;setGameSpeed(0);continue}const ht=(state.tasks||[]).find(x=>x.id===l.taskId);if(ht?.silageSnapshot){ht.silageSnapshot.deliveredTons=(Number(ht.silageSnapshot.deliveredTons)||0)+l.tons;b.pnl=b.pnl||{field:0,harvest:0,compaction:0,film:0,infrastructure:0,loading:0,delivery:0,revenue:0,spoilageT:0};const den=Math.max(.001,Number(ht.silageSnapshot.tons)||l.tons),share=l.tons/den;b.pnl.field+=(Number(ht.silageSnapshot.fieldCashCost)||0)*share;b.pnl.harvest+=(Number(ht.silageSnapshot.harvestCashCost)||0)*share;}log(`${num(l.tons,1)} т зелёной массы принято в ${b.id}. Плотность ${num(b.density,2)} т/м³.`);}state.warehouse.silageTransit=keep;return blocked;}
