function infrastructureBuildDays(kind,nextLevel){const heavy=['grain','vegetable','hay','silage'],industrial=['dryer','seedTreater'],base=heavy?[0]:null;const a=heavy.includes(kind)?[0,14,30,60,120,210,360]:industrial.includes(kind)?[0,14,30,60,120,180,300]:[0,7,14,30,60,120,240];return a[Math.min(nextLevel,a.length-1)]||30;}
function infrastructureProject(kind){return (state.infrastructure?.projects||[]).find(x=>x.kind===kind&&x.status==='building')||null;}
function processInfrastructureProjects(){state.infrastructure.projects=Array.isArray(state.infrastructure.projects)?state.infrastructure.projects:[];for(const j of state.infrastructure.projects){if(j.status!=='building'||j.readyAt>state.gameTime)continue;state.infrastructure[j.kind+'Level']=Math.max(infraLevel(j.kind),j.toLevel);j.status='completed';j.completedAt=j.readyAt;if(j.kind==='silage')ensureSilageBunkers();log(`Строительство завершено: ${j.label}.`);}state.infrastructure.projects=state.infrastructure.projects.filter(j=>j.status==='building'||(state.gameTime-(j.completedAt||0)<30*DAY));}
function upgradeInfrastructure(kind){const levels=INFRA_LEVELS[kind];if(!levels)return;const cur=infraLevel(kind),next=levels[cur+1];if(!next){toast('Объект уже максимального уровня');return}if(infrastructureProject(kind)){toast('Этот объект уже строится или улучшается');return}if(state.money<next.cost){toast('Недостаточно средств на строительство');return}const days=infrastructureBuildDays(kind,cur+1),readyAt=state.gameTime+days*DAY;if(!confirm(`Начать строительство «${next.label}» за ${rub(next.cost)}? Срок: ${days} дн.`))return;state.money-=next.cost;state.infrastructure.projects=Array.isArray(state.infrastructure.projects)?state.infrastructure.projects:[];state.infrastructure.projects.push({id:uid(),kind,fromLevel:cur,toLevel:cur+1,label:next.label,cost:next.cost,startedAt:state.gameTime,readyAt,status:'building'});finance('expense',next.cost,'infrastructure',null,`Строительство / улучшение: ${next.label} · срок ${days} дн.`);log(`Начато строительство: ${next.label}. Срок ${days} дн., завершение ${shortDate(readyAt)}.`);save();render();toast(`Строительство начато · ${days} дн.`)}
