function processTaskWeatherEvents(at){let stop=false;for(const t of state.tasks||[]){if(t.end<=at||t.start>=at)continue;const x=taskWeatherStateAt(t,at+1000);if(x&&!t.weatherPausedAt){if(taskUsesWorkGroups(t))updateTaskWorkProgress(t,at);t.weatherPausedAt=at;t.weatherPauseReason=x.reason;t.weatherResumeAt=x.resume;recordField(landById(t.fieldId),`Операция «${OPS[t.op]?.label||t.op}» остановлена погодой: ${x.reason}.`,at);if(!t.shiftPausedAt&&!t.breakdownPausedAt){state.criticalAlert={type:'weather_stop',time:at,taskId:t.id,fieldId:t.fieldId,title:'Погодная остановка работ',message:`${OPS[t.op]?.label||t.op} · ${fieldCode(landById(t.fieldId)||{id:t.fieldId})}: ${x.reason}. Ожидаемое возобновление после просыхания: ${dateFmt(x.resume)}.`};setGameSpeed(0);stop=true;}}else if(!x&&t.weatherPausedAt&&at+1000>=Number(t.weatherResumeAt||0)){t.weatherPausedAt=null;t.weatherPauseReason=null;t.weatherResumeAt=null;if(taskUsesWorkGroups(t))t.workProgressAt=at;recordField(landById(t.fieldId),`Погодная пауза завершена. Операция «${OPS[t.op]?.label||t.op}» может продолжаться.`,at);}}return stop;}

function weatherFor(ms){return weatherForRaw(ms);}
function cropAge(f,at=state.gameTime){return f.crop&&f.plantedAt?Math.max(0,daysBetween(f.plantedAt,at)):null;}
function maturityAt(f){const c=cropDef(f);if(!c||!f.plantedAt)return null;const delay=['cereal','oilseed','corn'].includes(c.group)?Math.round(nitrogenExcessRisk(f,f.crop)*5):0;return f.plantedAt+(c.maturityDays+delay)*DAY;}
function cropStage(f,at=state.gameTime){const c=cropDef(f);if(!c||!f.plantedAt)return null;const a=cropAge(f,at),m=c.maturityDays,p=clamp(a/m,0,1);if(p<.08)return{label:'Прорастание',progress:p};if(p<.28)return{label:'Всходы',progress:p};if(p<.68)return{label:'Вегетация',progress:p};if(p<.88)return{label:'Формирование урожая',progress:p};if(p<1)return{label:'Созревание',progress:p};return{label:'Готово к уборке',progress:1};}
function seasonalWindow(spec,year){return{start:dateFor(year,...spec.start),optimalStart:spec.optimalStart?dateFor(year,...spec.optimalStart):null,optimalEnd:spec.optimalEnd?dateFor(year,...spec.optimalEnd):null,end:dateFor(year,...spec.end)};}
function findSowWindow(c,at=state.gameTime){const y=new Date(at).getFullYear(),t=dayStart(at);for(const yy of [y-1,y,y+1]){const w=seasonalWindow(c.sow,yy);if(t>=w.start&&t<=w.end)return{...w,year:yy,open:true};}let candidates=[seasonalWindow(c.sow,y),seasonalWindow(c.sow,y+1)].filter(w=>w.start>t).sort((a,b)=>a.start-b.start);return{...(candidates[0]||seasonalWindow(c.sow,y+1)),year:candidates[0]?new Date(candidates[0].start).getFullYear():y+1,open:false};}
function sowTimingFactor(c,ms){const y=new Date(ms).getFullYear(),w=seasonalWindow(c.sow,y),t=dayStart(ms);if(t<w.start||t>w.end)return 0;if(t>=w.optimalStart&&t<=w.optimalEnd)return 1;if(t<w.optimalStart)return .9+.1*(daysBetween(w.start,t)/Math.max(1,daysBetween(w.start,w.optimalStart)));return Math.max(.78,1-.22*(daysBetween(w.optimalEnd,t)/Math.max(1,daysBetween(w.optimalEnd,w.end))));}
function sowSegmentTimingFactor(c,ms){const y=new Date(ms).getFullYear(),w=seasonalWindow(c.sow,y),t=Number(ms)||0;if(t<w.start)return clamp(.82+.08*(t-w.start)/(Math.max(DAY,w.optimalStart-w.start)),.72,.90);if(t<=w.end)return sowTimingFactor(c,t);const lateDays=(t-w.end)/DAY;return clamp(.78-lateDays*.018,.55,.78);}
function fieldSpatialZones(f){if(Array.isArray(f?.spatialZones)&&f.spatialZones.length===3)return f.spatialZones;const id=Math.max(1,Number(f?.id)||1),r=rngFactory((Math.imul(id,2654435761)^0x79A61F3D)>>>0),raw=[.31+r()*.05,.33+r()*.05,.31+r()*.05],sum=raw.reduce((a,b)=>a+b,0),amp=.055+r()*.035,vals=[1-amp,1,1+amp],rot=id%3,z=[];for(let i=0;i<3;i++)z.push({id:['A','B','C'][i],label:`Зона ${['A','B','C'][i]}`,share:raw[i]/sum,fertility:vals[(i+rot)%3]});const mean=z.reduce((a,x)=>a+x.share*x.fertility,0);for(const x of z)x.fertility=+(x.fertility/mean).toFixed(4);if(f)f.spatialZones=z;return z;}
function recordTaskSpatialProgress(t,from,to,workedHa){if(!t||workedHa<=.00001||to<=from)return;const tracked=t.op==='sow'||t.op==='harvest'||['nitrate','urea','ammophos','npk','potash','lime'].includes(t.op);if(!tracked)return;t.spatialProgress=Array.isArray(t.spatialProgress)?t.spatialProgress:[];t.spatialProgress.push({from:Number(from),to:Number(to),ha:Number(workedHa)});if(t.spatialProgress.length>240)t.spatialProgress=t.spatialProgress.slice(-240);}
function taskSpatialSlices(t,maxStepH=1){const rows=Array.isArray(t?.spatialProgress)&&t.spatialProgress.length?t.spatialProgress:[{from:taskBreakdownStartAt(t),to:Number(t?.end)||taskBreakdownStartAt(t),ha:Number(t?.fieldHa)||0}],out=[];for(const row of rows){const a=Number(row.from)||0,b=Math.max(a,Number(row.to)||a),ha=Math.max(0,Number(row.ha)||0),dur=Math.max(1,b-a),n=Math.max(1,Math.ceil(dur/(Math.max(.25,maxStepH)*3600000)));for(let i=0;i<n;i++){const x0=a+(b-a)*i/n,x1=a+(b-a)*(i+1)/n;out.push({from:x0,to:x1,at:(x0+x1)/2,ha:ha/n});}}return out;}
function summarizeSowingProgress(t,c){const slices=taskSpatialSlices(t,1),total=Math.max(.001,slices.reduce((a,x)=>a+x.ha,0)),bands={optimal:{label:'В оптимальном окне',ha:0,sum:0,min:Infinity,max:-Infinity},window:{label:'В допустимом окне',ha:0,sum:0,min:Infinity,max:-Infinity},late:{label:'После окна',ha:0,sum:0,min:Infinity,max:-Infinity}};let sumF=0,sumAt=0;for(const x of slices){const f=sowSegmentTimingFactor(c,x.at),y=new Date(x.at).getFullYear(),w=seasonalWindow(c.sow,y),b=x.at>=w.optimalStart&&x.at<=w.optimalEnd?bands.optimal:x.at<=w.end?bands.window:bands.late;b.ha+=x.ha;b.sum+=x.ha*f;b.min=Math.min(b.min,x.from);b.max=Math.max(b.max,x.to);sumF+=x.ha*f;sumAt+=x.ha*x.at;}const zones=Object.values(bands).filter(x=>x.ha>.001).map(x=>({label:x.label,ha:x.ha,share:x.ha/total,factor:x.sum/x.ha,from:x.min,to:x.max}));return{factor:clamp(sumF/total,.55,1),meanAt:sumAt/total,startedAt:Math.min(...slices.map(x=>x.from)),completedAt:Math.max(...slices.map(x=>x.to)),zones};}
