function setYieldTarget(fieldId,cropKey,value){const f=landById(fieldId),c=CROPS[cropKey];if(!f||!c||f.crop){toast(f?.crop?'Целевая урожайность фиксируется при посеве и не меняется в текущем сезоне':'Поле не найдено');return}const r=targetYieldRange(cropKey),v=clamp(Number(value)||c.baseYield,r.min,r.max);f.yieldTargets=f.yieldTargets||{};f.yieldTargets[cropKey]=v;save();render();toast(`${fieldCode(f)}: цель ${num(v,2)} т/га · ${c.label}`);}
