function startForageContractPackage(fieldId){const f=landById(fieldId),chk=forageOpAllowed(f,'mow');if(!chk.ok){toast(chk.label);return;}const cut=forageCutsThisYear(f)+1,growth=isMeadow(f)?meadowGrowthPct(f):100,base=forageCutYield(f.crop,cut,f,growth),nutrition=forageNutrientFactor(f),weather=clamp(f.weatherFactor||1,.75,1.05),gross=f.ha*base*nutrition*weather,tons=gross*.91,cost=Math.round(f.ha*6200+tons*520);const outCrop=isMeadow(f)?'meadow_hay':'hay';if(!canStoreCropTons(outCrop,tons)){toast(`Недостаточно места в сенохранилище: нужно ${num(tons,1)} т`);return;}if(state.money<cost){toast(`Недостаточно средств: ${rub(cost)}`);return;}if(!confirm(`Заготовить сено под ключ подрядчиком?\n${fieldCode(f)} · ${f.ha} га\nОриентир: ${num(tons,1)} т товарного сена\nСтоимость: ${rub(cost)}\n\nПодрядчик выполняет кошение, ворошение, валкование, прессование и вывоз.`))return;const rem=isMeadow(f)?{N:0,P:0,K:0}:forageApplyRemoval(f,cut);state.money-=cost;finance('expense',cost,'operation',f.id,'Сенозаготовка под ключ',f.crop);f.lastGrassCut=state.gameTime;f.grassCuts=Array.isArray(f.grassCuts)?f.grassCuts:[];f.grassCuts.push(state.gameTime);if(isMeadow(f)){f.meadowGrowth=0;f.meadowGrowthYear=new Date(state.gameTime).getFullYear();}state.tasks.push({id:uid(),fieldId:f.id,op:'hayPackage',cropKey:f.crop,start:state.gameTime,end:state.gameTime+72*3600000,cost,packageTons:tons,packageGross:gross,packageQuality:clamp((isMeadow(f)?72:84)+forageQualityBonus(f.crop),45,96),packageMoisture:16.5,packageRemoval:rem,machineKind:'contractor',machineAssetIds:[],machineModelIds:[],machineHours:0,machineLabel:'Подрядчик · сенозаготовка под ключ'});recordField(f,`Подрядчик начал сенозаготовку под ключ. Вынос N/P/K ${rem.N}/${rem.P}/${rem.K}.`);save();render();}

function fertilizerTimingAllowed(f,op){if(!f?.crop)return{ok:true,label:'Внесение до посева / после уборки'};if(op==='lime')return{ok:false,label:'Известкование выполняется без культуры'};const p=cropStage(f)?.progress||0;if(op==='nitrate'||op==='urea'){if(p>.62)return{ok:false,label:'Азотная подкормка уже слишком поздняя для текущей культуры'};return{ok:true,label:'Азотная подкормка доступна'};}return{ok:false,label:'Фосфорные, калийные и комплексные удобрения вносите до посева или после уборки'};}
function opAllowed(f,op,cropKey=null){if(!f||!f.owned)return{ok:false,label:isMeadow(f)?'Сенокос не куплен или не арендован':'Поле не куплено или не арендовано'};const fw=fieldWorkability(f,op==='sow'?'sow':['harvest','silageHarvest'].includes(op)?'harvest':OPS[op]?.type==='spray'?'spray':'field');if(op!=='baleHaul'&&!fw.ok)return fw;if(f.tenure==='leased'&&f.lease?.expired&&!['harvest','silageHarvest'].includes(op))return{ok:false,label:'Срок аренды истёк: разрешено только завершить уборку'};if(taskFor(f.id))return{ok:false,label:'На поле уже идёт работа'};const def=OPS[op];if(!def)return{ok:false,label:'Неизвестная операция'};if(def.type==='tillage'){if(f.crop)return{ok:false,label:'На поле растёт культура'};return fieldConditions(f,op);}if(def.type==='fert'){if(!soilKnown(f))return{ok:false,label:'Сначала нужен анализ почвы'};const ft=fertilizerTimingAllowed(f,op);if(!ft.ok)return ft;return fieldConditions(f,'fert');}if(def.type==='spray'){const presowBurndown=op==='herbicide'&&!f.crop&&f.technology==='noTill'&&(Number(f.soil?.weeds)||0)>12;if(!f.crop&&!presowBurndown)return{ok:false,label:'Нет культуры для обработки'};if(op==='herbicide'&&f.cropProtection?.herbicide&&!presowBurndown&&Number(f.cropWeedPressure||0)<=12)return{ok:false,label:'Гербицид уже сработал, засорённость ниже порога'};if(!presowBurndown&&!protectionApplicable(f,op))return{ok:false,label:'По текущей культуре эта обработка не требуется'};if(!presowBurndown){const w=protectionWindowInfo(f,op),now=state.gameTime;if(w&&now<w.start)return{ok:false,label:`Окно обработки откроется ${shortDate(w.start)}`};if(w&&now>w.end)return{ok:false,label:`Окно обработки закрыто ${shortDate(w.end)}`};}return fieldConditions(f,'spray');}if(op==='sow'){if(f.crop)return{ok:false,label:'Поле уже занято'};return sowReadiness(f,cropKey);}if(['mow','ted','rake','bale','baleHaul'].includes(op))return forageOpAllowed(f,op);if(op==='grainWindrow')return grainWindrowReadiness(f);if(op==='silageHarvest')return silageHarvestReadiness(f);if(op==='harvest'){if(forageCrops.has(f.crop))return{ok:false,label:'Многолетние травы убираются через сенокос'};return canHarvest(f);}return{ok:false,label:'Недоступно'};}
