function agroPlanRoutes(){state.agroPlan=state.agroPlan&&typeof state.agroPlan==='object'?state.agroPlan:{routes:[]};state.agroPlan.routes=Array.isArray(state.agroPlan.routes)?state.agroPlan.routes:[];return state.agroPlan.routes}
function routeForCompletedTask(t){return agroPlanRoutes().find(r=>r.enabled!==false&&r.op===t.op&&r.fieldIds?.[r.cursor]===t.fieldId)||null}
function taskRemainingShiftHours(t){const shift=Math.max(1,Number(t.shiftHours)||8),worked=Math.max(0,Number(t.machineHours)||0),rem=shift-(worked%shift);return rem<.05?shift:rem}
function planCanAutoAdvance(t,nextField){if(!t||!nextField||!t.planTemplate)return false;const src=landById(t.fieldId);if(!src||!clustersAdjacent(src.clusterId,nextField.clusterId))return false;const chk=opAllowed(nextField,t.op,nextField.crop||t.cropKey);if(!chk.ok)return false;const assets=(t.machineAssetIds||[]).map(id=>state.equipment?.fleet?.find(a=>a.id===id)).filter(Boolean);if(!assets.length)return false;const travel=travelPlan(nextField,assets);return taskRemainingShiftHours(t)>(Number(travel.outboundH)||0)+.2}
function autoAdvancePlannedTask(t,route){const nextId=route?.fieldIds?.[route.cursor+1],f=landById(nextId);if(!f||!planCanAutoAdvance(t,f))return false;const p=JSON.parse(JSON.stringify(t.planTemplate||{}));p.fieldId=f.id;p.op=t.op;p.cropKey=f.crop||t.cropKey;p.openedAt=state.gameTime;operationPicker=p;route.cursor++;try{startSelectedOperation();}catch(e){operationPicker=null;route.cursor--;return false}if(operationPicker){route.cursor--;return false}log(`План агронома: техника автоматически перешла на ${fieldCode(f)} (${landClusterLabel(f)}).`);return true}
function completionPromptForTask(t){const route=routeForCompletedTask(t),nextId=route?.fieldIds?.[route.cursor+1]||null;state.operationCompletion={taskId:t.id,fieldId:t.fieldId,op:t.op,cropKey:t.cropKey||null,assetIds:[...(t.machineAssetIds||[])],nextFieldId:nextId,routeId:route?.id||null,finishedAt:t.end||state.gameTime};setGameSpeed(0)}
function handleCompletedTaskFlow(t){const route=routeForCompletedTask(t);if(route&&autoAdvancePlannedTask(t,route))return;completionPromptForTask(t)}
function processTasks(){const done=state.tasks.filter(t=>t.end<=state.gameTime).sort((a,b)=>a.end-b.end);if(done.length){done.forEach(t=>{finishTask(t);handleCompletedTaskFlow(t)});state.tasks=state.tasks.filter(t=>t.end>state.gameTime);save();}}
function addYears(ms,n){const d=new Date(ms);d.setFullYear(d.getFullYear()+n);return d.getTime()}
function landLeaseAnnual(f){return Math.max(1,(Number(f?.ha)||0)*(isMeadow(f)?CONFIG.meadowLeaseAnnualPerHa:CONFIG.leaseAnnualPerHa));}
function landLeaseBreakEvenYears(f){const price=Math.max(1,isMeadow(f)?meadowPrice(f):landPrice(f)),upfront=Math.round(price*CONFIG.leaseUpfrontRate),annual=landLeaseAnnual(f);return Math.max(0,(price-upfront)/annual);}
function landRecoveryWarning(f){if(isMeadow(f))return'';const s=f?.soil||{},bad=f?.landProfile?.status==='abandoned'||Number(s.compaction)>65||Number(s.weeds)>55||Math.min(Number(s.N)||0,Number(s.P)||0,Number(s.K)||0)<35;return bad?' Восстановление почвы оплачивает арендатор, но улучшение остаётся собственнику участка.':'';}
function leaseInitialCost(f){return Math.round(landPrice(f)*CONFIG.leaseUpfrontRate)+f.ha*CONFIG.leaseAnnualPerHa}
function fieldSaleValue(f){const base=landPrice(f),soil=f.soil||{},ph=(soil.ph>=5.8&&soil.ph<=7.2)?1:.94,weeds=1-clamp((soil.weeds-15)/180,0,.20),comp=1-clamp((soil.compaction-35)/220,0,.15);let status=1;if(f.landProfile&&f.landProfile.status==='abandoned')status=.86;else if(f.landProfile&&f.landProfile.status==='fallow')status=1.03;return Math.round(base*clamp(ph*weeds*comp*status,.68,1.18)/500)*500}
function buyField(id){const f=state.fields.find(x=>x.id===id);if(!f||f.owned)return;if(!f.landProfile?.marketListed||f.landProfile?.holdingId)return toast('Поле сейчас не выставлено отдельным лотом');if(f.landProfile?.marketMode==='lease_only')return toast('Этот участок доступен только в аренду');const p=landPrice(f);if(state.money<p){toast('Недостаточно средств');return}state.money-=p;f.owned=true;f.tenure='owned';f.lease=null;f.landProfile.marketListed=false;f.landProfile.marketExpiresAt=null;landView='owned';finance('expense',p,'land',f.id,'Покупка земли');recordField(f,'Поле приобретено хозяйством.');log(`Куплено поле ${fieldCode(f)}: ${f.ha} га за ${rub(p)}.`);save();render();toast('Поле приобретено');}
function leaseField(id){const f=state.fields.find(x=>x.id===id);if(!f||f.owned)return;if(!f.landProfile?.marketListed||f.landProfile?.holdingId)return toast('Поле сейчас не выставлено отдельным лотом');if(f.landProfile?.marketMode==='buy_only')return toast('Этот участок доступен только для покупки');const market=landPrice(f),upfront=Math.round(market*CONFIG.leaseUpfrontRate),annual=f.ha*CONFIG.leaseAnnualPerHa,initial=upfront+annual;if(state.money<initial){toast('Недостаточно средств для входа в аренду и оплаты первого года');return}state.money-=initial;f.owned=true;f.tenure='leased';f.landProfile.marketListed=false;f.landProfile.marketExpiresAt=null;landView='owned';f.lease={startAt:state.gameTime,endAt:addYears(state.gameTime,CONFIG.leaseYears),nextPaymentAt:addYears(state.gameTime,1),annual,upfront,paidYears:1};finance('expense',upfront,'land_lease',f.id,`Аренда на ${CONFIG.leaseYears} лет · вступительный платёж 10%`);finance('expense',annual,'land_rent',f.id,`Аренда · первый год · ${rub(CONFIG.leaseAnnualPerHa)}/га`);recordField(f,`Поле взято в аренду на ${CONFIG.leaseYears} лет. Первый год оплачен: ${rub(annual)}.`);log(`${fieldCode(f)} арендовано на ${CONFIG.leaseYears} лет. Вход ${rub(upfront)} + первый год ${rub(annual)}.`);save();render();toast('Договор аренды заключён')}
function sellField(id){const f=state.fields.find(x=>x.id===id);if(!f||!f.owned||f.tenure==='leased'){toast('Продать можно только собственное поле');return}if(f.crop||taskFor(f.id)){toast('Сначала завершите работы и уборку культуры');return}const value=fieldSaleValue(f);if(!confirm(`Продать ${fieldCode(f)} за ${rub(value)}?`))return;state.money+=value;finance('income',value,'land_sale',f.id,'Продажа земли');f.owned=false;f.tenure=null;landView='market';recordField(f,`Поле продано хозяйством за ${rub(value)}.`);log(`Продано поле ${fieldCode(f)} за ${rub(value)}.`);save();page='fields';render();toast(`Продано за ${rub(value)}`)}
function returnLeasedField(id,automatic=false){const f=state.fields.find(x=>x.id===id);if(!f||!f.owned||f.tenure!=='leased')return;if((f.crop||taskFor(f.id))&&!automatic){toast('Сначала завершите работы и уборку культуры');return}if(!automatic&&!confirm(`${f.lease?.expired?'Не продлевать и вернуть':'Досрочно вернуть'} ${fieldCode(f)}? Уже уплаченные платежи не возвращаются.`))return;f.owned=false;f.tenure=null;landView='market';f.lease=null;recordField(f,'Арендованное поле возвращено арендодателю.');log(`${fieldCode(f)} возвращено арендодателю.`);save();page='fields';render();if(!automatic)toast('Поле возвращено')}
function renewLease(id){
 const f=state.fields.find(x=>x.id===id);if(!f||!f.owned||f.tenure!=='leased'||!f.lease)return;const annual=f.ha*CONFIG.leaseAnnualPerHa;if(state.money<annual){toast(`Для продления нужен первый год аренды: ${rub(annual)}`);return}if(!confirm(`Продлить аренду ${fieldCode(f)} ещё на ${CONFIG.leaseYears} лет? Сейчас будет списано ${rub(annual)} за первый год нового срока.`))return;state.money-=annual;finance('expense',annual,'land_rent',f.id,`Продление аренды · первый год нового срока`);const start=Math.max(state.gameTime,f.lease.endAt||state.gameTime);f.lease={...f.lease,startAt:start,endAt:addYears(start,CONFIG.leaseYears),nextPaymentAt:addYears(start,1),annual,paidYears:1,expired:false,renewalNotice:false};recordField(f,`Аренда продлена ещё на ${CONFIG.leaseYears} лет.`);log(`${fieldCode(f)}: аренда продлена до ${shortDate(f.lease.endAt)}.`);save();render();toast('Аренда продлена');
}
function processLandLeases(){for(const f of allLandUnits()){if(!f.owned||f.tenure!=='leased'||!f.lease)continue;const annualRate=isMeadow(f)?CONFIG.meadowLeaseAnnualPerHa:CONFIG.leaseAnnualPerHa;while(f.lease.nextPaymentAt&&f.lease.nextPaymentAt<=state.gameTime&&f.lease.nextPaymentAt<f.lease.endAt){const due=f.lease.annual||f.ha*annualRate;state.money-=due;finance('expense',due,'land_rent',f.id,`Ежегодная аренда · ${rub(annualRate)}/га`);log(`${fieldCode(f)}: списана ежегодная аренда ${rub(due)}.`);f.lease.nextPaymentAt=addYears(f.lease.nextPaymentAt,1);f.lease.paidYears=(f.lease.paidYears||1)+1;}const noticeAt=f.lease.endAt-30*DAY;if(state.gameTime>=noticeAt&&!f.lease.renewalNotice){f.lease.renewalNotice=true;log(`${fieldCode(f)}: аренда заканчивается ${shortDate(f.lease.endAt)}. Решите, продлевать ли договор.`);toast(`${fieldCode(f)}: аренда скоро заканчивается`);}if(state.gameTime>=f.lease.endAt){f.lease.expired=true;f.lease.renewalNotice=true;}}}
