 if(!f.crop||!f.plantedAt)return null;
 const c=cropDef(f),m=maturityAt(f),y=new Date(m).getFullYear(),w=seasonalWindow(c.harvest,y),ready=Math.max(m,w.start),now=state.gameTime;
