function managementWorkerQualified(worker,u){if(!worker||!u)return false;const role=roleForUnit(u),req=unitSkillRequirement(u);if(worker.id==='OWNER'||worker.role==='owner')return(Number(worker.skill)||45)>=req.threshold;return worker.role===role&&(Number(worker.skill)||0)>=req.threshold;}
