  result[it.id]={allocatedHours:Math.min(horizon,allocated),independentHours:independent,conflictHours:Math.max(0,Math.min(need,independent)-allocated),permanentHours:permanent,seasonalHours:seasonal,ownerHours:ownerH,conflictedWorkers:[...new Set(conflicted)],reservedFor:higher};
