 const contractor=opts.field&&opts.op?managementContractorScenario(opts.field,opts.op,opts.cropKey,rate,remainingHa,base,fc.window.end,startAt):null,conflictH=Math.max(0,Number(opts.conflictHours)||0),reserved=opts.reservedFor||[];
 const deficitH=Math.max(0,need-base);let advice=`Реальная кадровая ёмкость до конца окна: текущей командой доступно ${durationText(base)} → ≈ ${cur}% площади. Дефицит до полного выполнения: ${num(deficitH,1)} чел.-ч.`;
 if(conflictH>.05)advice+=` Конфликт персонала забирает ≈ ${durationText(conflictH)}${reserved.length?`; ресурс уже нужен: ${reserved.slice(0,2).join(', ')}`:''}. Центр не бронирует одного работника на две срочные работы одновременно. Переброска сюда возможна только ценой снижения покрытия перечисленных работ.`;
 if(s.seasonalCandidate&&sea>cur)advice+=` Сезонный ${s.seasonalCandidate.name}: ≈ ${sea}% · 30 дней ${rub(s.seasonalCost)}.`;
 if(s.gigCandidate&&gigAdd>0&&gig>cur)advice+=` Один разовый ${s.gigCandidate.name}: +${durationText(gigAdd)} → ≈ ${gig}% · ${rub(gigCost)}.`;
 if(s.gigCandidate)advice+=' Разовый работник считается только на одну смену до 12 ч и не заменяет постоянное покрытие.';
 if(s.seasonalCandidate&&s.gigCandidate&&combo>Math.max(sea,gig))advice+=` Сезонный + одна разовая смена: ≈ ${combo}% · ${rub(s.seasonalCost+comboGigCost)}.`;
 if(contractor&&contractor.addHa>0)advice+=` Подрядчик «Стандарт» на дефицит: +${num(contractor.addHa,1)} га → ≈ ${contractor.totalPct}% · ${rub(contractor.cost)}.`;
 if(s.seasonalCandidate&&s.gigCandidate&&s.gigCandidate.hourlyRate>0){const shifts=Math.ceil(s.seasonalCost/((Number(s.gigCandidate.hourlyRate)||1)*8));advice+=` Сезонный договор дешевле эквивалентных разовых смен примерно с ${shifts}-й 8-часовой смены.`;}
 const choices=[];if(sea>=100&&s.seasonalCandidate)choices.push({label:'сезонный договор',cost:s.seasonalCost,pct:sea});if(gig>=100&&s.gigCandidate)choices.push({label:'одна разовая смена',cost:gigCost,pct:gig});if(combo>=100&&s.seasonalCandidate&&s.gigCandidate)choices.push({label:'сезонный + разовый',cost:s.seasonalCost+comboGigCost,pct:combo});if(contractor?.totalPct>=100)choices.push({label:'подрядчик на остаток',cost:contractor.cost,pct:contractor.totalPct});choices.sort((a,b)=>a.cost-b.cost);const economicChoice=choices[0]||null;if(economicChoice){const afford=economicChoice.cost<=state.money;advice+=` Экономически минимальный вариант завершить 100% из доступных сейчас: ${economicChoice.label}, ${rub(economicChoice.cost)}${afford?'':' — текущих денег недостаточно'}.`;}
