  if(state.gameTime>w.end||state.gameTime<w.start-14*DAY)continue;
  const ready=sowReadiness(f,ck),plan=bestOwnedPlan(f,'sow',ck),q=plan?quoteOwnedUnits(f,plan.units):null;let fc=q?managementWindowForecast(f,'sow',ck,q.rate,f.ha,state.gameTime,0):null;
