  const q=bestOwnedPlan(a.field,a.kind,a.cropKey||a.field.crop),qq=q?quoteOwnedUnits(a.field,q.units):null;let fc=qq?managementWindowForecast(a.field,a.kind,a.cropKey||a.field.crop,qq.rate,a.field.ha,state.gameTime,0):null;const risky=!!(fc?.window&&fc.windowShare<.999),priority=(a.urgent||risky)?3:1;
  rows.push({priority,field:a.field,title:a.title,detail:a.reason||a.status||'',window:fc?.window?'Расчёт кадрового конфликта…':`${shortDate(a.start)} — ${shortDate(a.end)}`,action:'calendar',_mgmt:q&&qq&&fc?.window?{id:`field:${a.field.id}:${a.kind}`,units:q.units,rate:qq.rate,remainingHa:a.field.ha,workHours:qq.hours,endAt:fc.window.end,optimalEnd:fc.window.optimalEnd,op:a.kind,cropKey:a.cropKey||a.field.crop,fc}:null});
