 for(const r of rows){if(!r._mgmt)continue;const m=r._mgmt,a=alloc[m.id]||{allocatedHours:0,conflictHours:0,reservedFor:[]},staff=managementStaffRecommendation(m.units,m.fc,m.rate,m.remainingHa,state.gameTime,{currentHours:a.allocatedHours,conflictHours:a.conflictHours,reservedFor:a.reservedFor,field:r.field,op:m.op,cropKey:m.cropKey}),optAlloc=managementPortfolioStaffAllocation([{id:'opt',label:r.title,units:m.units,endAt:m.optimalEnd,workHours:m.workHours,priority:r.priority}],state.gameTime).opt?.allocatedHours||0,fc=managementWindowForecast(r.field,m.op,m.cropKey,m.rate,m.remainingHa,state.gameTime,0,{optimalWorkHours:Math.min(optAlloc,a.allocatedHours),windowWorkHours:a.allocatedHours});r.window=staff?.text||`Текущей командой до конца окна ≈ ${Math.round(fc.windowShare*100)}%`;if(staff?.currentPct<100&&state.gameTime>=m.fc.window.start)r.priority=3;else if(a.conflictHours>.05)r.priority=Math.max(r.priority,2);delete r._mgmt;}
 return rows.sort((a,b)=>b.priority-a.priority||a.field.id-b.field.id).slice(0,14);
