  const keys=Object.entries(a.systems||{}).filter(([,v])=>Number.isFinite(v)).map(([k])=>k),due=keys.map(k=>({k,...preventiveDueInfo(a,k)})).filter(x=>x.due||x.soon).sort((x,y)=>x.left-y.left),risk=keys.map(k=>({k,r:criticalFailureRisk100h(a,k)})).sort((x,y)=>y.r-x.r)[0];
