function tutorialStart(){state.tutorial=tutorialDefault();state.tutorial.active=true;state.tutorial.startedAt=state.gameTime;state.tutorial.step=0;state.tutorial.paused=false;setGameSpeed(0);save();navigatePage('dashboard');render();toast('Интерактивное обучение запущено');}
function tutorialStop(complete=false){state.tutorial=normalizeTutorial(state.tutorial);state.tutorial.active=false;state.tutorial.paused=!complete;state.tutorial.completed=!!complete;if(complete)state.tutorial.completedAt=state.gameTime;clearTutorialTour();save();render();}
function tutorialSkipStep(){const t=normalizeTutorial(state.tutorial);t.step=Math.min(FIRST_YEAR_TUTORIAL_STEPS.length,t.step+1);state.tutorial=t;tutorialCheckProgress(true);save();render();}
function tutorialCheckProgress(force=false){if(!state?.tutorial?.active||state.tutorial.paused)return false;let changed=false,guard=0;while(state.tutorial.step<FIRST_YEAR_TUTORIAL_STEPS.length&&guard++<4){const st=FIRST_YEAR_TUTORIAL_STEPS[state.tutorial.step];let ok=false;try{ok=!!st.done();}catch{}if(!ok&&!force)break;if(!ok&&force)ok=true;if(ok){state.tutorial.step++;changed=true;force=false;}else break;}if(state.tutorial.step>=FIRST_YEAR_TUTORIAL_STEPS.length){state.tutorial.active=false;state.tutorial.completed=true;state.tutorial.completedAt=state.gameTime;log('Интерактивное обучение первого года завершено.');changed=true;}if(changed)save();return changed;}
function clearTutorialTour(){tutorialHintTarget=null;if(!state?.tutorial)return;state.tutorial.tourPage=null;state.tutorial.tourIndex=0;document.querySelectorAll('.tutorial-focus').forEach(x=>x.classList.remove('tutorial-focus'));document.getElementById('tutorialSpotlight')?.remove();}
function tutorialTourStart(pg){if(!state?.tutorial?.active||state.tutorial.paused||state.tutorial.seenTours?.[pg]||!TUTORIAL_PAGE_TOURS[pg])return;state.tutorial.tourPage=pg;state.tutorial.tourIndex=0;save();}
function tutorialTourAdvance(){const t=state.tutorial;if(!t?.tourPage)return;const arr=TUTORIAL_PAGE_TOURS[t.tourPage]||[];t.tourIndex++;if(t.tourIndex>=arr.length){t.seenTours[t.tourPage]=true;clearTutorialTour();save();render();}else{save();renderTutorialOverlays();}}
function tutorialTourSkip(){const t=state.tutorial;if(t?.tourPage){t.seenTours[t.tourPage]=true;clearTutorialTour();save();render();}}
function tutorialShowWhere(pg){tutorialHintTarget=pg;renderTutorialOverlays();}
function tutorialCurrentStepHtml(){if(!state?.tutorial?.active)return'';const i=state.tutorial.step,st=FIRST_YEAR_TUTORIAL_STEPS[i];if(!st)return'';return`<div class="tutorial-mission"><div><div class="eyebrow">ОБУЧЕНИЕ · ШАГ ${i+1} ИЗ ${FIRST_YEAR_TUTORIAL_STEPS.length}</div><b>${st.title}</b><span>${st.text}</span></div><div class="row-actions"><button class="btn secondary" data-tutorial-go="${st.page}">Показать где</button><button class="btn secondary" data-tutorial-skip-step>Пропустить шаг</button><button class="btn secondary" data-tutorial-pause>Пауза обучения</button><button class="btn secondary" data-tutorial-end>Завершить досрочно</button></div></div>`;}
function tutorialOverlayActive(){return !!(state?.tutorial?.active&&!state.tutorial.paused&&(tutorialHintTarget||state.tutorial.tourPage));}
function tutorialTooltipPlacement(target,desiredW=390){const r=target.getBoundingClientRect(),vw=Math.max(320,window.innerWidth||1024),vh=Math.max(240,window.innerHeight||768),margin=12,gap=14,minW=Math.min(280,vw-margin*2),w=Math.max(minW,Math.min(desiredW,vw-margin*2));let left=Math.max(margin,Math.min(vw-w-margin,r.left));const belowSpace=vh-r.bottom-gap,aboveSpace=r.top-gap;let top;if(belowSpace>=170)top=r.bottom+gap;else if(aboveSpace>=170)top=Math.max(margin,r.top-170-gap);else top=Math.max(margin,Math.min(vh-190-margin,r.bottom+gap));return{r,w,left,top};}
function renderTutorialOverlays(){if(!state?.tutorial?.active||state.tutorial.paused)return;document.querySelectorAll('.tutorial-focus').forEach(x=>x.classList.remove('tutorial-focus'));document.getElementById('tutorialSpotlight')?.remove();if(tutorialHintTarget){const target=document.querySelector(`.nav-item[data-page=\"${tutorialHintTarget}\"]`);if(target){target.classList.add('tutorial-focus');const p=tutorialTooltipPlacement(target,360),box=document.createElement('div');box.id='tutorialSpotlight';box.className='tutorial-spotlight';box.style.left=p.left+'px';box.style.top=p.top+'px';box.style.width=p.w+'px';box.innerHTML=`<div class=\"tutorial-spotlight-shade\"></div><div class=\"tutorial-spotlight-box\"><div class=\"eyebrow\">ТЕКУЩЕЕ ЗАДАНИЕ</div><h3>Нажмите сюда</h3><p>Перейдите в раздел «${FIRST_YEAR_TUTORIAL_STEPS[state.tutorial.step]?.title?.replace(/^.*«|».*/g,'')||tutorialHintTarget}». Переход будет засчитан автоматически.</p></div>`;document.body.appendChild(box);}return;}const tp=state.tutorial.tourPage;if(!tp||tp!==page)return;const item=(TUTORIAL_PAGE_TOURS[tp]||[])[state.tutorial.tourIndex];if(!item){tutorialTourSkip();return;}const target=document.querySelector(item[0]);if(!target){tutorialTourAdvance();return;}target.classList.add('tutorial-focus');const r0=target.getBoundingClientRect();if(r0.top<70||r0.bottom>window.innerHeight-70){try{target.scrollIntoView({block:'center',behavior:'auto'});}catch{}}const p=tutorialTooltipPlacement(target,390),box=document.createElement('div');box.id='tutorialSpotlight';box.className='tutorial-spotlight';box.style.left=p.left+'px';box.style.top=p.top+'px';box.style.width=p.w+'px';box.innerHTML=`<div class="tutorial-spotlight-shade"></div><div class="tutorial-spotlight-box"><div class="eyebrow">ПОДСКАЗКА ПО ЭКРАНУ</div><h3>${item[1]}</h3><p>${item[2]}</p><div class="row-actions"><button class="btn" data-tutorial-tour-next>${state.tutorial.tourIndex+1>=(TUTORIAL_PAGE_TOURS[tp]||[]).length?'Готово':'Далее'}</button><button class="btn secondary" data-tutorial-tour-skip>Пропустить обзор</button></div></div>`;document.body.appendChild(box);box.querySelector('[data-tutorial-tour-next]')?.addEventListener('click',tutorialTourAdvance);box.querySelector('[data-tutorial-tour-skip]')?.addEventListener('click',tutorialTourSkip);}
function scheduleTutorialOverlay(){if(tutorialOverlayScheduled)return;tutorialOverlayScheduled=true;const fn=()=>{tutorialOverlayScheduled=false;if(!state?.tutorial?.active)return;tutorialCheckProgress(false);if(!state.tutorial.tourPage)tutorialTourStart(page);renderTutorialOverlays();};if(typeof requestAnimationFrame==='function')requestAnimationFrame(fn);else setTimeout(fn,0);}
function tutorialCard(title,body){return `<div class="card section-card tutorial-card"><h3>${title}</h3><div class="muted" style="line-height:1.55;margin-top:6px">${body}</div></div>`;}
function renderTutorial(){
 const q=(tutorialQuery||'').trim().toLowerCase();
 const tabs=[['start','Новая компания'],['sections','Все разделы'],['buttons','Кнопки и действия'],['concepts','Основы игры']];
 const t=normalizeTutorial(state.tutorial);state.tutorial=t;const interactive=t.active?`<div class="note info tutorial-launch"><b>Интерактивное обучение запущено · шаг ${Math.min(t.step+1,FIRST_YEAR_TUTORIAL_STEPS.length)} из ${FIRST_YEAR_TUTORIAL_STEPS.length}</b><div class="muted small">Игра ведёт по реальному хозяйству и автоматически засчитывает действия. Прогресс сохраняется.</div><div class="row-actions" style="margin-top:10px"><button class="btn" data-tutorial-resume>Продолжить обучение</button><button class="btn secondary" data-tutorial-restart>Начать заново</button><button class="btn secondary" data-tutorial-pause>Пауза обучения</button></div></div>`:`<div class="note info tutorial-launch"><b>${t.completed?'Обучение уже пройдено':'Интерактивное обучение первого года'}</b><div class="muted small">Пошаговый игровой сценарий с автоматическими заданиями и подсветкой интерфейса.</div><div class="row-actions" style="margin-top:10px"><button class="btn" data-tutorial-start>${t.completed?'Пройти ещё раз':'Запустить обучение'}</button>${t.paused&&!t.completed?'<button class="btn secondary" data-tutorial-resume>Продолжить</button>':''}</div></div>`;const head=`${pageHead('Обучение','Полный встроенный справочник AgroManager Pilot: от первого клика до замкнутого производственного цикла.')}${interactive}<div class="card section-card"><div class="row-actions">${tabs.map(([id,label])=>`<button class="btn ${tutorialTab===id?'':'secondary'}" data-tutorial-tab="${id}">${label}</button>`).join('')}</div><div style="margin-top:12px"><input class="input" data-tutorial-search placeholder="Поиск по обучению: например «лизинг», «уборка», «ремонт»" value="${tutorialQuery}"></div></div>`;
 if(q){const pool=[...TUTORIAL_SECTIONS.map(x=>({title:x.title,body:x.body})),...TUTORIAL_BUTTON_GROUPS.map(x=>({title:x[0],body:x[1]})),...TUTORIAL_START_STEPS.map(x=>({title:x[0],body:x[1]}))].filter(x=>(x.title+' '+x.body).toLowerCase().includes(q));return head+`<div class="card section-card"><div class="section-title"><h2>Результаты поиска</h2><span class="pill">${pool.length}</span></div>${pool.length?pool.map(x=>tutorialCard(x.title,x.body)).join(''):'<div class="empty">Ничего не найдено. Попробуйте более короткое слово.</div>'}</div>`;}
 if(tutorialTab==='sections')return head+`<div class="note info"><b>Как читать:</b> это карта интерфейса. Название совпадает с пунктом левого меню; внутри описана роль раздела и типичные решения игрока.</div>${TUTORIAL_SECTIONS.map(x=>tutorialCard(x.title,x.body+` <button class="btn secondary" style="margin-top:10px" data-tutorial-open="${x.id}">Открыть раздел</button>`)).join('')}`;
 if(tutorialTab==='buttons')return head+`<div class="note info"><b>Справочник действий.</b> Повторяющиеся кнопки описаны семействами: одинаковая кнопка у разных полей или моделей выполняет тот же тип действия над выбранным объектом.</div>${TUTORIAL_BUTTON_GROUPS.map(x=>tutorialCard(x[0],x[1])).join('')}`;
 if(tutorialTab==='concepts')return head+[
  ['Главный принцип','У игры нет скрытого штрафа за размер хозяйства и нет обязательной «меты». Сильная стратегия может оставаться сильной. Ограничителями выступают реальные деньги, время, люди, техника, расстояние, погода и агрономия.'],
  ['Время','Почти всё занимает игровое время: доставка, поездка к полю, работа, ремонт, смена, отдых и логистика. Ускорение времени не пропускает критические события.'],
  ['Деньги и cashflow','Текущий счёт отвечает только на вопрос «сколько денег сейчас». Для решения о покупке смотрите будущие обязательства и сезонные расходы. Принятый контракт или будущий урожай не равны наличным деньгам.'],
  ['Урожайность','Целевая урожайность — план питания, не бонус. Фактический результат складывается из сроков, условий посева, почвы, уплотнения, питания, pH, севооборота, болезней/вредителей/сорняков, качества операций и уборки. В карточке поля доступен прозрачный waterfall факторов.'],
  ['Техника','Мощность — не единственная совместимость. Учитываются тяга/масса, гидравлика, ВОМ, навеска, жатки и состояние узлов. Более мощный двигатель не превращает лёгкое шасси в тяжёлый трактор.'],
  ['Износ и ремонт','Обычная поломка ремонтируется. Критически разрушенный крупный узел заменяется. Профилактика снижает риск, но не омолаживает старую машину. Снятые физические узлы могут храниться как активы и использоваться повторно.'],
  ['Люди','Производительность ограничена реальными сменами. Работник может быть занят или отдыхать. Разовый специалист закрывает одну смену, сезонный — период, постоянный — долгосрочную потребность.'],
  ['Логистика','При уборке комбайн производит поток тонн, а транспорт должен его принять и вывезти. Автопоезд увеличивает ёмкость одной дорожной единицы; несколько грузовиков дают чередование; перегрузчик создаёт полевой буфер. Поздняя фактическая уборка части поля может снизить её урожайность.'],
  ['Севооборот','Предшественники влияют на урожайный и санитарный фон, но игра не требует единственно правильной схемы. Разумный разнообразный цикл обычно устойчивее частых повторов одной группы культур.'],
  ['Кризис','Финансовая проблема развивается поэтапно: напряжение, кризис, неплатёжеспособность, затем банкротство при длительном отсутствии восстановления. Это время для продажи лишних активов, снижения инвестиций, работы с запасами и долгом — один плохой месяц не должен мгновенно завершать игру.']
 ].map(x=>tutorialCard(x[0],x[1])).join('');
 return head+`<div class="note info"><b>Если вы никогда не управляли хозяйством — идите по шагам сверху вниз.</b> Не требуется знать сельское хозяйство заранее: каждый шаг указывает, какой раздел открыть и зачем.</div><div class="card section-card"><div class="section-title"><h2>Первый производственный цикл</h2><span class="pill">18 шагов</span></div>${TUTORIAL_START_STEPS.map((x,i)=>`<details class="tutorial-step" ${i<3?'open':''}><summary><b>${x[0]}</b></summary><div class="muted" style="line-height:1.55;padding:10px 4px 14px">${x[1]}</div></details>`).join('')}</div><div class="note info"><b>Цикл замкнулся.</b> После шага 18 вы снова находитесь в точке планирования нового сезона. Дальше задача игрока — увеличивать масштаб только тогда, когда хватает оборотных денег, людей, техники, логистики и времени агрономических окон.</div>`;
}


function firstFarmSeasonBudget(){
 const fs=owned().filter(f=>!isMeadow(f)),reserve=300000;
 if(!fs.length)return{fields:0,ha:0,cost:0,revenue:0,margin:0,cashAfter:state.money,reserve,gap:0,rows:[]};
 let cost=0,revenue=0;const rows=[];
 for(const f of fs){const cropKey=f.crop||f.plannedCrop||cropSelection?.[f.id]||'spring_wheat',c=CROPS[cropKey]||CROPS.spring_wheat,seed=SEEDS[cropKey],seedCost=seed?Math.round((Number(seed.rate)||0)*(Number(seed.price)||0)*f.ha):0;
  const ops=['plow','cultivate','sow','herbicide','harvest'];let contractor=0;
  for(const op of ops){const q=contractorTierQuote(f,op,'standard',cropKey);contractor+=q?.fullFieldCost||Math.round((OPS[op]?.cost||0)*f.ha);}
  const materials=seedCost+Math.round(f.ha*4200),fieldCost=contractor+materials,yieldT=(f.crop?projectedYieldPerHa(f):(Number(c.baseYield)||3.5)*.85)*f.ha,fieldRevenue=Math.round(yieldT*(Number(c.price)||0)*.95);
  cost+=fieldCost;revenue+=fieldRevenue;rows.push({field:f,cropKey,cost:fieldCost,revenue:fieldRevenue,margin:fieldRevenue-fieldCost});
 }
 const cashAfter=state.money-cost,margin=revenue-cost,gap=Math.max(0,reserve-cashAfter);return{fields:fs.length,ha:fs.reduce((a,f)=>a+f.ha,0),cost,revenue,margin,cashAfter,reserve,gap,rows};
}
function firstFarmGuideHtml(){const b=firstFarmSeasonBudget(),fs=owned().filter(f=>!isMeadow(f)),fleet=state.equipment?.fleet||[];let stage,title,text,button,pageName;
 if(!fs.length){stage='1/5';title='Найдите первое поле';text='Сравните покупку и аренду. Для старта с нуля аренда обычно оставляет больше оборотных денег на первый сезон.';button='Открыть рынок земли';pageName='fields';}
 else if(!fs.some(f=>f.crop)){stage='2/5';title='Соберите бюджет до уборки';text=`На ${num(b.ha,0)} га ориентир полного подрядного сезона сейчас ≈ ${rub(b.cost)}. После финансирования останется ${rub(b.cashAfter)}.`;button='Открыть операции';pageName='operations';}
 else if((state.tasks||[]).length){stage='3/5';title='Проведите сезон без кассового разрыва';text=`Активных работ: ${(state.tasks||[]).length}. Сохраняйте резерв около ${rub(b.reserve)} на погоду, ремонт и незапланированного подрядчика.`;button='Открыть агрокалендарь';pageName='calendar';}
 else if(!(state.warehouse?.lots||[]).length&&!Object.values(state.warehouse?.stocks||{}).some(x=>Number(x)>0)){stage='4/5';title='Доведите культуру до первого урожая';text=`Прогноз выручки по текущим/плановым культурам ≈ ${rub(b.revenue)}, расчётный результат сезона ≈ ${b.margin>=0?'+':''}${rub(b.margin)}.`;button='Открыть поля';pageName='operations';}
 else{stage='5/5';title='Первый цикл хозяйства замкнут';text='Теперь сравнивайте подряд с собственной техникой: покупайте машину, когда её загрузка и контроль сроков оправдывают капитал.';button='Сравнить технику';pageName='equipment';}
 const cls=b.gap>0?'warnbox':'goodbox';return `<div class="card section-card first-farm-guide"><div class="section-title"><div><span class="status info">ПЕРВОЕ ХОЗЯЙСТВО · ${stage}</span><h2>${title}</h2></div><button class="btn" data-page="${pageName}">${button}</button></div><div class="note ${cls}">${text}${b.fields?`<div class="muted small" style="margin-top:6px">Сезон: затраты ${rub(b.cost)} · прогноз выручки ${rub(b.revenue)} · результат ${b.margin>=0?'+':''}${rub(b.margin)} · резерв после затрат ${rub(b.cashAfter)}${b.gap?` · до рекомендуемого резерва не хватает ${rub(b.gap)}`:''}.</div>`:''}</div>${b.rows.length?`<details style="margin-top:10px"><summary class="muted small" style="cursor:pointer">Показать поля и прогноз</summary><div class="table-wrap"><table><thead><tr><th>ПОЛЕ</th><th>КУЛЬТУРА</th><th>ДО УБОРКИ</th><th>ПРОГНОЗ ВЫРУЧКИ</th><th>РЕЗУЛЬТАТ</th></tr></thead><tbody>${b.rows.map(r=>`<tr><td>${fieldCode(r.field)} · ${num(r.field.ha,0)} га</td><td>${CROPS[r.cropKey]?.label||r.cropKey}</td><td>${rub(r.cost)}</td><td>${rub(r.revenue)}</td><td class="${r.margin>=0?'positive':'negative'}">${r.margin>=0?'+':''}${rub(r.margin)}</td></tr>`).join('')}</tbody></table></div></details>`:''}</div>`}
function usedMarketPulseHtml(){const market=state.equipment?.usedMarket||[],now=state.gameTime,last=Number(state.equipment?.lastMarketRefresh)||now,next=last+7*DAY,newCount=market.filter(l=>now-(Number(l.createdAt)||0)<=7*DAY).length,ending=market.filter(l=>(Number(l.expiresAt)||0)-now<=3*DAY).length,deals=market.filter(l=>Number(l.readyEquivalentPrice)>0&&Number(l.price)<=Number(l.readyEquivalentPrice)*.82&&Number(l.condition)>=55).sort((a,b)=>(a.price/a.readyEquivalentPrice)-(b.price/b.readyEquivalentPrice)).slice(0,3);return `<div class="card section-card"><div class="section-title"><div><h2>Пульс Б/У рынка</h2><div class="muted tiny">Рынок физически обновляется по игровому времени; объявления снимаются по своим срокам.</div></div><span class="pill">следующее пополнение ≈ ${shortDate(next)}</span></div><div class="grid kpis"><div class="card kpi"><div class="label">СВЕЖИЕ ≤ 7 ДНЕЙ</div><div class="v">${newCount}</div></div><div class="card kpi"><div class="label">УЙДУТ ≤ 3 ДНЕЙ</div><div class="v">${ending}</div></div><div class="card kpi"><div class="label">ПОСЛЕДНЕЕ ПОПОЛНЕНИЕ</div><div class="v" style="font-size:18px">${shortDate(last)}</div></div></div>${deals.length?`<div class="note info"><b>Редкие ценовые предложения:</b> ${deals.map(l=>`${equipmentModel(l.modelId)?.name||l.modelId} · ${rub(l.price)} · состояние ≈ ${num(l.condition,0)}%`).join(' · ')}. Низкая цена не отменяет диагностику и риск ремонта.</div>`:''}</div>`}
function usedModelOperation(m){if(!m)return null;if(m.type==='combine')return'harvest';if(m.type!=='implement')return null;const c=m.category||'';return({plow:'plow',cultivate:'cultivate',disk:'disk',stubble:'stubble',harrow:'harrow',sow_grain:'sow',sow_row:'sow',sprayer:'herbicide',fertilizer:'nitrate',ridge:'ridge',mower:'mow',tedder:'ted',rake:'rake',baler:'bale'}[c]||null)}
function usedListingEconomicsHtml(l){const m=equipmentModel(l?.modelId),area=owned().filter(f=>!isMeadow(f)).reduce((a,f)=>a+f.ha,0);if(!m||area<=0)return'';const op=usedModelOperation(m);if(op){const f={ha:area,crop:'spring_wheat',distanceKm:8},q=contractorTierQuote(f,op,'standard','spring_wheat'),replaced=q?.fullFieldCost||Math.round((OPS[op]?.cost||0)*area),seasons=replaced>0?l.price/replaced:0;return `<div class="muted tiny" style="margin-top:4px">На ваших ${num(area,0)} га потенциально заменяет подряд ≈ <b>${rub(replaced)}/сезон</b>${seasons?` · цена ≈ ${num(seasons,1)} такого объёма подрядных сезонов`:''}. До топлива, персонала, ремонта и остаточной стоимости.</div>`;}if(m.type==='tractor'){const ownImpl=(state.equipment?.fleet||[]).map(a=>equipmentModel(a.modelId)).filter(x=>x?.type==='implement'&&(!x.requiredHp||x.requiredHp<=(listingEngineSpec(l)?.hp||m.hp||0))).length,marketImpl=(state.equipment?.usedMarket||[]).filter(x=>{const im=equipmentModel(x.modelId);return im?.type==='implement'&&(!im.requiredHp||im.requiredHp<=(listingEngineSpec(l)?.hp||m.hp||0));}).length;return `<div class="muted tiny" style="margin-top:4px">Совместимая механизация: ${ownImpl} агрегатов уже в парке · ${marketImpl} подходящих Б/У объявлений. Сам трактор экономию не создаёт без рабочего агрегата.</div>`;}return''}
function usedListingBadgeHtml(l){const now=state.gameTime,age=(now-(Number(l.createdAt)||now))/DAY,left=((Number(l.expiresAt)||now)-now)/DAY,deal=Number(l.readyEquivalentPrice)>0&&Number(l.price)<=Number(l.readyEquivalentPrice)*.82&&Number(l.condition)>=55;return `<div class="row-actions" style="margin-top:4px">${age<=2?'<span class="status good">Новое объявление</span>':''}${left<=3?'<span class="status warn">Скоро снимут</span>':''}${deal?'<span class="status info">Редкая цена</span>':''}</div>`}

function renderDashboard(){const own=owned(),area=own.reduce((sum,f)=>sum+f.ha,0),w=weatherFor(state.gameTime),fs=financeStats(),active=own.filter(f=>f.crop).length,leases=own.filter(f=>f.tenure==='leased'&&f.lease?.renewalNotice),actions=calendarAlerts().filter(a=>a.urgent||a.agronomy).slice(0,8),newCompany=(state.gameTime-(new Date(2026,0,1,8,0,0).getTime()))<14*DAY&&state.history.length<40;return`${pageHead('Обзор хозяйства','Агрономия, производство и экономика')}${newCompany?`<div class="note info" style="margin-bottom:14px"><b>Первый раз в AgroManager?</b> Встроенное обучение проведёт от выбора земли и культуры до уборки, продажи и планирования следующего сезона. <button class="btn secondary" style="margin-left:8px" data-page="tutorial">Начать обучение</button></div>`:''}${firstFarmGuideHtml()}<div class="grid kpis"><div class="card kpi"><div class="label">ДЕНЕЖНЫЕ СРЕДСТВА</div><div class="v">${rub(state.money)}</div><div class="s">Финрезультат: <span class="${fs.operating>=0?'positive':'negative'}">${rub(fs.operating)}</span></div></div><div class="card kpi"><div class="label">ЗЕМЕЛЬНЫЙ БАНК</div><div class="v">${num(area,0)} га</div><div class="s">${own.filter(f=>f.tenure!=='leased').length} собственных · ${own.filter(f=>f.tenure==='leased').length} арендованных · сенокосы ${num(ownedMeadows().reduce((a,f)=>a+f.ha,0),0)} га</div></div><div class="card kpi"><div class="label">ПОСЕВЫ</div><div class="v">${active}</div><div class="s">активных полей</div></div><div class="card kpi"><div class="label">ПОГОДА</div><div class="v">${w.temp>0?'+':''}${w.temp}°C</div><div class="s">${w.condition} · ${w.precip} мм</div></div></div>${actions.length?`<div class="card section-card"><div class="section-title"><h2>Что требует внимания</h2><span class="status warn">${actions.length}</span></div>${actions.map(a=>`<div class="rec ${a.urgent?'warn':'info'}"><div><b>${fieldCode(a.field)} · ${a.title}</b><div class="muted small">${CROPS[a.cropKey||a.field.crop]?.label||''}${a.reason?` · ${a.reason}`:''}${a.status?` · ${a.status}`:''}</div></div><button class="btn secondary" data-page="calendar">Агрокалендарь</button></div>`).join('')}</div>`:''}${leases.length?`<div class="card section-card"><div class="section-title"><h2>Аренда требует решения</h2><span class="status warn">${leases.length}</span></div>${leases.map(f=>`<div class="rec warn"><div><b>${fieldCode(f)} · ${f.ha} га</b><div class="muted small">${f.lease?.expired?'Срок аренды завершён':'Договор заканчивается'} · ${shortDate(f.lease?.endAt)}</div></div><button class="btn" data-land-view-jump="owned">Открыть поля</button></div>`).join('')}</div>`:''}<div class="card section-card"><div class="section-title"><h2>Журнал</h2></div>${state.history.slice(0,12).map(h=>`<div class="task"><div>${h.text}</div><div class="muted small">${dateFmt(h.time)}</div></div>`).join('')}</div>`;}
function soilMetric(f,label,value,suffix=''){return soilKnown(f)?`<div class="metric"><span class="label">${label}</span><b>${value}${suffix}</b></div>`:`<div class="metric metric-locked"><span class="label">${label}</span><b>?</b><small>Нужен анализ</small></div>`;}
function nutrientStatus(f,cropKey){const c=CROPS[cropKey]||CROPS.spring_wheat,q=nutrientSupply(f,cropKey),target=yieldTargetFor(f,cropKey),needs=targetNutrientNeeds(cropKey,target),ratios={N:q.N/Math.max(1,needs.N),P:q.P/Math.max(1,needs.P),K:q.K/Math.max(1,needs.K)},deficits={N:Math.max(0,needs.N-q.N),P:Math.max(0,needs.P-q.P),K:Math.max(0,needs.K-q.K)};const limiting=Object.keys(ratios).sort((a,b)=>ratios[a]-ratios[b])[0],score=clamp(Math.min(ratios.N,ratios.P,ratios.K),0,1.2);return{crop:c,q,target,needs,ratios,deficits,limiting,score};}
function yieldTargetPlanHtml(f,cropKey){if(!f?.owned)return'';const c=CROPS[cropKey]||CROPS.spring_wheat,r=targetYieldRange(cropKey),target=yieldTargetFor(f,cropKey),potential=agronomicTargetPotential(f,cropKey),plan=soilKnown(f)?targetNutrientPlan(f,cropKey):null,price=cropMarketPrice(cropKey),gross=price>0?target*f.ha*price:0,options=yieldTargetOptionValues(cropKey).map(x=>`<option value="${x}" ${Math.abs(x-target)<.0001?'selected':''}>${num(x,2)} т/га${Math.abs(x-Number(c.baseYield))<.0001?' · стандарт':''}</option>`);const targetClass=target>potential*1.08?'warn':target<=potential?'good':'info';const locked=!!f.crop,till=tillageRecommendation(f,cropKey).filter(x=>x.op).slice(0,3),sowChk=opAllowed(f,'sow',cropKey),fieldMap=[...till.map(x=>({stage:x.stage||'Почвообработка',op:x.op,label:x.title||OPS[x.op]?.label||x.op,reason:x.text||'',chk:opAllowed(f,x.op,cropKey)})),...(!f.crop?[{stage:'Посев',op:'sow',label:`Посев · ${c.label}`,reason:`После подготовки поля перейти к посеву в календарное окно; техника: ${machineryAvailabilityLabel(f,'sow',cropKey)}.`,chk:sowChk}]:[])];const fieldMapHtml=fieldMap.length?fieldMap.map(x=>`<div class="rec ${x.chk?.ok?'info':'warn'}"><div><div class="muted tiny">${x.stage}</div><b>${x.label}</b><div class="muted small">${x.reason}</div><div class="muted tiny">Техника: ${machineryAvailabilityLabel(f,x.op,cropKey)}</div></div><button class="btn secondary" data-op="${x.op}" data-field="${f.id}" data-crop="${cropKey}" ${x.chk?.ok?'':`disabled title="${x.chk?.label||'Недоступно'}"`}>${x.chk?.ok?'Перейти':'Не сейчас'}</button></div>`).join(''):'<div class="rec good">Основная подготовка поля сейчас не требует дополнительного прохода.</div>';const steps=plan?plan.steps.map(z=>{const fd=FERTS[z.op],chk=opAllowed(f,z.op,cropKey),machine=machineryAvailabilityLabel(f,z.op,cropKey);return `<div class="rec ${chk.ok?'info':'warn'}"><div><div class="muted tiny">${z.stage}</div><b>${fd.label} · ${z.dose} ${fd.unit}</b><div class="muted small">${z.reason}</div><div class="muted tiny">Техника: ${machine} · материалы ≈ ${rub(fertilizerCost(f,z.op,z.dose))}</div></div><button class="btn secondary" data-fert-rec="${z.op}" data-field="${f.id}" data-dose="${z.dose}" data-crop="${cropKey}" ${chk.ok?'':`disabled title="${chk.label}"`}>${chk.ok?'Внести':'Не сейчас'}</button></div>`}).join(''):'';const future=plan?.future?.length?plan.future.map(z=>`<div class="rec"><div><div class="muted tiny">${z.stage}</div><b>${FERTS[z.op].label} · ориентир ${z.dose} ${FERTS[z.op].unit}</b><div class="muted small">${z.reason}</div></div><span class="status info">после всходов</span></div>`).join(''):'';const excess=soilKnown(f)?nitrogenExcessRisk(f,cropKey):0;return `<div class="card section-card target-yield-plan"><div class="section-title"><h2>Технологическая карта · цель урожайности</h2><span class="status ${targetClass}">${num(target,2)} т/га</span></div><div class="grid two-col"><div><label class="label">ЦЕЛЕВАЯ УРОЖАЙНОСТЬ · ${c.label}</label><select class="select wide" data-target-yield="${f.id}" data-target-crop="${cropKey}" ${locked?'disabled':''}>${options.join('')}</select><div class="muted small" style="margin-top:6px">${locked?`Цель зафиксирована при посеве: ${num(target,2)} т/га.`:'Цель задаёт плановую интенсивность всей технологии: она меняет расчётный потенциал и потребность N/P/K. Погода, сроки, почва, питание и защита растений определяют, какая часть цели будет реализована.'}</div></div><div class="passport-grid"><div class="metric"><span class="label">ОЦЕНКА ПОТЕНЦИАЛА ПОЛЯ</span><b>≈ ${num(potential,2)} т/га</b></div><div class="metric"><span class="label">ВАЛОВОЙ ДОХОД ПРИ ЦЕЛИ</span><b>${gross?rub(gross):'—'}</b><span class="muted tiny">до затрат и фактических потерь</span></div></div></div><div class="divider"></div><div class="label">ТЕХНОЛОГИЧЕСКАЯ ЦЕПОЧКА ПОЛЯ</div>${fieldMapHtml}${!soilKnown(f)?`<div class="note warnbox" style="margin-top:12px">Для технологической карты питания нужен анализ почвы. Цель сохранить можно, но дозы и стоимость появятся после лаборатории.</div>`:`<div class="divider"></div><div class="passport-grid"><div class="metric"><span class="label">ПОТРЕБНОСТЬ N/P/K ПОД ЦЕЛЬ</span><b>${Math.round(plan.needs.N)}/${Math.round(plan.needs.P)}/${Math.round(plan.needs.K)}</b></div><div class="metric"><span class="label">ДОСТУПНО СЕЙЧАС</span><b>${Math.round(plan.q.N)}/${Math.round(plan.q.P)}/${Math.round(plan.q.K)}</b></div><div class="metric"><span class="label">ДЕФИЦИТ ДО ЦЕЛИ</span><b>${Math.round(plan.def.N)}/${Math.round(plan.def.P)}/${Math.round(plan.def.K)}</b></div><div class="metric"><span class="label">МАТЕРИАЛЫ ПО ТЕКУЩИМ ЭТАПАМ</span><b>${rub(plan.materialCost)}</b></div></div>${plan.recoveryDeferred?`<div class="note info" style="margin-top:12px"><b>Восстановление почвы разделено на сезоны.</b><div class="muted small">Агроном не пытается закрыть весь накопленный дефицит за один урожай: текущая программа ограничена экономическим бюджетом урожая; минимальные технологические дозы могут дать отклонение от расчётного ориентира, а остаток плодородия восстанавливается последовательно.</div></div>`:''}<div class="divider"></div><div class="label">ЭТАПЫ ПИТАНИЯ</div>${steps||'<div class="rec good">Текущий запас уже закрывает расчётную потребность этой цели.</div>'}${future}${plan.lime.needed?`<div class="note info" style="margin-top:12px"><b>План pH на ${plan.lime.years} сезон(а)</b><div class="muted small">Всего требуется около ${num(plan.lime.total,1)} т/га извести; ориентир по ${num(plan.lime.annual,1)} т/га за сезон до pH ≈ ${num(plan.lime.target,1)}.</div></div>`:''}${excess>0?`<div class="note warnbox" style="margin-top:12px"><b>Риск перекорма азотом: ${Math.round(excess*100)}%</b><div class="muted small">Избыток N не превращается автоматически в урожай: он повышает риск полегания/болезней и может задержать созревание до ${Math.round(excess*5)} дн.</div></div>`:''}`}</div>`;}
function nutritionDashboardHtml(f,cropKey){if(!f?.owned)return'';const c=CROPS[cropKey]||CROPS.spring_wheat;if(!soilKnown(f))return`<div class="card section-card"><div class="section-title"><h2>Агрохимия и питание</h2><span class="status warn">Нужен анализ</span></div><div class="note warnbox">Без лабораторного анализа N/P/K, pH и органического вещества расчёт доз удобрений отключён. Закажите анализ — после получения результата здесь появится фактический запас, доступность элементов и дефицит под выбранную культуру.</div></div>`;const x=nutrientStatus(f,cropKey),l=ensureNutrientLedger(f),r=f.soilTest?.results||makeSoilTestResult(f,f.soilTest?.completedAt||state.gameTime),age=soilTestAgeYears(f),stale=soilTestStale(f),recs=fertilizerRecommendation(f,cropKey);const limLabel={N:'азот',P:'фосфор',K:'калий'}[x.limiting],status=x.score>=1?'good':x.score>=.82?'info':'warn';const recHtml=recs.length?recs.map(z=>{const fd=FERTS[z.op],cost=fertilizerCost(f,z.op,z.dose);return`<div class="rec info"><div><div class="muted tiny">${z.stage||'Текущее внесение'}</div><b>${fd.label} · ${z.dose} ${fd.unit}</b><div class="muted small">${z.reason}</div><div class="muted tiny">На всё поле: ${fd.unit==='т/га'?num(z.dose*f.ha,1)+' т':num(z.dose*f.ha,0)+' кг'} · ориентировочно ${rub(cost)}</div></div><button class="btn" data-fert-rec="${z.op}" data-field="${f.id}" data-dose="${z.dose}" data-crop="${cropKey}" ${opAllowed(f,z.op,cropKey).ok?'':`disabled title="${opAllowed(f,z.op,cropKey).label}"`}>Внести</button></div>`}).join(''):'<div class="rec good"><b>Дополнительное питание сейчас не требуется</b><div class="muted small">Расчётный доступный запас покрывает текущую фазу плана питания выбранной цели.</div></div>';return`<div class="card section-card nutrition-dashboard"><div class="section-title"><h2>Агрохимия и питание · ${c.label}</h2><span class="status ${status}">${x.score>=1?'Питание обеспечено':`Лимитирует ${limLabel}`}</span></div><div class="note ${stale?'warnbox':''}"><b>Лабораторная проба: ${shortDate(r.sampledAt||f.soilTest.completedAt)}</b><div class="muted small">Возраст ${num(age,1)} г.${stale?' · анализ старше '+SOIL_TEST_VALID_YEARS+' лет, точность рекомендаций снижена':''} · лаборатория: N ${num(r.N,0)} / P ${num(r.P,0)} / K ${num(r.K,0)} / pH ${num(r.ph,1)} / органика ${num(r.organicMatter,2)}%</div></div><div class="passport-grid" style="margin-top:12px"><div class="metric"><span class="label">ЦЕЛЬ УРОЖАЙНОСТИ</span><b>${num(x.target,2)} т/га</b></div><div class="metric"><span class="label">ПОТРЕБНОСТЬ N/P/K ПОД ЦЕЛЬ</span><b>${Math.round(x.needs.N)}/${Math.round(x.needs.P)}/${Math.round(x.needs.K)}</b></div><div class="metric"><span class="label">ДОСТУПНО СЕЙЧАС</span><b>${Math.round(x.q.N)}/${Math.round(x.q.P)}/${Math.round(x.q.K)}</b></div><div class="metric"><span class="label">ДЕФИЦИТ N/P/K</span><b>${Math.round(x.deficits.N)}/${Math.round(x.deficits.P)}/${Math.round(x.deficits.K)}</b></div><div class="metric"><span class="label">ДОСТУПНОСТЬ ИЗ-ЗА pH</span><b>${Math.round(x.q.availability.N*100)}/${Math.round(x.q.availability.P*100)}/${Math.round(x.q.availability.K*100)}%</b></div><div class="metric"><span class="label">АЗОТНЫЙ КРЕДИТ</span><b>${x.q.nCredit>=0?'+':''}${num(x.q.nCredit,1)}</b><span class="muted tiny">органика + предшественник − связывание соломой</span></div><div class="metric"><span class="label">pH</span><b>${num(f.soil.ph,1)}</b><span class="muted tiny">целевой для ${c.label}: ${c.ph[0]}–${c.ph[1]}</span></div></div><div class="divider"></div><div class="label">РЕКОМЕНДАЦИЯ НА ТЕКУЩИЙ МОМЕНТ</div>${recHtml}<div class="note" style="margin-top:12px"><b>Баланс ${l.year}</b><div class="muted small">Внесено N/P/K: ${num(l.applied.N,1)} / ${num(l.applied.P,1)} / ${num(l.applied.K,1)} · вынос урожаем: ${num(l.removed.N,1)} / ${num(l.removed.P,1)} / ${num(l.removed.K,1)} · минерализация N: +${num(l.mineralizedN,1)} · вымывание N: −${num(l.leachedN,1)}</div></div></div>`;}

function analysisBlock(f){const st=f.soilTest||{status:'none'};if(st.status==='pending')return`<div class="analysis-box"><div><b>Анализ выполняется</b><div class="muted small">N/P/K, pH и органика · результат: ${dateFmt(st.readyAt)}</div></div><span class="status info">${Math.max(1,daysBetween(state.gameTime,st.readyAt))} дн.</span></div>`;if(st.status==='done'){const r=st.results||makeSoilTestResult(f,st.completedAt||state.gameTime),age=soilTestAgeYears(f),stale=soilTestStale(f),a=nutrientAvailability(f.soil);return`<div class="analysis-box ${stale?'warnbox':''}"><div><b>${stale?'Анализ устарел':'Анализ почвы доступен'}</b><div class="muted small">Проба ${shortDate(r.sampledAt||st.completedAt)} · N ${num(r.N,0)} / P ${num(r.P,0)} / K ${num(r.K,0)} / pH ${num(r.ph,1)} / органика ${num(r.organicMatter,2)}%</div><div class="muted tiny">Возраст ${num(age,1)} г. · текущая расчётная доступность N/P/K: ${Math.round(a.N*100)} / ${Math.round(a.P*100)} / ${Math.round(a.K*100)}%${stale?' · для точных доз лучше повторить анализ':''}</div></div><button class="btn secondary" data-soil-test="${f.id}">Повторить · ${rub(f.ha*SOIL_TEST_COST)}</button></div>`;}return`<div class="analysis-box warnbox"><div><b>Показатели почвы неизвестны</b><div class="muted small">Лабораторный N/P/K + pH + органика: ${rub(SOIL_TEST_COST)}/га · срок ${SOIL_TEST_DAYS} дня</div></div><button class="btn" data-soil-test="${f.id}" ${state.money<f.ha*SOIL_TEST_COST?'disabled':''}>Заказать · ${rub(f.ha*SOIL_TEST_COST)}</button></div>`;}
function landPrice(f){return f.ha*(f.landProfile?.pricePerHa||CONFIG.hectarePrice)}
function meadowPrice(f){return f.ha*(f.landProfile?.pricePerHa||CONFIG.meadowPricePerHa)}
function meadowLeaseInitialCost(f){return Math.round(meadowPrice(f)*CONFIG.leaseUpfrontRate)+f.ha*CONFIG.meadowLeaseAnnualPerHa}
function meadowSaleValue(f){return Math.round(meadowPrice(f)*clamp(.92+(Number(f.meadowQuality)||.85)*.12,.92,1.06)/500)*500}
function buyMeadow(id){const f=(state.meadows||[]).find(x=>x.id===id);if(!f||f.owned)return;if(!f.landProfile?.marketListed||f.landProfile?.marketMode==='lease_only'){toast('Этот сенокос сейчас не продаётся');return;}const p=meadowPrice(f);if(state.money<p){toast('Недостаточно средств');return}state.money-=p;f.owned=true;f.tenure='owned';f.lease=null;f.landProfile.marketListed=false;f.landProfile.marketListedAt=null;f.landProfile.marketExpiresAt=null;f.meadowGrowthYear=new Date(state.gameTime).getFullYear();f.meadowGrowth=forageCutsThisYear(f)===0?meadowBaselineGrowth(state.gameTime,f.meadowQuality,f.moisture):meadowGrowthPct(f);finance('expense',p,'land',f.id,'Покупка сенокоса');recordField(f,'Сенокос приобретён хозяйством.');log(`Куплен сенокос ${fieldCode(f)}: ${f.ha} га за ${rub(p)}.`);save();render();toast('Сенокос приобретён')}
function leaseMeadow(id){const f=(state.meadows||[]).find(x=>x.id===id);if(!f||f.owned)return;if(!f.landProfile?.marketListed||f.landProfile?.marketMode==='buy_only'){toast('Этот сенокос сейчас недоступен для аренды');return;}const market=meadowPrice(f),upfront=Math.round(market*CONFIG.leaseUpfrontRate),annual=f.ha*CONFIG.meadowLeaseAnnualPerHa,initial=upfront+annual;if(state.money<initial){toast('Недостаточно средств для аренды сенокоса');return}state.money-=initial;f.owned=true;f.tenure='leased';f.landProfile.marketListed=false;f.landProfile.marketListedAt=null;f.landProfile.marketExpiresAt=null;f.meadowGrowthYear=new Date(state.gameTime).getFullYear();f.meadowGrowth=forageCutsThisYear(f)===0?meadowBaselineGrowth(state.gameTime,f.meadowQuality,f.moisture):meadowGrowthPct(f);f.lease={startAt:state.gameTime,endAt:addYears(state.gameTime,CONFIG.leaseYears),nextPaymentAt:addYears(state.gameTime,1),annual,upfront,paidYears:1};finance('expense',upfront,'land_lease',f.id,`Аренда сенокоса на ${CONFIG.leaseYears} лет · вступительный платёж 10%`);finance('expense',annual,'land_rent',f.id,`Аренда сенокоса · первый год · ${rub(CONFIG.meadowLeaseAnnualPerHa)}/га`);recordField(f,`Сенокос взят в аренду на ${CONFIG.leaseYears} лет.`);log(`${fieldCode(f)} арендован на ${CONFIG.leaseYears} лет.`);save();render();toast('Аренда сенокоса оформлена')}
function sellMeadow(id){const f=(state.meadows||[]).find(x=>x.id===id);if(!f||!f.owned||f.tenure==='leased')return;if(f.forageProcess||taskFor(f.id)){toast('Сначала завершите сенозаготовку');return}const value=meadowSaleValue(f);if(!confirm(`Продать ${fieldCode(f)} за ${rub(value)}?`))return;state.money+=value;finance('income',value,'land_sale',f.id,'Продажа сенокоса');f.owned=false;f.tenure=null;f.landProfile.marketListed=false;f.landProfile.marketListedAt=null;f.landProfile.marketExpiresAt=null;recordField(f,`Сенокос продан за ${rub(value)}.`);save();render()}
function returnLeasedMeadow(id){const f=(state.meadows||[]).find(x=>x.id===id);if(!f||!f.owned||f.tenure!=='leased')return;if(f.forageProcess||taskFor(f.id)){toast('Сначала завершите сенозаготовку');return}if(!confirm(`Вернуть ${fieldCode(f)} арендодателю?`))return;f.owned=false;f.tenure=null;f.lease=null;f.landProfile.marketListed=false;f.landProfile.marketListedAt=null;f.landProfile.marketExpiresAt=null;recordField(f,'Сенокос возвращён арендодателю.');save();render()}
function renewMeadowLease(id){const f=(state.meadows||[]).find(x=>x.id===id);if(!f||!f.owned||f.tenure!=='leased'||!f.lease)return;const annual=f.ha*CONFIG.meadowLeaseAnnualPerHa;if(state.money<annual){toast(`Для продления нужно ${rub(annual)}`);return}if(!confirm(`Продлить аренду ${fieldCode(f)} ещё на ${CONFIG.leaseYears} лет?`))return;state.money-=annual;finance('expense',annual,'land_rent',f.id,'Продление аренды сенокоса');const start=Math.max(state.gameTime,f.lease.endAt||state.gameTime);f.lease={...f.lease,startAt:start,endAt:addYears(start,CONFIG.leaseYears),nextPaymentAt:addYears(start,1),annual,paidYears:1,expired:false,renewalNotice:false};save();render()}

function sizeBand(f){return f.ha<=10?'small':f.ha<=50?'medium':'large'}
function fieldMarketNote(f){const lp=f.landProfile||{};if(lp.status==='abandoned')return`Не обрабатывалось ~${lp.yearsIdle||3} лет · высокий объём подготовительных работ`;if(lp.status==='fallow')return`Пар ${lp.yearsIdle||1} сезон · низкая засорённость, хорошая база для ввода в оборот`;return`${lp.previousCrop&&CROPS[lp.previousCrop]?CROPS[lp.previousCrop].label:'Рабочий севооборот'} · ${lp.marketYear?`сезон ${lp.marketYear}`:'регулярно обрабатывалось'}`;}
function filteredLand(){let rows=state.fields.filter(x=>landView==='owned'?x.owned:(!x.owned&&x.landProfile?.marketListed&&!x.landProfile?.holdingId));const f=landFilters;if(landView!=='owned'&&f.deal!=='all')rows=rows.filter(x=>(x.landProfile?.marketMode||'both')===f.deal);if(f.size!=='all')rows=rows.filter(x=>sizeBand(x)===f.size);if(f.status!=='all')rows=rows.filter(x=>(x.landProfile?.status||'working')===f.status);if(f.crop!=='all')rows=rows.filter(x=>f.crop==='none'?!x.landProfile?.previousCrop:x.landProfile?.previousCrop===f.crop);if(f.price!=='all')rows=rows.filter(x=>{const p=x.landProfile?.pricePerHa||CONFIG.hectarePrice;return f.price==='discount'?p<CONFIG.hectarePrice*.9:f.price==='premium'?p>CONFIG.hectarePrice*1.05:p>=CONFIG.hectarePrice*.9&&p<=CONFIG.hectarePrice*1.05;});if(f.query){const q=f.query.trim().toLowerCase();rows=rows.filter(x=>fieldCode(x).toLowerCase().includes(q)||String(x.ha).includes(q));}rows.sort((a,b)=>f.sort==='sizeAsc'?a.ha-b.ha:f.sort==='sizeDesc'?b.ha-a.ha:f.sort==='priceAsc'?landPrice(a)-landPrice(b):f.sort==='priceDesc'?landPrice(b)-landPrice(a):f.sort==='distanceAsc'?(a.distanceKm||0)-(b.distanceKm||0):f.sort==='distanceDesc'?(b.distanceKm||0)-(a.distanceKm||0):f.sort==='status'?(a.landProfile?.status||'').localeCompare(b.landProfile?.status||''):a.id-b.id);return rows;}
function leaseAlertRow(f){const expired=!!f.lease?.expired,days=Math.max(0,daysBetween(state.gameTime,f.lease?.endAt||state.gameTime));return `<div class="rec warn"><div><b>${fieldCode(f)} · ${f.ha} га</b><div class="small">${expired?'Срок аренды завершён. Продлите договор или верните участок на рынок.':`До окончания договора: ${days} дн.`}</div><div class="muted tiny">Продление ещё на ${CONFIG.leaseYears} лет · первый год ${rub(f.ha*CONFIG.leaseAnnualPerHa)}</div></div><div class="row-actions"><button class="btn" data-renew-lease="${f.id}">Продлить</button><button class="btn secondary" data-return-lease="${f.id}" ${f.crop||taskFor(f.id)?'disabled':''}>Не продлевать / вернуть</button></div></div>`;}
function ownedFieldRow(f){let cropCell='<span class="muted">Свободно · предшественник: '+(f.lastCrop&&CROPS[f.lastCrop]?CROPS[f.lastCrop].label:'—')+'</span>';if(f.crop){const h=harvestWindowInfo(f);cropCell=cropProgressHtml(f)+(h?`<div class="muted tiny">${h.status} · ${h.detail}</div>`:'');}const tenure=f.tenure==='leased'?`<span class="status info">Аренда</span><div class="muted tiny">до ${shortDate(f.lease?.endAt)}</div>`:'<span class="status good">Собственность</span>';return `<tr><td><button class="field-link" data-field-detail="${f.id}">${fieldCode(f)}</button><div class="muted tiny">${landClusterLabel(f)}</div></td><td>${f.ha} га</td><td>${tenure}</td><td>${cropCell}</td><td><b>${num(f.distanceKm||0,1)} км</b></td><td>${moistureHtml(f)}</td><td>${f.crop?num(projectedYieldPerHa(f),2)+' т/га':'—'}</td><td><button class="btn secondary" data-field-detail="${f.id}">Карточка</button></td></tr>`;}
function marketFieldRow(f){const p=landPrice(f),pph=f.landProfile?.pricePerHa||CONFIG.hectarePrice,lease=leaseInitialCost(f),mode=f.landProfile?.marketMode||'both',canBuy=mode!=='lease_only',canLease=mode!=='buy_only';return `<tr><td><button class="field-link" data-field-detail="${f.id}">${fieldCode(f)}</button><div class="muted tiny">${landClusterLabel(f)} · ещё ~${landListingDaysLeft(f)} дн.</div></td><td>${f.ha} га</td><td><span class="status ${landStatusClass(f)}">${landStatusLabel(f)}</span><div><span class="status ${landMarketModeClass(mode)}">${landMarketModeLabel(mode)}</span></div></td><td>${fieldMarketNote(f)}</td><td><b>${num(f.distanceKm||0,1)} км</b><div class="muted tiny">перегон + логистика</div></td><td>${rub(pph)}</td><td>${canBuy?`<b>${rub(p)}</b>`:'<span class="muted">—</span>'}</td><td>${canLease?`<b>${rub(lease)}</b><div class="muted tiny">вход + 1-й год · сумма аренды ≈ цене покупки через ${num(landLeaseBreakEvenYears(f),1)} лет${landRecoveryWarning(f)}</div>`:'<span class="muted">—</span>'}</td><td class="right"><button class="btn secondary" data-field-detail="${f.id}">Осмотреть</button> ${canBuy?`<button class="btn" data-buy="${f.id}" ${state.money<p?'disabled':''}>Купить</button>`:''} ${canLease?`<button class="btn secondary" data-lease="${f.id}" ${state.money<lease?'disabled':''}>Арендовать</button>`:''}</td></tr>`;}

function filteredMeadows(){
 let rows=(state.meadows||[]).filter(x=>landView==='owned'?x.owned:(!x.owned&&x.landProfile?.marketListed)),f=meadowFilters;
 if(landView!=='owned'&&f.deal!=='all')rows=rows.filter(x=>(x.landProfile?.marketMode||'both')===f.deal);
 if(f.size!=='all')rows=rows.filter(x=>sizeBand(x)===f.size);
 if(f.price!=='all')rows=rows.filter(x=>{const p=x.landProfile?.pricePerHa||CONFIG.meadowPricePerHa;return f.price==='discount'?p<CONFIG.meadowPricePerHa*.9:f.price==='premium'?p>CONFIG.meadowPricePerHa*1.05:p>=CONFIG.meadowPricePerHa*.9&&p<=CONFIG.meadowPricePerHa*1.05;});
 if(f.query){const q=f.query.trim().toLowerCase();rows=rows.filter(x=>fieldCode(x).toLowerCase().includes(q)||String(x.ha).includes(q));}
 rows.sort((a,b)=>f.sort==='sizeAsc'?a.ha-b.ha:f.sort==='sizeDesc'?b.ha-a.ha:f.sort==='priceAsc'?meadowPrice(a)-meadowPrice(b):f.sort==='priceDesc'?meadowPrice(b)-meadowPrice(a):f.sort==='distanceAsc'?(a.distanceKm||0)-(b.distanceKm||0):f.sort==='distanceDesc'?(b.distanceKm||0)-(a.distanceKm||0):a.id-b.id);
 return rows;
}
function meadowOwnedTableRow(f){
 const p=f.forageProcess,m=p?forageMoistureNow(p):null,cuts=forageCutsThisYear(f),stage=p?(p.stage==='mown'?'Скошено · сушится':p.stage==='tedded'?'Проворошено':p.stage==='windrow'?'Валок':p.stage==='baled'?'Тюки готовы':p.stage):'Дикая трава';
 const lease=f.tenure==='leased'?`Аренда до ${shortDate(f.lease?.endAt)}`:'Собственность';
 return `<tr><td><b>${fieldCode(f)}</b><div class="muted tiny">${landClusterLabel(f)}</div></td><td>${f.ha} га</td><td><span class="status ${f.tenure==='leased'?'info':'good'}">${lease}</span></td><td><b>${stage}</b><div class="muted tiny">укосов ${cuts}/2 · качество ${Math.round((f.meadowQuality||.85)*100)}% · рост ${Math.round(meadowGrowthPct(f))}/100</div></td><td>${num(f.distanceKm,1)} км</td><td>${m==null?moistureHtml(f):num(m,1)+'%'}</td><td>${p?num(p.tons||0,1)+' т':'—'}</td><td><details class="service-menu"><summary class="btn secondary compact">Работы</summary><div style="min-width:560px;max-width:720px">${meadowOwnedCard(f)}</div></details></td></tr>`;
}
function meadowMarketRow(f){
 const pp=f.landProfile?.pricePerHa||CONFIG.meadowPricePerHa,buy=meadowPrice(f),annual=f.ha*CONFIG.meadowLeaseAnnualPerHa,initial=meadowLeaseInitialCost(f),mode=f.landProfile?.marketMode||'both',canBuy=mode!=='lease_only',canLease=mode!=='buy_only';
 return `<tr><td><b>${fieldCode(f)}</b><div class="muted tiny">${landClusterLabel(f)} · ещё ~${meadowListingDaysLeft(f)} дн.</div></td><td>${f.ha} га</td><td><span class="status good">Естественный луг</span><div><span class="status ${landMarketModeClass(mode)}">${landMarketModeLabel(mode)}</span></div></td><td>Качество ${Math.round((f.meadowQuality||.85)*100)}%<div class="muted tiny">дикая луговая трава</div></td><td>${num(f.distanceKm,1)} км</td><td>${rub(pp)}</td><td>${canBuy?`<b>${rub(buy)}</b><div><button class="btn compact" data-buy-meadow="${f.id}" ${state.money<buy?'disabled':''}>Купить</button></div>`:'<span class="muted">—</span>'}</td><td>${canLease?`<b>${rub(annual)}/год</b><div class="muted tiny">вход ${rub(initial)} · аренда ≈ цене покупки через ${num(landLeaseBreakEvenYears(f),1)} лет</div><button class="btn secondary compact" data-lease-meadow="${f.id}" ${state.money<initial?'disabled':''}>Арендовать</button>`:'<span class="muted">—</span>'}</td></tr>`;
}

