 const transitStatus=l=>{if(l.storageWaiting)return{label:'Не может разгрузиться',cls:'bad',detail:'буфер/секция заполнены'};if(!l.intakeQueued)return{label:'Едет на базу',cls:'info',detail:`прибытие ${dateFmt(l.readyAt)}`};if(state.gameTime<(Number(l.intakeStartedAt)||0))return{label:'Ждёт приёмку',cls:'warn',detail:`начало ${dateFmt(l.intakeStartedAt)}`};return{label:'На приёмке',cls:'good',detail:`освободит линию ${dateFmt(l.readyAt)}`}};
