 document.querySelectorAll('[data-contract-primary]').forEach(sel=>sel.addEventListener('change',()=>{const c=state.contracts.active.find(x=>x.id===contractPicker?.contractId),i=+sel.dataset.contractPrimary,t=contractPicker?.ownTeams?.[i];if(!c||!t)return;t.primaryId=sel.value;const all=contractFreeUnits(c),used=new Set();contractPicker.ownTeams.forEach((x,j)=>{if(j!==i){if(x.primaryId)used.add(x.primaryId);if(x.secondaryId)used.add(x.secondaryId);}});const u=all.find(x=>x.assets[0]?.id===t.primaryId&&!x.assets.slice(1).some(a=>used.has(a.id)));t.secondaryId=u?.assets[1]?.id||'';renderPreservingViewport();}));
