document.getElementById('nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b)return;navigatePage(b.dataset.page);render();});
function advanceGameTimeTo(target,maxChunkH=6){if(!state)return 0;let cursor=state.gameTime,guard=0;const chunk=Math.max(.25,Number(maxChunkH)||6)*3600000;realtimeAdvanceDepth++;try{while(cursor<target-1&&guard++<20000){const before=cursor,step=Math.min(target,cursor+chunk),next=advanceSystems(cursor,step);cursor=Math.min(target,Number(next));state.gameTime=cursor;if(!Number.isFinite(cursor)||cursor<=before||cursor<step-1||state.criticalAlert)break;}}finally{realtimeAdvanceDepth--;}return state.gameTime;}
function advanceRealtimeClock(now=Date.now(),flush=false){if(!state){lastReal=now;return 0}const elapsed=Math.max(0,now-lastReal);lastReal=now;if(speed<=0||elapsed<=0)return 0;realtimeMinuteRemainderMs+=elapsed*speed*60;let minutes=Math.floor(realtimeMinuteRemainderMs/60000);if(minutes<=0)return 0;let advanced=0,guard=0;realtimeAdvanceDepth++;try{while(minutes>0&&guard++<500){const realtimeChunkMin=flush?60:(speed<=60?1:speed<=240?4:24),stepMin=Math.min(minutes,realtimeChunkMin),before=state.gameTime,target=before+stepMin*60000,next=advanceSystems(before,target),actual=Math.max(0,Number(next)-before);state.gameTime=Number(next);const consumed=Math.min(stepMin*60000,actual>0?actual:stepMin*60000);realtimeMinuteRemainderMs=Math.max(0,realtimeMinuteRemainderMs-consumed);advanced+=actual;if(!Number.isFinite(state.gameTime)||state.gameTime<=before||state.gameTime<target-1||state.criticalAlert||speed<=0){if(state.criticalAlert||speed<=0)realtimeMinuteRemainderMs=0;break;}minutes=Math.floor(realtimeMinuteRemainderMs/60000);}}finally{realtimeAdvanceDepth--;}return advanced;}
function setGameSpeed(v){const now=Date.now();if(realtimeAdvanceDepth===0)advanceRealtimeClock(now,true);else lastReal=now;const n=Number(v);speed=Number.isFinite(n)&&n>=0?n:1;if(speed>0)lastNonZeroSpeed=speed;document.querySelectorAll('[data-speed]').forEach(x=>x.classList.toggle('active',Number(x.dataset.speed)===speed));try{sessionStorage.setItem('agroGameSpeed',String(speed));}catch{}}
window.setGameSpeed=setGameSpeed;
function skipDays(days){const n=Math.floor(Number(days));if(!Number.isFinite(n)||n<=0||!state)return;if(state.criticalAlert){setGameSpeed(0);render();toast('Сначала завершите текущее событие');return}advanceRealtimeClock(Date.now(),true);const target=state.gameTime+n*DAY;advanceGameTimeTo(target,1);lastReal=Date.now();realtimeMinuteRemainderMs=0;save();render();if(state.gameTime<target)toast(`Перемотка остановлена: ${dateFmt(state.gameTime)}`);else toast(`Перемотано на ${n} дн.`)}
document.querySelectorAll('[data-speed]').forEach(b=>b.addEventListener('click',()=>{setGameSpeed(b.dataset.speed);try{b.blur();}catch{}}));
document.addEventListener('keydown',e=>{if(e.repeat)return;const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)||document.activeElement?.isContentEditable)return;const speeds={Digit1:1,Digit2:5,Digit3:20,Digit4:60,Digit5:240,Digit6:1440};if(e.code==='Space'){e.preventDefault();setGameSpeed(speed===0?(lastNonZeroSpeed||1):0);toast(speed===0?'Пауза':`Скорость ×${speed}`);return}if(speeds[e.code]){e.preventDefault();setGameSpeed(speeds[e.code]);toast(speeds[e.code]===1440?'Скорость 1 день/с':`Скорость ×${speeds[e.code]}`);return}if(e.code==='Digit7'||e.code==='Digit8'){e.preventDefault();skipDays(e.code==='Digit7'?5:10);}});
document.querySelectorAll('[data-skip]').forEach(b=>b.addEventListener('click',()=>skipDays(+b.dataset.skip)));
try{const savedSpeed=Number(sessionStorage.getItem('agroGameSpeed'));if(Number.isFinite(savedSpeed)&&[0,1,5,20,60,240,1440].includes(savedSpeed))setGameSpeed(savedSpeed);}catch{}if(state?.criticalAlert)setGameSpeed(0);
(async function keepLauncherSession(){try{const r=await fetch('/session',{cache:'no-store'});if(!r.body)return;const reader=r.body.getReader();while(true){const {done}=await reader.read();if(done)break;}}catch{}})();
document.getElementById('manualSaveBtn').addEventListener('click',manualSave);
document.getElementById('manualLoadBtn').addEventListener('click',manualLoad);
document.getElementById('resetBtn').addEventListener('click',()=>{if(confirm('Начать новую игру? Текущее автосохранение будет заменено новой игрой. Ручное сохранение сохраняется, пока вы не перезапишете его.')){state=freshState(null);setGameSpeed(1);save();render();toast('Выберите сложность новой игры');}});
document.getElementById('exitBtn').addEventListener('click',async()=>{try{if(fileSaveTimer){clearTimeout(fileSaveTimer);fileSaveTimer=null;}const saved=await writeFileSave('autosave');if(!saved){toast('Не удалось сохранить игру. Выход отменён — повторите сохранение или проверьте доступ к папке saves.');return;}const q=await fetch('/quit',{method:'POST'});if(!q.ok)throw new Error(`HTTP ${q.status}`);document.body.innerHTML='<div style="font:18px Segoe UI,Arial;color:#edf5ef;background:#0d1310;min-height:100vh;display:grid;place-items:center">AgroManager завершён. Состояние сохранено. Эту вкладку можно закрыть.</div>';}catch(e){console.warn('Exit failed',e);toast('Не удалось корректно завершить игру. Окно оставлено открытым.');}});
function interactionAnchorSnapshot(){
 const el=document?.activeElement;if(!el||!el.dataset)return null;const keys=['shiftHours','shiftCount','workerKey','workerShiftKey','contractShiftCount','ownPrimary','ownSecondary','ownTeamAdd','pickerMode','pickerHybrid','contractorTier','transportContractorTier','pickerLogistics','saleMode','saleContractorTier'];for(const k of keys){if(el.dataset[k]!==undefined)return{key:k,value:String(el.dataset[k]),top:el.getBoundingClientRect?.().top};}return null;
}
function restoreInteractionAnchor(a){if(!a||!Number.isFinite(a.top))return false;try{const attr='data-'+a.key.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()),els=[...document.querySelectorAll('['+attr+']')],el=els.find(x=>String(x.dataset?.[a.key])===a.value);if(!el?.getBoundingClientRect)return false;const delta=el.getBoundingClientRect().top-a.top;if(Math.abs(delta)>.5)window?.scrollBy?.(0,delta);return true;}catch{return false;}}
function renderPreservingViewport(){const x=Number(window?.scrollX)||0,y=Number(window?.scrollY)||0,focusAnchor=interactionAnchorSnapshot(),openFieldIds=[...document.querySelectorAll('details.operation-field[open]')].map(d=>Number(d.querySelector('[data-field-detail]')?.dataset.fieldDetail)).filter(Number.isFinite),openOther=[...document.querySelectorAll('#content details')].filter(d=>!d.classList?.contains('operation-field')).map((d,i)=>d.open?i:null).filter(i=>i!==null),anchor=document?.querySelector?.('.machinery-picker,.contract-picker'),anchorTop=anchor?.getBoundingClientRect?.().top;render();for(const id of openFieldIds){const d=[...document.querySelectorAll('details.operation-field')].find(x=>Number(x.querySelector('[data-field-detail]')?.dataset.fieldDetail)===id);if(d)d.open=true;}const other=[...document.querySelectorAll('#content details')].filter(d=>!d.classList?.contains('operation-field'));for(const i of openOther)if(other[i])other[i].open=true;let passes=0;const restore=()=>{try{if(restoreInteractionAnchor(focusAnchor)){}else{const next=document?.querySelector?.('.machinery-picker,.contract-picker');if(Number.isFinite(anchorTop)&&next?.getBoundingClientRect){const delta=next.getBoundingClientRect().top-anchorTop;if(Math.abs(delta)>.5)window?.scrollBy?.(0,delta);else window?.scrollTo?.(x,y);}else window?.scrollTo?.(x,y);}}catch{}if(++passes<2&&typeof requestAnimationFrame==='function')requestAnimationFrame(restore);};if(typeof requestAnimationFrame==='function')requestAnimationFrame(restore);else restore();}
function renderPreservingBankDetails(){const ds=[...document.querySelectorAll('details.bank-group')],open=ds.map(d=>d.open),x=Number(window?.scrollX)||0,y=Number(window?.scrollY)||0;render();document.querySelectorAll('details.bank-group').forEach((d,i)=>d.open=!!open[i]);try{window?.scrollTo?.(x,y);}catch{}}
let uiInteractionUntil=0;
function markUiInteraction(ms=350){uiInteractionUntil=Math.max(uiInteractionUntil,Date.now()+ms);}
function uiInteractionActive(){if(tutorialOverlayActive())return true;const a=document.activeElement,tag=a?.tagName;if(Date.now()<uiInteractionUntil)return true;const inContent=!!a?.closest?.('#content');if(inContent&&(['INPUT','TEXTAREA','SELECT','BUTTON','SUMMARY'].includes(tag)||a?.isContentEditable))return true;try{if(document.querySelector('#content button:hover,#content input:hover,#content select:hover,#content summary:hover,#content a:hover,#content tr:hover'))return true;}catch{}if(operationPicker||contractPicker||salePicker)return true;return false;}
document.addEventListener('pointerdown',()=>markUiInteraction(220));for(const ev of ['input','change'])document.addEventListener(ev,e=>{markUiInteraction(350);if(ev==='change'&&e?.target?.tagName==='SELECT'){const sel=e.target;setTimeout(()=>{try{if(document.activeElement===sel)sel.blur()}catch{}},0);}});
function refreshLiveUi(now=Date.now()){if(now-lastUiRefreshReal<100)return;lastUiRefreshReal=now;renderTop();const interactiveActive=uiInteractionActive();if(now-lastRealtimeSave>=1000){lastRealtimeSave=now;save();}if(now-(refreshLiveUi.lastContent||0)<250)return;refreshLiveUi.lastContent=now;if(page==='financing'&&!interactiveActive)renderPreservingBankDetails();else if(['dashboard','management','operations','agroPlan','processes','fieldDetail','agronomy','calendar','weather','finance','materials','market','contracts','outsideWork','deliveryContracts','warehouse','infrastructure','staff'].includes(page)&&!interactiveActive)renderPreservingViewport();if((page==='equipment'||page==='equipmentDetail')&&equipmentUiRevision!==lastRenderedEquipmentRevision&&!interactiveActive){lastRenderedEquipmentRevision=equipmentUiRevision;renderPreservingViewport();}}
function realtimeFrame(){const now=Date.now();advanceRealtimeClock(now,false);refreshLiveUi(now);if(typeof requestAnimationFrame==='function')requestAnimationFrame(realtimeFrame);else setTimeout(realtimeFrame,16);}
lastReal=Date.now();if(typeof requestAnimationFrame==='function')requestAnimationFrame(realtimeFrame);else setTimeout(realtimeFrame,16);
save();render();updateSaveStatus(fileSaveLoadInfo.recovered?'автовосстановление':'');
